def ask_scan_start(parent, title, question, expected, warning='', **_options) -> bool:
    top = tk.Toplevel(parent)
    top.title(title)
    top.transient(parent)
    top.resizable(False, False)
    body = ttk.Frame(top, padding=18)
    body.grid(row=0, column=0, sticky='nsew')
    base = tkfont.nametofont('TkDefaultFont')
    size = int(base.cget('size'))
    big = base.copy()
    big.configure(weight='bold', size=round(size * 1.4))
    row = 0
    if warning:
        ttk.Label(body, text=warning, foreground='#b00020', wraplength=460, justify='left').grid(row=0, column=0, columnspan=2, sticky='w', pady=(0, 12))
        row = 1
    ttk.Label(body, text='Expected scan time:').grid(row=row, column=0, columnspan=2, sticky='w')
    ttk.Label(body, text=expected, foreground='#d00000', font=big).grid(row=row + 1, column=0, columnspan=2, sticky='w', pady=(4, 12))
    ttk.Label(body, text='Is this time OK? Start the scan?').grid(row=row + 2, column=0, columnspan=2, sticky='w', pady=(0, 14))
    answer = [False]
    def close(value: bool) -> None:
        answer[0] = value
        top.grab_release()
        top.destroy()
    yes = ttk.Button(body, text='Yes', width=10, command=lambda: close(True))
    yes.grid(row=row + 3, column=0, sticky='e', padx=(0, 8))
    ttk.Button(body, text='No', width=10, command=lambda: close(False)).grid(row=row + 3, column=1, sticky='w')
    body.columnconfigure(0, weight=1)
    top.protocol('WM_DELETE_WINDOW', lambda: close(False))
    top.bind('<Escape>', lambda _event: close(False))
    top.bind('<Return>', lambda _event: close(True))
    top.ask_scan_start_font = big
    top.update_idletasks()
    try:
        x = parent.winfo_rootx() + max(0, (parent.winfo_width() - top.winfo_reqwidth()) // 2)
        y = parent.winfo_rooty() + max(0, (parent.winfo_height() - top.winfo_reqheight()) // 3)
        top.geometry(f'+{x}+{y}')
    except tk.TclError:
        pass
    yes.focus_set()
    top.grab_set()
    top.wait_window()
    return answer[0]
def show_trimmed(label, variable) -> None:
    if not isinstance(label, tk.Widget):
        label.configure(textvariable=variable)
        return
    spec = str(label.cget('font')) or ttk.Style(label).lookup(label.winfo_class(), 'font') or 'TkDefaultFont'
    def measure(text: str) -> int:
        return int(label.tk.call("font", "measure", spec, "-displayof", label, text))
    def refresh(*_args) -> None:
        try:
            text = str(variable.get())
            room = label.winfo_width()
            if room <= 1 or measure(text) <= room:
                shown = text
            else:
                low, high = 0, len(text)
                while low < high:
                    middle = (low + high + 1) // 2
                    if measure(text[:middle].rstrip() + "…") <= room:
                        low = middle
                    else:
                        high = middle - 1
                shown = text[:low].rstrip() + "…"
            if str(label.cget("text")) != shown:
                label.configure(text=shown)
        except tk.TclError:
            pass
    variable.trace_add("write", refresh)
    label.bind("<Configure>", refresh, add="+")
    refresh()
LOCKIN_DOWNRANGE_READINGS = 3
PPMS_ZURICH_MODE_ORDERS = dict(DEFAULT_HARMONIC_MODE_ORDERS)
NONLOCAL_MFLI_API_LEVEL = 5
NONLOCAL_MFLI_DEMODULATOR = 0
NONLOCAL_MFLI_EXTREF_DEMODULATOR = 1
NONLOCAL_MFLI_EXTREF_CHANNEL = 0
NONLOCAL_MFLI_LEGACY_PYTHON_ENV = "MOKE_MFLI_PYTHON"
NONLOCAL_DEFAULT_KEITHLEY_MODEL = "2400"
NONLOCAL_VI_MAX_ABS_PULSE_V = 20.0
NONLOCAL_VI_2410_SOURCE_OVP_V = 20.0
NONLOCAL_KEITHLEY_DISCHARGE_S = 1.0
NONLOCAL_KEITHLEY_DRAIN_MAX_S = 30.0
NONLOCAL_KEITHLEY_SAMPLE_INTERVAL_S = 0.2
NONLOCAL_VI_2410_CURRENT_COMPLIANCE_A = KEITHLEY_DEFAULT_COMPLIANCE_A
_INSTRUMENT_LEASE_LOCK = threading.RLock()
_INSTRUMENT_LEASES: dict[str, tuple[object, str]] = {}
_SHARED_VISA_MANAGER_LOCK = threading.RLock()
_SHARED_VISA_MANAGER = None
_SHARED_VISA_MANAGER_USERS = 0
def acquire_shared_visa_manager():
    global _SHARED_VISA_MANAGER, _SHARED_VISA_MANAGER_USERS
    if pyvisa is None:
        raise RuntimeError('pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py')
    with _SHARED_VISA_MANAGER_LOCK:
        manager = _SHARED_VISA_MANAGER
        if manager is not None:
            try:
                manager.session
            except BaseException as error:
                if _SHARED_VISA_MANAGER_USERS:
                    raise RuntimeError('The shared VISA resource manager session became invalid unexpectedly; please close the instruments that still show as connected and reconnect') from error
                _SHARED_VISA_MANAGER = None
                manager = None
        if manager is None:
            manager = pyvisa.ResourceManager()
            manager.session
            _SHARED_VISA_MANAGER = manager
        _SHARED_VISA_MANAGER_USERS += 1
        return manager
def release_shared_visa_manager(manager) -> None:
    global _SHARED_VISA_MANAGER, _SHARED_VISA_MANAGER_USERS
    if manager is None:
        return
    with _SHARED_VISA_MANAGER_LOCK:
        if manager is not _SHARED_VISA_MANAGER:
            return
        _SHARED_VISA_MANAGER_USERS = max(0, _SHARED_VISA_MANAGER_USERS - 1)
        if _SHARED_VISA_MANAGER_USERS == 0:
            try:
                manager.close()
            except BaseException:
                pass
            finally:
                _SHARED_VISA_MANAGER = None
def instrument_lease_key(resource: str) -> str:
    key = str(resource).strip().upper()
    match = re.fullmatch(r"GPIB(\d*)::(\d+)(?:::(\d+))?(?:::INSTR)?", key)
    if match:
        board, primary, secondary = match.groups()
        key = f"GPIB{int(board or '0')}::{int(primary)}"
        if secondary is not None:
            key += f"::{int(secondary)}"
        key += "::INSTR"
    return key
INSTRUMENT_LEASE_TEXT_BYTES = 512
INSTRUMENT_LEASE_PROGRAM = Path(sys.argv[0]).stem or 'Transport'
def _process_instrument_leases() -> dict:
    return sys.__dict__.setdefault('_transport_instrument_process_leases', {})
def _process_instrument_lease_lock():
    return sys.__dict__.setdefault('_transport_instrument_process_lease_lock', threading.RLock())
def _instrument_lease_object_name(key: str) -> str:
    return 'TransportInstrumentLease_' + re.sub('[^A-Za-z0-9]+', '_', key)
def hold_instrument_for_this_process(key: str, owner_label: str):
    text = f'{INSTRUMENT_LEASE_PROGRAM} / {owner_label} (process {os.getpid()})'.encode('utf-8')[:INSTRUMENT_LEASE_TEXT_BYTES - 1]
    name = _instrument_lease_object_name(key)
    holder = None
    if sys.platform == 'win32':
        try:
            kernel = ctypes.WinDLL('kernel32', use_last_error=True)
            kernel.CreateFileMappingW.restype = ctypes.c_void_p
            kernel.CreateFileMappingW.argtypes = (ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_wchar_p)
            kernel.MapViewOfFile.restype = ctypes.c_void_p
            kernel.MapViewOfFile.argtypes = (ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_size_t)
            kernel.UnmapViewOfFile.argtypes = (ctypes.c_void_p,)
            kernel.CloseHandle.argtypes = (ctypes.c_void_p,)
            ctypes.set_last_error(0)
            handle = kernel.CreateFileMappingW(ctypes.c_void_p(-1), None, 4, 0, INSTRUMENT_LEASE_TEXT_BYTES, 'Local\\' + name)
            error = ctypes.get_last_error()
        except Exception:
            return None
        if not handle:
            if error == 5:
                raise RuntimeError('a program run with other Windows rights, e.g. as administrator')
            return None
        if error != 183:
            view = kernel.MapViewOfFile(handle, 6, 0, 0, INSTRUMENT_LEASE_TEXT_BYTES)
            if view:
                ctypes.memmove(view, text + b'\0', len(text) + 1)
                kernel.UnmapViewOfFile(view)
            return ('win32', handle)
        holder = ''
        try:
            view = kernel.MapViewOfFile(handle, 4, 0, 0, INSTRUMENT_LEASE_TEXT_BYTES)
            if view:
                try:
                    holder = ctypes.string_at(view, INSTRUMENT_LEASE_TEXT_BYTES).split(b'\0', 1)[0].decode('utf-8', 'replace')
                finally:
                    kernel.UnmapViewOfFile(view)
        finally:
            kernel.CloseHandle(handle)
    else:
        try:
            import fcntl
            import tempfile
            folder = Path(tempfile.gettempdir()) / 'Transport_instrument_leases'
            folder.mkdir(parents=True, exist_ok=True)
            handle = open(folder / (name + '.lock'), 'a+', encoding='utf-8')
        except (OSError, ImportError):
            return None
        try:
            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            try:
                handle.seek(0)
                holder = handle.read(INSTRUMENT_LEASE_TEXT_BYTES).strip()
            except OSError:
                holder = ''
            handle.close()
        else:
            try:
                handle.seek(0)
                handle.truncate()
                handle.write(text.decode('utf-8', 'replace'))
                handle.flush()
            except OSError:
                pass
            return ('file', handle)
    raise RuntimeError(holder or 'another program')
def let_go_of_instrument_for_this_process(token) -> None:
    if token is None:
        return
    kind, handle = token
    try:
        if kind == 'win32':
            ctypes.WinDLL('kernel32').CloseHandle(ctypes.c_void_p(handle))
        else:
            handle.close()
    except (OSError, AttributeError):
        pass
def acquire_instrument_lease(resource: str, owner: object, owner_label: str) -> str:
    key = instrument_lease_key(resource)
    if not key:
        raise ValueError("The instrument resource address cannot be empty")
    with _INSTRUMENT_LEASE_LOCK:
        current = _INSTRUMENT_LEASES.get(key)
        if current is not None:
            raise RuntimeError(f'{resource} is already connected by "{current[1]}"; please disconnect it in that module first, then connect from "{owner_label}"')
        with _process_instrument_lease_lock():
            held = _process_instrument_leases()
            entry = held.get(key)
            if entry is None:
                try:
                    entry = held[key] = [hold_instrument_for_this_process(key, str(owner_label)), 0]
                except RuntimeError as other:
                    raise RuntimeError(f'{resource} is in use by another Transport program on this PC ({other}); disconnect it there or close that program first (if no such window is open, end that process in Task Manager), then connect from "{owner_label}"') from None
            entry[1] += 1
        _INSTRUMENT_LEASES[key] = (owner, str(owner_label))
    return key
def release_instrument_lease(resource: str, owner: object) -> None:
    key = instrument_lease_key(resource)
    if not key:
        return
    with _INSTRUMENT_LEASE_LOCK:
        current = _INSTRUMENT_LEASES.get(key)
        if current is not None and current[0] is owner:
            _INSTRUMENT_LEASES.pop(key, None)
            with _process_instrument_lease_lock():
                held = _process_instrument_leases()
                entry = held.get(key)
                if entry is not None:
                    entry[1] -= 1
                    if entry[1] <= 0:
                        held.pop(key, None)
                        let_go_of_instrument_for_this_process(entry[0])
class SafeVisaIdentityController:
    def __init__(
        self,
        logger: Callable[[str], None],
        label: str,
        identity_token: str,
        safe_off_commands: tuple[str, ...] = (),
        owner_scope: str = "PPMS",
        preserve_visa_io_defaults: bool = False,
        safe_off_on_connect: bool = True,
        enumerate_before_open: bool = False,
        connect_settle_seconds: float = 0.0,
    ) -> None:
        self.logger = logger
        self.label = str(label)
        self.identity_token = str(identity_token).upper()
        self.safe_off_commands = tuple(safe_off_commands)
        self.owner_scope = str(owner_scope)
        self.preserve_visa_io_defaults = bool(preserve_visa_io_defaults)
        self.safe_off_on_connect = bool(safe_off_on_connect)
        self.enumerate_before_open = bool(enumerate_before_open)
        self.connect_settle_seconds = max(0.0, float(connect_settle_seconds))
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def connect(self, resource_name: str) -> str:
        if pyvisa is None:
            raise RuntimeError('pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py')
        resource_name = str(resource_name).strip()
        with self.lock:
            if self.instrument is not None:
                return self.identity
            acquire_instrument_lease(resource_name, self, f'{self.owner_scope} / {self.label}')
            manager = None
            instrument = None
            identity_verified = False
            try:
                manager = acquire_shared_visa_manager()
                if self.enumerate_before_open:
                    manager.list_resources()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 3000 if self.preserve_visa_io_defaults else 5000
                if not self.preserve_visa_io_defaults:
                    instrument.write_termination = "\n"
                    instrument.read_termination = "\n"
                    try:
                        instrument.query_delay = 0.05
                    except (AttributeError, ValueError):
                        pass
                else:
                    instrument.write_termination = "\r\n"
                    instrument.read_termination = None
                    instrument.send_end = True
                if self.connect_settle_seconds > 0:
                    time.sleep(self.connect_settle_seconds)
                try:
                    identity = instrument.query("*IDN?").strip()
                except BaseException as error:
                    raise RuntimeError(f'{self.label} identity query *IDN? failed: {error}; no output/setting command was sent to the device this time; the VISA session has been closed') from error
                if self.identity_token not in identity.upper():
                    raise RuntimeError(f'The device returned by {resource_name} is not {self.label}: {identity}')
                identity_verified = True
                if self.safe_off_on_connect:
                    for command in self.safe_off_commands:
                        try:
                            instrument.write(command)
                        except BaseException as error:
                            raise RuntimeError(f'{self.label} connection safety command {command!r} failed: {error}') from error
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = identity
                self.logger(f'{self.owner_scope} {self.label} connected: {identity}')
                return identity
            except BaseException:
                if instrument is not None:
                    if identity_verified and self.safe_off_on_connect:
                        for command in self.safe_off_commands:
                            try:
                                instrument.write(command)
                            except BaseException:
                                pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                release_instrument_lease(resource_name, self)
                raise
class AvtechPulseError(RuntimeError):
    def __init__(self, message: str, *, fired: bool=False, amplitude_v: float=math.nan, width_s: float=math.nan, overload: bool | None=False) -> None:
        super().__init__(message)
        self.fired = fired
        self.amplitude_v = amplitude_v
        self.width_s = width_s
        self.overload = overload
class AvtechPulserController(SafeVisaIdentityController):
    OVERLOAD_ERROR = 1001
    def __init__(self, logger: Callable[[str], None]) -> None:
        super().__init__(logger, 'Avtech pulse generator', 'AVTECH', safe_off_commands=('trigger:source hold', 'output off'), owner_scope='CIDWM')
    def connect(self, resource_name: str) -> str:
        identity = super().connect(resource_name)
        with self.lock:
            try:
                self.instrument.write("*CLS")
                problem = self._off_problem()
            except BaseException as error:
                problem = f"*CLS after connecting failed: {error}"
            if problem is not None:
                try:
                    self.disconnect()
                except BaseException as error:
                    problem += f"; {error}"
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
        return identity
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            problem = self._off_problem() if instrument is not None else None
            if instrument is not None:
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            release_instrument_lease(resource_name, self)
            self.logger(f"{self.owner_scope} {self.label} disconnected")
            if problem is not None:
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
    @property
    def polarities(self) -> tuple[int, ...] | None:
        fields = self.identity.split(",")
        model = fields[1].strip().upper() if len(fields) > 1 else ""
        match = re.search(r"-(PN|P|N)(?=-|$)", model)
        if match is None:
            return None
        return {"PN": (1, -1), "P": (1,), "N": (-1,)}[match.group(1)]
    @staticmethod
    def validate(amplitude_v, width_s) -> tuple[float, float]:
        amplitude_v, width_s = float(amplitude_v), float(width_s)
        if not (math.isfinite(amplitude_v) and 0 < abs(amplitude_v) <= AVTECH_MAX_AMPLITUDE_V):
            raise ValueError(f'The Avtech amplitude must be above 0 and at most {AVTECH_MAX_AMPLITUDE_V:g} V')
        AvtechPulserController.validate_width(width_s)
        return amplitude_v, width_s
    @staticmethod
    def validate_width(width_s) -> float:
        width_s = float(width_s)
        if not (math.isfinite(width_s) and AVTECH_MIN_WIDTH_S * 0.999 <= width_s <= AVTECH_MAX_WIDTH_S * 1.001):
            raise ValueError("The Avtech pulse width must be within 1 ns - 5 us")
        return width_s
    def _number(self, query: str) -> float:
        reply = str(self.instrument.query(query)).strip()
        try:
            value = float(reply)
        except ValueError as error:
            raise RuntimeError(f"{self.label}: {query} returned {reply!r}") from error
        if not math.isfinite(value):
            raise RuntimeError(f"{self.label}: {query} returned {reply!r}")
        return value
    def _errors(self, found: list | None = None) -> list[tuple[int, str]]:
        found = [] if found is None else found
        for _ in range(32):
            reply = str(self.instrument.query("syst:err?")).strip()
            try:
                code = int(float(reply.split(",", 1)[0]))
            except ValueError:
                found.append((-1, reply))
                continue
            if code == 0:
                break
            found.append((code, reply))
        return found
    def _off_problem(self) -> str | None:
        failures = []
        def clear() -> None:
            try:
                self.instrument.clear()
            except BaseException as error:
                failures.append(f"device clear: {error}")
        def send(command: str) -> bool:
            try:
                self.instrument.write(command)
                return True
            except BaseException as error:
                failures.append(f"{command}: {error}")
                return False
        clear()
        for command in ("trigger:source hold", "output off"):
            if not send(command):
                clear()
                send(command)
        for attempt in range(2):
            try:
                if self._number("output?") == 0:
                    if failures:
                        self.logger(f"{self.label}: output read back off, after: " + "; ".join(failures))
                    return None
                failures.append("its output did not read back off")
            except BaseException as error:
                failures.append(f"output? failed: {error}")
            if attempt == 0:
                clear()
                send("output off")
        return "; ".join(failures)
    def switch_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"{self.label} is not connected; its output state is unknown")
            problem = self._off_problem()
            if problem is not None:
                raise RuntimeError(f"{self.label}: {problem}; check the generator")
    def single_pulse(self, amplitude_v: float, width_s: float) -> dict:
        amplitude_v, width_s = self.validate(amplitude_v, width_s)
        sign = 1 if amplitude_v > 0 else -1
        with self.lock:
            if self.instrument is None:
                raise AvtechPulseError(f"{self.label} is not connected; no pulse fired")
            allowed = self.polarities
            if allowed is not None and sign not in allowed:
                raise AvtechPulseError(f"This {self.label} gives {('positive' if allowed == (1,) else 'negative')} pulses only (its polarity option); no pulse fired")
            failure = None
            fired = trigger_sent = False
            amplitude_read = width_read = math.nan
            after: list[tuple[int, str]] = []
            others: list[str] = []
            try:
                self.instrument.clear()
                self.instrument.write("*CLS")
                self.instrument.write("trigger:source hold")
                self.instrument.write("output off")
                errors = self._errors()
                if errors:
                    raise RuntimeError(f'{self.label} refused hold or output off: ' + '; '.join((text for _code, text in errors)))
                if self._number("output?") != 0:
                    raise RuntimeError(f"{self.label}'s output did not read back off before the pulse")
                self.instrument.write("pulse:delay 0")
                if not abs(self._number("pulse:delay?")) <= 1e-9:
                    raise RuntimeError(f"{self.label} did not take a delay of 0")
                self.instrument.write(f"pulse:width {width_s:.6g}")
                width_read = self._number("pulse:width?")
                if not abs(width_read - width_s) <= max(0.05 * width_s, 0.2e-9):
                    raise RuntimeError(f"{self.label} took a width of {width_read:.4g} s for {width_s:.4g} s")
                self.instrument.write(f"volt:ampl {amplitude_v:.6g}")
                amplitude_read = self._number("volt:ampl?")
                tolerance = max(0.02 * abs(amplitude_v), 0.5)
                if not (amplitude_read * sign > 0 and abs(amplitude_read - amplitude_v) <= tolerance):
                    raise RuntimeError(f'{self.label} took {amplitude_read:+g} V for {amplitude_v:+g} V (its polarity option?)')
                errors = self._errors()
                if errors:
                    raise RuntimeError(f"{self.label} reported " + "; ".join(text for _code, text in errors))
                self.instrument.write("output on")
                if self._number("output?") != 1:
                    raise RuntimeError(f"{self.label}'s output did not switch on")
                fired = True
                self.instrument.write("trigger:source immediate")
                trigger_sent = True
                self.instrument.write("trigger:source hold")
                self._errors(after)
            except BaseException as error:
                failure = error
            problem = self._off_problem()
            try:
                self._errors(after)
            except BaseException as error:
                others.append(f"its error queue could not be read: {error}")
            overload: bool | None = any(code == self.OVERLOAD_ERROR for code, _text in after)
            others += [text for code, text in after if code != self.OVERLOAD_ERROR]
            try:
                overload = overload or self._number("output:protection:tripped?") != 0
            except BaseException as error:
                others.append(f"its overload state could not be read: {error}")
                overload = True if overload else None
            parts = []
            if failure is not None:
                parts.append(str(failure))
            parts += [f"it reported {text}" for text in others]
            if problem is not None:
                parts.append(f"{problem}; check the generator")
            if parts:
                if overload:
                    parts.append("OVERLOAD: output protection tripped (short or too-low load impedance)")
                if trigger_sent:
                    prefix = "pulse fired, then: "
                elif fired:
                    prefix = "the trigger may have been sent (a pulse may have fired), then: "
                else:
                    prefix = "no pulse fired: "
                raise AvtechPulseError(prefix + '; '.join(parts), fired=fired, amplitude_v=amplitude_read, width_s=width_read, overload=overload) from failure
            return {'amplitude_v': amplitude_read, 'width_s': width_read, 'overload': overload, 'pulse_end': time.monotonic()}
    @staticmethod
    def validate_count(count) -> int:
        if isinstance(count, str):
            text = count.strip()
            if not re.fullmatch(r"[0-9]+", text):
                raise ValueError(f'The Avtech pulse count must be a whole number from 1 to {AVTECH_MAX_PULSE_COUNT}')
            count = int(text)
        if isinstance(count, bool) or not isinstance(count, int) or not 1 <= count <= AVTECH_MAX_PULSE_COUNT:
            raise ValueError(f'The Avtech pulse count must be a whole number from 1 to {AVTECH_MAX_PULSE_COUNT}')
        return count
    def pulse_train(self, amplitude_v: float, width_s: float, count, *, gap_s: float = AVTECH_PULSE_GAP_S,
                    stop_event: threading.Event | None = None,
                    progress: Callable[[int, int], None] | None = None) -> dict:
        amplitude_v, width_s = self.validate(amplitude_v, width_s)
        count = self.validate_count(count)
        gap_s = float(gap_s)
        if not (math.isfinite(gap_s) and 0.0 <= gap_s <= 3600.0):
            raise ValueError("The Avtech pulse gap must be within 0 - 3600 s")
        done = 0
        result: dict = {'amplitude_v': math.nan, 'width_s': math.nan, 'overload': False, 'pulse_end': time.monotonic()}
        stopped = False
        for index in range(1, count + 1):
            if stop_event is not None and stop_event.is_set():
                stopped = True
                break
            if progress is not None:
                progress(index, count)
            try:
                result = self.single_pulse(amplitude_v, width_s)
            except AvtechPulseError as error:
                error.pulse_index, error.pulses_done = index, done
                raise
            done += 1
            if result["overload"]:
                break
            if index < count:
                if stop_event is not None:
                    if stop_event.wait(gap_s):
                        stopped = True
                        break
                else:
                    time.sleep(gap_s)
        if stopped:
            try:
                self.switch_off()
            except BaseException as error:
                stop_error = AvtechPulseError(f'stopped after {done}/{count} pulses, then: {error}', amplitude_v=result['amplitude_v'], width_s=result['width_s'], overload=result['overload'])
                stop_error.pulse_index, stop_error.pulses_done = done, done
                stop_error.output_unknown = True
                raise stop_error from error
        return dict(result, pulses=done, count=count, stopped=stopped)
SR830_DISPLAY_XY_COMMANDS = ("DDEF 1,0,0", "DDEF 2,0,0")
def show_sr830_x_and_y(instrument, logger=None, label: str = "SR830") -> bool:
    try:
        for command in SR830_DISPLAY_XY_COMMANDS:
            instrument.write(command)
        return True
    except Exception as error:
        if logger is not None:
            logger(f"{label}: the display was not set to X and Y: {error}")
        return False
def _clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))
def calculate_window_layout(root: tk.Tk):
    screen_width = max(640, int(root.winfo_screenwidth()))
    screen_height = max(480, int(root.winfo_screenheight()))
    if sys.platform.startswith("win"):
        taskbar_reserve = 48
    elif sys.platform == "darwin":
        taskbar_reserve = 30
    else:
        taskbar_reserve = 42
    usable_height = max(400, screen_height - taskbar_reserve)
    edge = max(4, int(round(min(screen_width, screen_height) * 0.008)))
    gap = max(6, int(round(WINDOW_GAP)))
    wide_split = screen_width >= 1700
    if wide_split:
        control_width = int(round(screen_width * CONTROL_WIDTH_FRACTION))
        control_width = max(720, min(control_width, screen_width - 620 - gap))
        control_x = max(edge, screen_width - control_width - edge)
        camera_x = edge
        camera_width = max(600, control_x - gap - camera_x)
    else:
        control_x = edge
        camera_x = edge
        control_width = max(480, screen_width - 2 * edge)
        camera_width = control_width
    window_height = max(380, usable_height - edge)
    ui_scale = _clamp(min(control_width / 960.0, window_height / 1000.0), 0.72, 1.18)
    canvas_scale = _clamp(window_height / 1000.0, 0.62, 1.22)
    return {
        "camera": (camera_width, window_height, camera_x, edge),
        "control": (control_width, window_height, control_x, edge),
        "screen": (screen_width, screen_height),
        "usable_height": usable_height,
        "ui_scale": ui_scale,
        "canvas_scale": canvas_scale,
        "compact": not wide_split or window_height < 850,
    }
def geometry_string(geometry) -> str:
    width, height, x, y = geometry
    return f"{width}x{height}+{x}+{y}"
def _frame_mean(image) -> float:
    if cv2 is not None and getattr(image, "ndim", 0) == 2:
        try:
            return float(cv2.mean(image)[0])
        except cv2.error:
            pass
    return float(np.mean(image))
def _block_mean_downsample(image, factor: int):
    if factor <= 1:
        return image.astype(np.float32, copy=False)
    height, width = image.shape[:2]
    trimmed_height = height - height % factor
    trimmed_width = width - width % factor
    if trimmed_height < factor or trimmed_width < factor:
        return image.astype(np.float32, copy=False)
    trimmed = image[:trimmed_height, :trimmed_width].astype(np.float32, copy=False)
    return trimmed.reshape(trimmed_height // factor, factor, trimmed_width // factor, factor).mean(axis=(1, 3))
def _parabolic_peak_offset(left: float, center: float, right: float) -> float:
    denominator = left - 2.0 * center + right
    if abs(denominator) < 1e-12:
        return 0.0
    return float(np.clip(0.5 * (left - right) / denominator, -0.5, 0.5))
def _peak_offset(left: float, center: float, right: float) -> float:
    if left > 0.0 and center > 0.0 and right > 0.0:
        log_left, log_center, log_right = math.log(left), math.log(center), math.log(right)
        denominator = log_left - 2.0 * log_center + log_right
        if denominator < -1e-12:
            return float(np.clip(0.5 * (log_left - log_right) / denominator, -0.5, 0.5))
    return _parabolic_peak_offset(left, center, right)
def _drift_downsample(image_f32):
    if DRIFT_DOWNSAMPLE <= 1:
        return image_f32
    if cv2 is not None:
        scale = 1.0 / DRIFT_DOWNSAMPLE
        return cv2.resize(image_f32, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA)
    return _block_mean_downsample(image_f32, DRIFT_DOWNSAMPLE)
def _drift_spectrum(image_f32, window):
    windowed = (image_f32 - float(np.mean(image_f32))) * window
    if cv2 is not None:
        spectrum = cv2.dft(np.ascontiguousarray(windowed, dtype=np.float32), flags=cv2.DFT_COMPLEX_OUTPUT)
        return spectrum.view(np.complex64)[..., 0]
    return np.fft.fft2(windowed)
def _drift_correlation(spectrum, reference_spectrum, transfer):
    cross = spectrum * np.conj(reference_spectrum)
    cross /= np.maximum(np.abs(cross), 1e-30)
    cross *= transfer
    if cv2 is not None:
        cross = np.ascontiguousarray(cross, dtype=np.complex64)
        return cv2.idft(cross.view(np.float32).reshape(cross.shape + (2,)), flags=cv2.DFT_SCALE | cv2.DFT_REAL_OUTPUT)
    return np.fft.ifft2(cross).real
class _DriftScale:
    __slots__ = ("origin", "size", "window", "transfer", "spectrum", "identical")
    def __init__(self, image_f32, origin, size, noise_sigma, illumination_sigma) -> None:
        x0, y0 = origin
        width, height = size
        self.origin = origin
        self.size = size
        self.window = np.outer(np.hanning(height), np.hanning(width)).astype(np.float32)
        fy = np.fft.fftfreq(height).astype(np.float32)[:, None]
        fx = np.fft.fftfreq(width).astype(np.float32)[None, :]
        radius2 = fx * fx + fy * fy
        band = np.exp(-2.0 * math.pi ** 2 * noise_sigma ** 2 * radius2) - np.exp(-2.0 * math.pi ** 2 * illumination_sigma ** 2 * radius2)
        self.transfer = (band * band).astype(np.float32)
        self.spectrum = _drift_spectrum(image_f32[y0:y0 + height, x0:x0 + width], self.window)
        self.identical = float(np.mean(self.transfer))
    def match(self, image_f32, offset_x: int, offset_y: int, radius: int):
        x0, y0 = self.origin[0] + offset_x, self.origin[1] + offset_y
        width, height = self.size
        spectrum = _drift_spectrum(image_f32[y0:y0 + height, x0:x0 + width], self.window)
        correlation = _drift_correlation(spectrum, self.spectrum, self.transfer)
        if radius is None:
            radius = max(height, width)
        radius_y = max(1, min(radius, (height - 1) // 2))
        radius_x = max(1, min(radius, (width - 1) // 2))
        offsets_y = np.arange(-radius_y, radius_y + 1)
        offsets_x = np.arange(-radius_x, radius_x + 1)
        near = correlation[np.ix_(offsets_y % height, offsets_x % width)]
        row, column = np.unravel_index(int(np.argmax(near)), near.shape)
        peak_y, peak_x = int(offsets_y[row]), int(offsets_x[column])
        peak = float(near[row, column])
        shift_x = peak_x + _peak_offset(float(correlation[peak_y % height, (peak_x - 1) % width]), peak, float(correlation[peak_y % height, (peak_x + 1) % width]))
        shift_y = peak_y + _peak_offset(float(correlation[(peak_y - 1) % height, peak_x % width]), peak, float(correlation[(peak_y + 1) % height, peak_x % width]))
        quality = peak / self.identical if self.identical > 0.0 else 0.0
        return shift_x, shift_y, float(np.clip(quality, 0.0, 1.0))
class DriftBackground:
    __slots__ = ("raw", "float32", "coarse", "fine", "shape")
    def __init__(self, background_u16) -> None:
        self.raw = background_u16
        self.float32 = np.asarray(background_u16).astype(np.float32)
        self.shape = self.float32.shape
        small = _drift_downsample(self.float32)
        self.coarse = None
        if min(small.shape) >= 8:
            self.coarse = _DriftScale(small, (0, 0), (small.shape[1], small.shape[0]), DRIFT_COARSE_NOISE_SIGMA_PX, DRIFT_ILLUMINATION_SIGMA_PX / DRIFT_DOWNSAMPLE)
        height, width = self.shape
        margin = int(math.ceil(MAX_DRIFT_PIXELS)) + 2
        size = min(DRIFT_FINE_SIZE, width - 2 * margin, height - 2 * margin)
        size -= size % 2
        self.fine = None
        if size >= 64:
            self.fine = _DriftScale(self.float32, ((width - size) // 2, (height - size) // 2), (size, size), DRIFT_NOISE_SIGMA_PX, DRIFT_ILLUMINATION_SIGMA_PX)
def _as_drift_background(background) -> DriftBackground:
    if isinstance(background, DriftBackground):
        return background
    return DriftBackground(background)
def estimate_drift_shift(background_u16, image_u16):
    prepared = _as_drift_background(background_u16)
    image = np.asarray(image_u16).astype(np.float32, copy=False)
    if prepared.coarse is None or image.shape != prepared.shape:
        return 0.0, 0.0, 0.0
    small = _drift_downsample(image)
    coarse_width, coarse_height = prepared.coarse.size
    if small.shape[0] < coarse_height or small.shape[1] < coarse_width:
        return 0.0, 0.0, 0.0
    coarse_x, coarse_y, match = prepared.coarse.match(small, 0, 0, None)
    dx, dy = coarse_x * DRIFT_DOWNSAMPLE, coarse_y * DRIFT_DOWNSAMPLE
    if not np.isfinite(dx) or not np.isfinite(dy) or abs(dx) > MAX_DRIFT_PIXELS or (abs(dy) > MAX_DRIFT_PIXELS) or (match < DRIFT_MIN_MATCH):
        return 0.0, 0.0, match
    if prepared.fine is not None:
        step_x, step_y = int(round(dx)), int(round(dy))
        fine_x, fine_y, fine_match = prepared.fine.match(image, step_x, step_y, 3)
        if abs(fine_x) <= 2.5 and abs(fine_y) <= 2.5:
            dx, dy, match = step_x + fine_x, step_y + fine_y, fine_match
    if abs(dx) > MAX_DRIFT_PIXELS or abs(dy) > MAX_DRIFT_PIXELS:
        return 0.0, 0.0, match
    return float(dx), float(dy), float(match)
def _reflect_coordinates(coordinates, length: int):
    if length <= 1:
        return np.zeros_like(coordinates, dtype=np.float32)
    period = 2.0 * (length - 1)
    wrapped = np.mod(coordinates, period)
    return np.where(wrapped <= length - 1, wrapped, period - wrapped)
def drift_correct_image(image_u16, dx: float, dy: float):
    if cv2 is not None:
        image = np.asarray(image_u16).astype(np.float32, copy=False)
        matrix = np.array([[1.0, 0.0, -dx], [0.0, 1.0, -dy]], dtype=np.float32)
        return cv2.warpAffine(image, matrix, (image_u16.shape[1], image_u16.shape[0]), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT)
    image = image_u16.astype(np.float32, copy=False)
    height, width = image.shape[:2]
    source_x = _reflect_coordinates(np.arange(width, dtype=np.float32) + dx, width)
    x0 = np.floor(source_x).astype(np.intp)
    x1 = np.minimum(x0 + 1, width - 1)
    weight_x = source_x - x0
    shifted_x = image[:, x0] * (1.0 - weight_x)[None, :] + image[:, x1] * weight_x[None, :]
    source_y = _reflect_coordinates(np.arange(height, dtype=np.float32) + dy, height)
    y0 = np.floor(source_y).astype(np.intp)
    y1 = np.minimum(y0 + 1, height - 1)
    weight_y = source_y - y0
    return shifted_x[y0, :] * (1.0 - weight_y)[:, None] + shifted_x[y1, :] * weight_y[:, None]
def subtract_background_after_drift(image_u16, background_u16):
    prepared = _as_drift_background(background_u16)
    image_f32 = np.asarray(image_u16).astype(np.float32, copy=False)
    dx, dy, response = estimate_drift_shift(prepared, image_f32)
    aligned = drift_correct_image(image_f32, dx, dy)
    if aligned.dtype == np.float32 and aligned.flags.writeable and aligned is not image_f32:
        np.subtract(aligned, prepared.float32, out=aligned)
        difference = aligned
    else:
        difference = aligned - prepared.float32
    return difference, dx, dy, response
def auto_contrast_limits(image, bounds=None) -> tuple[float, float]:
    sample = image
    if bounds is not None:
        x1, y1, x2, y2 = bounds
        visible = image[y1:y2, x1:x2]
        if visible.size:
            sample = visible
    sample = np.asarray(sample)
    if sample.ndim == 2 and sample.size > DIFFERENCE_CONTRAST_MAX_SAMPLES:
        stride = int(math.ceil(math.sqrt(sample.size / DIFFERENCE_CONTRAST_MAX_SAMPLES)))
        sample = sample[::stride, ::stride]
    low, high = np.percentile(sample, (CONTRAST_LOW_PERCENTILE, CONTRAST_HIGH_PERCENTILE))
    return float(low), float(high)
def difference_contrast_parameters(difference, bounds=None) -> tuple[float, float]:
    sample = difference
    if bounds is not None:
        x1, y1, x2, y2 = bounds
        visible = difference[y1:y2, x1:x2]
        if visible.size:
            sample = visible
    finite = np.asarray(sample, dtype=np.float32).reshape(-1)
    if finite.size > DIFFERENCE_CONTRAST_MAX_SAMPLES:
        stride = int(math.ceil(finite.size / DIFFERENCE_CONTRAST_MAX_SAMPLES))
        finite = finite[::stride]
    finite = finite[np.isfinite(finite)]
    if finite.size == 0:
        return 0.0, DIFFERENCE_MIN_HALF_RANGE
    center = float(np.median(finite))
    deviation = np.abs(finite - center)
    mad = float(np.median(deviation))
    robust_sigma = 1.4826 * mad
    core = float(np.percentile(deviation, DIFFERENCE_CORE_PERCENTILE))
    half_range = max(core, DIFFERENCE_MAD_MULTIPLIER * robust_sigma, DIFFERENCE_MIN_HALF_RANGE)
    return center, half_range
def difference_preview(difference, bounds=None, max_abs: float | None=None, center: float=0.0):
    if max_abs is None:
        center, max_abs = difference_contrast_parameters(difference, bounds)
    max_abs = max(float(max_abs), DIFFERENCE_MIN_HALF_RANGE)
    preview = np.asarray(difference).astype(np.float32)
    preview -= float(center)
    preview *= 127.5 / max_abs
    preview += 127.5
    np.clip(preview, 0.0, 255.0, out=preview)
    return preview.astype(np.uint8)
def difference_histogram_data(difference, bounds=None, clim: tuple[float, float] | None=None, bins: int=96):
    sample = difference
    if bounds is not None:
        x1, y1, x2, y2 = bounds
        visible = difference[y1:y2, x1:x2]
        if visible.size:
            sample = visible
    values = np.asarray(sample, dtype=np.float32).reshape(-1)
    if values.size > DIFFERENCE_CONTRAST_MAX_SAMPLES:
        stride = int(math.ceil(values.size / DIFFERENCE_CONTRAST_MAX_SAMPLES))
        values = values[::stride]
    values = values[np.isfinite(values)]
    if values.size == 0:
        return None
    p1, p99 = np.percentile(values, (1.0, 99.0))
    if clim is None:
        low, high = float(p1), float(p99)
    else:
        low, high = float(clim[0]), float(clim[1])
    if not math.isfinite(low) or not math.isfinite(high) or high <= low:
        low, high = float(p1), float(p99)
    if high <= low:
        padding = max(abs(low) * 0.01, DIFFERENCE_MIN_HALF_RANGE)
        low -= padding
        high += padding
    counts, edges = np.histogram(values, bins=max(int(bins), 16), range=(low, high))
    return {
        "counts": counts.astype(np.float64),
        "edges": edges.astype(np.float64),
        "clim": (low, high),
        "mean": float(np.mean(values)),
        "median": float(np.median(values)),
        "std": float(np.std(values)),
        "p1": float(p1),
        "p99": float(p99),
        "under_fraction": float(np.mean(values < low)),
        "over_fraction": float(np.mean(values > high)),
        "sample_count": int(values.size),
    }
def spatial_bin_average_full_size(image, factor: int):
    source = np.asarray(image, dtype=np.float32)
    factor = int(factor)
    if factor == 1:
        return source
    if factor not in {2, 4, 8}:
        raise ValueError("Display binning can only be 1×1, 2×2, 4×4 or 8×8")
    height, width = source.shape[:2]
    binned_height = height - height % factor
    binned_width = width - width % factor
    if binned_height < factor or binned_width < factor:
        return source
    trimmed = source[:binned_height, :binned_width]
    if cv2 is not None:
        reduced = cv2.resize(np.ascontiguousarray(trimmed), (binned_width // factor, binned_height // factor), interpolation=cv2.INTER_AREA)
        expanded = cv2.resize(reduced, (binned_width, binned_height), interpolation=cv2.INTER_NEAREST)
    else:
        reduced = trimmed.reshape(binned_height // factor, factor, binned_width // factor, factor).mean(axis=(1, 3))
        expanded = np.repeat(np.repeat(reduced, factor, axis=0), factor, axis=1)
    if binned_height == height and binned_width == width:
        return expanded
    return np.pad(expanded, ((0, height - binned_height), (0, width - binned_width)), mode='edge')
def mean_filter_full_size(image, kernel_size: int):
    source = np.asarray(image, dtype=np.float32)
    kernel_size = int(kernel_size)
    if kernel_size == 1:
        return source
    if kernel_size not in {2, 4}:
        raise ValueError("Mean filter can only be 1×1, 2×2 or 4×4")
    if cv2 is not None:
        return cv2.blur(source, (kernel_size, kernel_size), borderType=cv2.BORDER_REFLECT)
    before = kernel_size // 2
    after = kernel_size - 1 - before
    padded = np.pad(source, ((before, after), (before, after)), mode='reflect')
    integral = np.pad(padded, ((1, 0), (1, 0)), mode='constant').cumsum(axis=0).cumsum(axis=1)
    total = integral[kernel_size:, kernel_size:] - integral[:-kernel_size, kernel_size:] - integral[kernel_size:, :-kernel_size] + integral[:-kernel_size, :-kernel_size]
    return (total / float(kernel_size * kernel_size)).astype(np.float32, copy=False)
def nice_symmetric_ticks(values, target_half_intervals: int = 4):
    finite_values = [abs(float(value)) for value in values if math.isfinite(float(value))]
    data_max_abs = max(finite_values, default=0.0)
    if data_max_abs <= 0.0:
        return -1.0, 1.0, [-1.0, -0.5, 0.0, 0.5, 1.0], 0.5
    raw_step = data_max_abs / max(int(target_half_intervals), 1)
    exponent = math.floor(math.log10(raw_step))
    scale = 10.0 ** exponent
    fraction = raw_step / scale
    if fraction <= 1.0:
        nice_fraction = 1.0
    elif fraction <= 2.0:
        nice_fraction = 2.0
    elif fraction <= 5.0:
        nice_fraction = 5.0
    else:
        nice_fraction = 10.0
    step = nice_fraction * scale
    intervals = max(1, int(math.ceil(data_max_abs / step - 1e-12)))
    limit = intervals * step
    ticks = [index * step for index in range(-intervals, intervals + 1)]
    return -limit, limit, ticks, step
def nice_linear_ticks(data_min: float, data_max: float, target_intervals: int=4, *, include_zero: bool=False, expand_limits: bool=True):
    low = float(data_min)
    high = float(data_max)
    if not math.isfinite(low) or not math.isfinite(high):
        low, high = 0.0, 1.0
    if low > high:
        low, high = high, low
    if include_zero:
        low = min(low, 0.0)
        high = max(high, 0.0)
    if math.isclose(low, high, rel_tol=0.0, abs_tol=1e-15):
        magnitude = abs(low) if abs(low) > 0.0 else 1.0
        half_span = max(magnitude * 0.05, 1e-12)
        low -= half_span
        high += half_span
    raw_step = (high - low) / max(int(target_intervals), 1)
    exponent = math.floor(math.log10(raw_step))
    scale = 10.0 ** exponent
    fraction = raw_step / scale
    if fraction <= 1.5:
        nice_fraction = 1.0
    elif fraction <= 2.25:
        nice_fraction = 2.0
    elif fraction <= 3.75:
        nice_fraction = 2.5
    elif fraction <= 7.5:
        nice_fraction = 5.0
    else:
        nice_fraction = 10.0
    step = nice_fraction * scale
    epsilon = abs(step) * 1e-10
    if expand_limits:
        axis_min = math.floor((low + epsilon) / step) * step
        axis_max = math.ceil((high - epsilon) / step) * step
        if axis_max <= axis_min:
            axis_max = axis_min + step
    else:
        axis_min, axis_max = low, high
    first_index = int(math.ceil((axis_min - epsilon) / step))
    last_index = int(math.floor((axis_max + epsilon) / step))
    ticks = [index * step for index in range(first_index, last_index + 1)]
    if len(ticks) < 2:
        ticks = [axis_min, axis_max]
    ticks = [0.0 if abs(value) < epsilon else value for value in ticks]
    return axis_min, axis_max, ticks, step
def format_nice_tick(value: float, step: float) -> str:
    if abs(value) < abs(step) * 1e-9:
        return "0"
    if abs(step) < 1e-6 or abs(value) >= 1e7:
        return f"{value:.4g}"
    if abs(step) >= 1.0:
        if math.isclose(step, round(step), rel_tol=0.0, abs_tol=1e-12):
            return f"{value:.0f}"
        return f"{value:.1f}"
    decimals = min(8, max(0, int(math.ceil(-math.log10(abs(step))))))
    while decimals < 8 and (not math.isclose(abs(step) * 10.0 ** decimals, round(abs(step) * 10.0 ** decimals), rel_tol=0.0, abs_tol=1e-09)):
        decimals += 1
    return f"{value:.{decimals}f}"
def rotated_roi_points(roi):
    angle_radians = np.deg2rad(float(roi["angle"]))
    cosine = float(np.cos(angle_radians))
    sine = float(np.sin(angle_radians))
    half_width = float(roi["w"]) / 2.0
    half_height = float(roi["h"]) / 2.0
    points = []
    for local_x, local_y in ((-half_width, -half_height), (half_width, -half_height), (half_width, half_height), (-half_width, half_height)):
        points.append((float(roi['cx']) + local_x * cosine - local_y * sine, float(roi['cy']) + local_x * sine + local_y * cosine))
    return points
_ROTATED_ROI_MASK_CACHE: dict = {}
_ROTATED_ROI_MASK_CACHE_LIMIT = 8
def _rotated_roi_mask(roi, height: int, width: int):
    key = (float(roi['cx']), float(roi['cy']), float(roi['w']), float(roi['h']), float(roi['angle']), int(height), int(width))
    cached = _ROTATED_ROI_MASK_CACHE.get(key)
    if cached is not None:
        return cached
    points = np.asarray(rotated_roi_points(roi), dtype=np.float64)
    min_x = max(0, int(np.floor(np.min(points[:, 0]))))
    max_x = min(width, int(np.ceil(np.max(points[:, 0]))) + 1)
    min_y = max(0, int(np.floor(np.min(points[:, 1]))))
    max_y = min(height, int(np.ceil(np.max(points[:, 1]))) + 1)
    if max_x <= min_x or max_y <= min_y:
        result = (min_y, max_y, min_x, max_x, None)
    else:
        yy, xx = np.mgrid[min_y:max_y, min_x:max_x]
        relative_x = xx - float(roi["cx"])
        relative_y = yy - float(roi["cy"])
        angle_radians = np.deg2rad(float(roi["angle"]))
        cosine = float(np.cos(angle_radians))
        sine = float(np.sin(angle_radians))
        local_x = relative_x * cosine + relative_y * sine
        local_y = -relative_x * sine + relative_y * cosine
        mask = (np.abs(local_x) <= float(roi['w']) / 2.0) & (np.abs(local_y) <= float(roi['h']) / 2.0)
        result = (min_y, max_y, min_x, max_x, mask)
    if len(_ROTATED_ROI_MASK_CACHE) >= _ROTATED_ROI_MASK_CACHE_LIMIT:
        _ROTATED_ROI_MASK_CACHE.clear()
    _ROTATED_ROI_MASK_CACHE[key] = result
    return result
def values_inside_rotated_roi(image, roi):
    height, width = image.shape[:2]
    min_y, max_y, min_x, max_x, mask = _rotated_roi_mask(roi, height, width)
    if mask is None:
        return np.asarray([], dtype=image.dtype)
    return image[min_y:max_y, min_x:max_x][mask]
def build_voltage_sequence(start_v: float, end_v: float, step_v: float, max_abs_v: float=KEITHLEY_MAX_ABS_VOLTAGE_V):
    start_v = float(start_v)
    end_v = float(end_v)
    step_v = abs(float(step_v))
    if not all(math.isfinite(value) for value in (start_v, end_v, step_v)):
        raise ValueError("Start voltage, end voltage and step must be finite values")
    if step_v <= 0:
        raise ValueError("Voltage step must be greater than 0")
    if abs(start_v) > max_abs_v or abs(end_v) > max_abs_v:
        raise ValueError(f"Start/end voltage must be within ±{max_abs_v:g} V")
    return build_round_trip_values(start_v, end_v, step_v, decimals=10, too_many_message='Total voltage scan points exceed 100000; please increase the step')
def build_current_scan_sequence(start_a: float, end_a: float, step_a: float, loops: int):
    start_a = float(start_a)
    end_a = float(end_a)
    step_a = abs(float(step_a))
    loops = int(loops)
    if not all(math.isfinite(value) for value in (start_a, end_a, step_a)):
        raise ValueError("Start current, end current and step must be finite values")
    if step_a <= 0:
        raise ValueError("Current step must be greater than 0")
    if not 1 <= loops <= 1000:
        raise ValueError("Scan loop count must be between 1 and 1000")
    if abs(start_a) > MAGNET_CURRENT_LIMIT_A or abs(end_a) > MAGNET_CURRENT_LIMIT_A:
        raise ValueError(f'Start/end current must be within ±{MAGNET_CURRENT_LIMIT_A:g} A')
    cycle = build_round_trip_values(
        start_a,
        end_a,
        step_a,
        decimals=10,
        max_total_points=max(1, 100_000 // loops),
        too_many_message="Total scan points exceed 100000; please increase the step or reduce the loop count",
    )
    if len(cycle) * loops > 100000:
        raise ValueError("Total scan points exceed 100000; please increase the step or reduce the loop count")
    sequence = []
    for loop_index in range(1, loops + 1):
        for point_index, target in enumerate(cycle, start=1):
            sequence.append((loop_index, point_index, len(cycle), float(target)))
    return sequence
def camera_average_block_s(frame) -> float:
    try:
        block_s = 2.0 * float(frame.temporal_average_count) * float(frame.exposure_ms) / 1000.0
    except (AttributeError, TypeError, ValueError):
        return 0.0
    return block_s if math.isfinite(block_s) else 0.0
class Keithley2410Controller:
    def __init__(self, logger: Callable[[str], None], model: str = KEITHLEY_DEFAULT_MODEL) -> None:
        self.logger = logger
        self.model = KEITHLEY_DEFAULT_MODEL
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.output_enabled = False
        self.last_set_voltage = 0.0
        self.compliance_a = KEITHLEY_DEFAULT_COMPLIANCE_A
        self.source_mode = None
        self.source_voltage_range_v = None
        self.source_ovp_readback_v = None
        self.lock = threading.RLock()
        self.set_model(model)
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def set_model(self, model: str) -> None:
        model = str(model).strip()
        if model not in KEITHLEY_MODELS:
            raise ValueError(f"Keithley model must be one of {', '.join(KEITHLEY_MODELS)}")
        if self.instrument is not None and model != self.model:
            raise RuntimeError("Disconnect before changing the Keithley model")
        self.model = model
    @property
    def high_range_v(self) -> float:
        return KEITHLEY_MODELS[self.model]["high_range_v"]
    @property
    def high_range_max_compliance_a(self) -> float:
        return KEITHLEY_MODELS[self.model]["high_range_max_compliance_a"]
    @property
    def max_abs_voltage_v(self) -> float:
        return KEITHLEY_MODELS[self.model]["max_abs_voltage_v"]
    @property
    def source_ovp_v(self) -> float:
        return KEITHLEY_MODELS[self.model]["source_ovp_v"]
    @staticmethod
    def identity_matches(identity: str, model: str) -> bool:
        fields = [field.strip() for field in str(identity).upper().split(",")]
        return len(fields) > 1 and re.fullmatch(rf"(MODEL\s*)?{re.escape(model)}(-C)?", fields[1]) is not None
    def _query_error(self, command: str) -> None:
        response = self.instrument.query("SYST:ERR?").strip()
        try:
            error_code = int(response.split(",", 1)[0].strip())
        except ValueError as exc:
            raise RuntimeError(f"{self.model} returned an unparsable error status: {response}") from exc
        if error_code != 0:
            raise RuntimeError(f"{self.model} SCPI error after '{command}': {response}")
    def _write_checked(self, command: str) -> None:
        self.instrument.write(command)
        self._query_error(command)
    def _required_voltage_range(self, max_abs_voltage: float) -> float:
        return KEITHLEY_LOW_SOURCE_RANGE_V if abs(float(max_abs_voltage)) <= KEITHLEY_LOW_SOURCE_RANGE_V else self.high_range_v
    def _select_voltage_range_locked(self, max_abs_voltage: float) -> float:
        requested = self._required_voltage_range(max_abs_voltage)
        self._write_checked(f":SOUR:VOLT:RANG {requested:.12g}")
        actual = float(self.instrument.query(":SOUR:VOLT:RANG?").strip())
        if not math.isfinite(actual) or actual + 1e-9 < abs(float(max_abs_voltage)):
            raise RuntimeError(f'{self.model} voltage source range is insufficient: needs {abs(float(max_abs_voltage)):g} V, readback {actual:g} V')
        self.source_voltage_range_v = actual
        return actual
    def _configure_voltage_source_locked(self, max_abs_voltage: float = 0.0) -> None:
        self.source_mode = None
        self.source_voltage_range_v = None
        self.source_ovp_readback_v = None
        self._write_checked(":SOUR:FUNC VOLT")
        self._write_checked(":SOUR:VOLT:MODE FIXED")
        self._write_checked(f":SOUR:VOLT:PROT {self.source_ovp_v:.12g}")
        actual_ovp = float(self.instrument.query(":SOUR:VOLT:PROT?").strip())
        if not math.isfinite(actual_ovp) or actual_ovp > self.source_ovp_v * 1.01:
            raise RuntimeError(f'{self.model} hardware over-voltage protection readback is too high: {actual_ovp:g} V')
        if actual_ovp < self.source_ovp_v * 0.99:
            raise RuntimeError(f'{self.model} hardware over-voltage protection readback is {actual_ovp:g} V, not the {self.source_ovp_v:g} V asked for')
        self.source_ovp_readback_v = actual_ovp
        self._select_voltage_range_locked(max_abs_voltage)
        self._write_checked(":SENS:FUNC 'CURR'")
        self._write_checked(f":SENS:CURR:PROT {self.compliance_a:.9g}")
        self._write_checked(":SOUR:VOLT 0")
        self.source_mode = "VOLT"
        self.last_set_voltage = 0.0
    def connect(self, resource_name: str, compliance_a: float, model: str | None = None) -> str:
        model = self.model if model is None else str(model).strip()
        if model not in KEITHLEY_MODELS:
            raise ValueError(f"Keithley model must be one of {', '.join(KEITHLEY_MODELS)}")
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py")
        if not 0 < compliance_a <= 1.0:
            raise ValueError("Current protection value must be between 0 and 1 A")
        with self.lock:
            if self.instrument is not None:
                if model != self.model:
                    raise RuntimeError("Disconnect before changing the Keithley model")
                return self.identity
            previous_model, self.model = self.model, model
            try:
                acquire_instrument_lease(resource_name, self, f"Keithley {self.model}")
            except BaseException:
                self.model = previous_model
                raise
            manager = None
            instrument = None
            try:
                manager = acquire_shared_visa_manager()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 5000
                instrument.write_termination = "\n"
                instrument.read_termination = "\n"
                identity = instrument.query("*IDN?").strip()
                if not self.identity_matches(identity, self.model):
                    raise RuntimeError(f'The device returned by {resource_name} is not a Keithley {self.model}: {identity}; check the model selected on the page')
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = identity
                self.compliance_a = compliance_a
                self.instrument.write("*CLS")
                self._write_checked(":OUTP OFF")
                self.output_enabled = False
                self._configure_voltage_source_locked()
                self.last_set_voltage = 0.0
                self.logger(f"Keithley connected: {identity}")
                return identity
            except BaseException as error:
                if instrument is not None:
                    try:
                        instrument.write(":SOUR:VOLT 0")
                        instrument.write(":OUTP OFF")
                    except BaseException:
                        pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                self.resource_manager = None
                self.instrument = None
                self.source_mode = None
                self.model = previous_model
                release_instrument_lease(resource_name, self)
                raise
    def enable_output(self, max_abs_voltage: float = 0.0) -> None:
        if not math.isfinite(float(max_abs_voltage)):
            raise ValueError("Maximum scan voltage must be a finite value")
        if abs(float(max_abs_voltage)) > self.max_abs_voltage_v:
            raise ValueError(f'Maximum scan voltage exceeds the {self.model} software limit ±{self.max_abs_voltage_v:g} V')
        if abs(float(max_abs_voltage)) > KEITHLEY_LOW_SOURCE_RANGE_V and self.compliance_a > self.high_range_max_compliance_a:
            raise ValueError(
                f"{self.model} current protection in the {self.high_range_v:g} V source range is at most "
                f"{self.high_range_max_compliance_a * 1e3:g} mA; current setting {self.compliance_a:g} A "
                "(Disconnect, then Connect with a lower Current limit)"
            )
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"Keithley {self.model} is not connected")
            if self.output_enabled:
                self._write_checked(":SOUR:VOLT 0")
                self._write_checked(":OUTP OFF")
                self.output_enabled = False
            self._configure_voltage_source_locked(abs(float(max_abs_voltage)))
            self._write_checked(":OUTP ON")
            self.output_enabled = True
    def set_voltage(self, voltage: float) -> float:
        voltage = float(voltage)
        if not math.isfinite(voltage):
            raise ValueError("Requested voltage must be a finite value")
        if abs(voltage) > self.max_abs_voltage_v:
            raise ValueError(f'Requested voltage {voltage:g} V exceeds the {self.model} software limit ±{self.max_abs_voltage_v:g} V')
        if abs(voltage) > KEITHLEY_LOW_SOURCE_RANGE_V and self.compliance_a > self.high_range_max_compliance_a:
            raise ValueError(f'{self.model} current protection must not exceed {self.high_range_max_compliance_a * 1000.0:g} mA above 20 V')
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"Keithley {self.model} is not connected")
            if self.source_mode != "VOLT":
                raise RuntimeError(f"{self.model} is not in voltage-source mode; please restart the voltage scan first")
            if self.source_voltage_range_v is None or abs(voltage) > self.source_voltage_range_v + 1e-09:
                raise RuntimeError(f'{self.model} current voltage range is insufficient; the scan must first be initialized for the full voltage range')
            self._write_checked(f":SOUR:VOLT {voltage:.6f}")
            self.last_set_voltage = voltage
            actual = float(self.instrument.query(":SOUR:VOLT?").strip())
            if not math.isfinite(actual):
                raise RuntimeError(f"{self.model} voltage readback is invalid: {actual!r}")
            return actual
    def apply_manual_voltage(self, voltage: float) -> float:
        voltage = float(voltage)
        if not math.isfinite(voltage):
            raise ValueError("Requested voltage must be a finite value")
        if abs(voltage) > self.max_abs_voltage_v:
            raise ValueError(f'Requested voltage {voltage:g} V exceeds the {self.model} software limit ±{self.max_abs_voltage_v:g} V')
        if abs(voltage) > KEITHLEY_LOW_SOURCE_RANGE_V and self.compliance_a > self.high_range_max_compliance_a:
            raise ValueError(
                f"{self.model} current protection must not exceed "
                f"{self.high_range_max_compliance_a * 1e3:g} mA above 20 V; current setting "
                f"{self.compliance_a:g} A (Disconnect, then Connect with a lower Current limit)"
            )
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"Keithley {self.model} is not connected")
            required_range = self._required_voltage_range(voltage)
            range_change = self.source_mode != 'VOLT' or self.source_voltage_range_v is None or (not math.isclose(self.source_voltage_range_v, required_range, rel_tol=0.0, abs_tol=1e-06))
            if range_change:
                if self.output_enabled:
                    self._write_checked(":SOUR:VOLT 0")
                    self._write_checked(":OUTP OFF")
                    self.output_enabled = False
                self._configure_voltage_source_locked(abs(voltage))
            if not self.output_enabled:
                self._write_checked(":OUTP ON")
                self.output_enabled = True
            self._write_checked(f":SOUR:VOLT {voltage:.9g}")
            actual = float(self.instrument.query(":SOUR:VOLT?").strip())
            if not math.isfinite(actual):
                raise RuntimeError(f"{self.model} voltage readback is invalid: {actual!r}")
            self.last_set_voltage = actual
            return actual
    def zero_voltage(self) -> float | None:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"Keithley {self.model} is not connected")
            if not self.output_enabled:
                self.output_off()
                return None
            if self.source_mode != "VOLT":
                raise RuntimeError(f'{self.model} is not in voltage-source mode; Zero sent nothing (use the red zero / output off button)')
            self._write_checked(":SOUR:VOLT 0")
            actual = float(self.instrument.query(":SOUR:VOLT?").strip())
            if not math.isfinite(actual) or abs(actual) > 1e-6:
                raise RuntimeError(f'{self.model} voltage readback after Zero is {actual!r}, not 0 V')
            self.last_set_voltage = 0.0
            return actual
    def output_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                return
            errors = []
            zero_command = ':SOUR:CURR 0' if self.source_mode == 'CURR' else ':SOUR:VOLT 0'
            for command in (zero_command, ":OUTP OFF"):
                try:
                    self.instrument.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            self.last_set_voltage = 0.0
            if errors:
                raise RuntimeError(f"{self.model} failed to turn output off: " + "; ".join(errors))
    def output_off_read_back(self) -> None:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError(f"Keithley {self.model} is not connected; its output state is unknown")
            failure = None
            try:
                self.output_off()
            except BaseException as error:
                failure = error
            after = f" (after: {failure})" if failure is not None else ""
            level_query = ":SOUR:CURR?" if self.source_mode == "CURR" else ":SOUR:VOLT?"
            try:
                state = int(round(float(self.instrument.query(":OUTP?").strip())))
                level = float(self.instrument.query(level_query).strip())
            except BaseException as error:
                raise RuntimeError(f"{self.model} output could not be read back: {error}{after}") from error
            if state != 0 or not math.isfinite(level) or abs(level) > 1e-6:
                raise RuntimeError(f'{self.model} did not read back 0 and OFF (:OUTP? {state}, {level_query} {level:g}){after}')
            if failure is not None:
                self.logger(f"Keithley {self.model}: read back 0 and OFF{after}")
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            if instrument is not None:
                for command in ("*CLS", ":SYST:LOC"):
                    try:
                        instrument.write(command)
                    except BaseException:
                        pass
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            self.output_enabled = False
            self.last_set_voltage = 0.0
            self.source_mode = None
            self.source_voltage_range_v = None
            release_instrument_lease(resource_name, self)
            self.logger(f"Keithley {self.model} disconnected")
            if shutdown_error is not None:
                raise shutdown_error
class Keithley6221Controller:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.resource_manager = None
        self.instrument = None
        self.resource_name = ""
        self.identity = ""
        self.output_enabled = False
        self.current_a = 0.0
        self.pulse_width_s = K6221_DEFAULT_PULSE_WIDTH_US / 1_000_000.0
        self.pulse_count = K6221_DEFAULT_PULSE_COUNT
        self.compliance_v = K6221_DEFAULT_COMPLIANCE_V
        self.output_mode = "OFF"
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def _query_error(self, command: str) -> None:
        response = self.instrument.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"6221 returned an unparsable error status: {response}") from error
        if code != 0:
            raise RuntimeError(f"6221 SCPI error after '{command}': {response}")
    def _write_checked(self, command: str) -> None:
        self.instrument.write(command)
        self._query_error(command)
    def _read_output_low_to_earth(self) -> int:
        text = self.instrument.query(K6221_OUTPUT_LOW_QUERY).strip().upper()
        if text in ("0", "OFF"):
            return 0
        if text in ("1", "ON"):
            return 1
        raise RuntimeError(f"6221 returned an unexpected OUTP:LTE state: {text!r}")
    def _set_output_low_floating(self) -> None:
        if self._read_output_low_to_earth() == 0:
            return
        self._write_checked(K6221_OUTPUT_LOW_FLOATING)
        if self._read_output_low_to_earth() != 0:
            raise RuntimeError('6221 output low stayed earth-grounded; set TRIAX -> OUTPUT LOW -> FLOATING on the front panel')
    @staticmethod
    def _validate(current_a: float, pulse_width_s: float, compliance_v: float, pulse_count: int):
        current_a = float(current_a)
        pulse_width_s = float(pulse_width_s)
        compliance_v = float(compliance_v)
        try:
            pulse_count_numeric = float(pulse_count)
        except (TypeError, ValueError) as error:
            raise ValueError("6221 pulse count must be an integer") from error
        if not math.isfinite(pulse_count_numeric) or not pulse_count_numeric.is_integer():
            raise ValueError("6221 pulse count must be an integer")
        pulse_count = int(pulse_count_numeric)
        if not all((math.isfinite(value) for value in (current_a, pulse_width_s, compliance_v))):
            raise ValueError("6221 current, pulse width and compliance voltage must be finite values")
        if abs(current_a) > K6221_MAX_ABS_CURRENT_A:
            raise ValueError(f'6221 current exceeds the software limit ±{K6221_MAX_ABS_CURRENT_A * 1000:g} mA')
        if 0.0 < abs(current_a) < K6221_MIN_NONZERO_CURRENT_A:
            raise ValueError("6221 non-zero pulse current magnitude cannot be less than 4 pA")
        if not K6221_MIN_PULSE_WIDTH_S <= pulse_width_s <= K6221_MAX_PULSE_WIDTH_S:
            raise ValueError(f'6221 pulse width must be between {K6221_MIN_PULSE_WIDTH_S * 1000000.0:g} us–{K6221_MAX_PULSE_WIDTH_S:g} s')
        if not K6221_MIN_COMPLIANCE_V <= compliance_v <= K6221_MAX_COMPLIANCE_V:
            raise ValueError(f'6221 compliance voltage must be between {K6221_MIN_COMPLIANCE_V:g}–{K6221_MAX_COMPLIANCE_V:g} V')
        if not 1 <= pulse_count <= K6221_MAX_PULSE_COUNT:
            raise ValueError(f'6221 pulse count must be between 1 and {K6221_MAX_PULSE_COUNT}')
        total_time_s = 2.0 * pulse_width_s * pulse_count
        if total_time_s > K6221_MAX_WAVEFORM_TIME_S:
            raise ValueError(f'Total waveform time (pulse width × pulse count) exceeds {K6221_MAX_WAVEFORM_TIME_S:g} s')
        return current_a, pulse_width_s, compliance_v, pulse_count
    def connect(self, resource_name: str, compliance_v: float) -> str:
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py")
        _, _, compliance_v, _ = self._validate(0.0, self.pulse_width_s, compliance_v, self.pulse_count)
        with self.lock:
            if self.instrument is not None:
                return self.identity
            acquire_instrument_lease(resource_name, self, "Keithley 6221 pulse")
            manager = None
            instrument = None
            try:
                manager = acquire_shared_visa_manager()
                instrument = manager.open_resource(resource_name)
                instrument.timeout = 5000
                instrument.write_termination = "\n"
                instrument.read_termination = "\n"
                identity = instrument.query("*IDN?").strip()
                if "6221" not in identity.upper():
                    raise RuntimeError(f'The device returned by {resource_name} is not a Keithley 6221: {identity}')
                self.resource_manager = manager
                self.instrument = instrument
                self.resource_name = resource_name
                self.identity = identity
                self.compliance_v = compliance_v
                instrument.write("*RST")
                instrument.write("*CLS")
                self._set_output_low_floating()
                self._write_checked(f"CURR:COMP {compliance_v:.12g}")
                self._write_checked("OUTP OFF")
                self.output_enabled = False
                self.current_a = 0.0
                self.output_mode = "OFF"
                self.logger(f"Keithley 6221 connected: {identity}")
                return identity
            except BaseException:
                if instrument is not None:
                    for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                        try:
                            instrument.write(command)
                        except BaseException:
                            pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                self.resource_manager = None
                self.instrument = None
                release_instrument_lease(resource_name, self)
                raise
    def read_output_state(self) -> dict[str, object]:
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Keithley 6221 is not connected")
            output_on = bool(round(float(self.instrument.query('OUTP?').strip())))
            compliance_v = float(self.instrument.query('CURR:COMP?').strip())
            measurement_condition = int(round(float(self.instrument.query('STAT:MEAS:COND?').strip())))
            mode = self.output_mode if output_on else "OFF"
            frequency_hz = math.nan
            if mode in {"AC", "PULSE"}:
                amplitude_a = float(self.instrument.query('SOUR:WAVE:AMPL?').strip())
                offset_a = float(self.instrument.query('SOUR:WAVE:OFFS?').strip())
                frequency_hz = float(self.instrument.query('SOUR:WAVE:FREQ?').strip())
                if mode == "AC":
                    current_a = amplitude_a / math.sqrt(2.0)
                else:
                    sign_source = offset_a if offset_a != 0 else 1.0
                    current_a = math.copysign(abs(offset_a) + abs(amplitude_a), sign_source)
            else:
                current_a = float(self.instrument.query('SOUR:CURR?').strip())
            self.output_enabled = output_on
            self.current_a = current_a if output_on else 0.0
            self.compliance_v = compliance_v
            if not output_on:
                self.output_mode = "OFF"
            return {
                "mode": mode,
                "current_a": current_a,
                "frequency_hz": frequency_hz,
                "compliance_v": compliance_v,
                "output_on": output_on,
                "measurement_condition": measurement_condition,
                "in_compliance": bool(measurement_condition & 8),
                "sample_monotonic": time.monotonic(),
            }
    def set_dc_pulse(self, current_a: float, pulse_width_s: float, compliance_v: float, pulse_count: int) -> dict[str, object]:
        current_a, pulse_width_s, compliance_v, pulse_count = self._validate(current_a, pulse_width_s, compliance_v, pulse_count)
        with self.lock:
            if self.instrument is None:
                raise RuntimeError("Keithley 6221 is not connected")
            if current_a == 0.0:
                self.output_off()
                return {
                    "mode": "OFF",
                    "current_a": 0.0,
                    "pulse_width_s": pulse_width_s,
                    "frequency_hz": 1.0 / (2.0 * pulse_width_s),
                    "compliance_v": compliance_v,
                    "pulse_count": pulse_count,
                    "total_time_s": 0.0,
                    "output_on": False,
                    "measurement_condition": 0,
                    "in_compliance": False,
                    "sample_monotonic": time.monotonic(),
                }
            frequency_hz = 1.0 / (2.0 * pulse_width_s)
            amplitude_a = abs(current_a) / 2.0
            offset_a = current_a / 2.0
            commands = (
                "SOUR:WAVE:ABOR",
                f"CURR:COMP {compliance_v:.12g}",
                "SOUR:WAVE:FUNC SQU",
                "SOUR:WAVE:DCYC 50",
                f"SOUR:WAVE:AMPL {amplitude_a:.12e}",
                f"SOUR:WAVE:OFFS {offset_a:.12e}",
                f"SOUR:WAVE:FREQ {frequency_hz:.12g}",
                "SOUR:WAVE:RANG BEST",
                "SOUR:WAVE:PMAR:STAT OFF",
                "SOUR:WAVE:EXTR OFF",
                f"SOUR:WAVE:DUR:CYCL {pulse_count}",
                "SOUR:WAVE:ARM",
                "OUTP ON",
                "SOUR:WAVE:INIT",
            )
            for command in commands:
                self._write_checked(command)
            actual_amplitude = float(self.instrument.query("SOUR:WAVE:AMPL?").strip())
            actual_offset = float(self.instrument.query("SOUR:WAVE:OFFS?").strip())
            actual_frequency = float(self.instrument.query("SOUR:WAVE:FREQ?").strip())
            actual_compliance = float(self.instrument.query("CURR:COMP?").strip())
            actual_cycles = int(round(float(self.instrument.query('SOUR:WAVE:DUR:CYCL?').strip())))
            output_state = int(round(float(self.instrument.query("OUTP?").strip())))
            measurement_condition = int(round(float(self.instrument.query('STAT:MEAS:COND?').strip())))
            checks = (
                ("amplitude", actual_amplitude, amplitude_a, 5e-4, 1e-12),
                ("offset", actual_offset, offset_a, 5e-4, 1e-12),
                ("frequency", actual_frequency, frequency_hz, 5e-4, 1e-6),
                ("compliance voltage", actual_compliance, compliance_v, 5e-4, 1e-6),
            )
            for label, actual, requested, rel_tol, abs_tol in checks:
                if not math.isfinite(actual) or not math.isclose(actual, requested, rel_tol=rel_tol, abs_tol=abs_tol):
                    self.output_off()
                    raise RuntimeError(f'6221 {label} readback mismatch: requested {requested:g}, readback {actual:g}')
            if actual_cycles != pulse_count:
                self.output_off()
                raise RuntimeError(f'6221 pulse count readback mismatch: requested {pulse_count}, readback {actual_cycles}')
            completed_before_readback = output_state == 0
            self.current_a = math.copysign(abs(actual_offset) + abs(actual_amplitude), current_a)
            self.pulse_width_s = 1.0 / (2.0 * actual_frequency)
            self.compliance_v = actual_compliance
            self.pulse_count = pulse_count
            self.output_enabled = bool(output_state)
            self.output_mode = "PULSE" if output_state else "OFF"
            return {
                "mode": "PULSE",
                "current_a": self.current_a,
                "pulse_width_s": self.pulse_width_s,
                "frequency_hz": actual_frequency,
                "compliance_v": actual_compliance,
                "pulse_count": pulse_count,
                "total_time_s": 2.0 * self.pulse_width_s * pulse_count,
                "output_on": bool(output_state),
                "completed_before_readback": completed_before_readback,
                "measurement_condition": measurement_condition,
                "in_compliance": bool(measurement_condition & 8),
                "sample_monotonic": time.monotonic(),
            }
    def output_off(self) -> None:
        with self.lock:
            if self.instrument is None:
                return
            errors = []
            for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                try:
                    self.instrument.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            self.current_a = 0.0
            self.output_mode = "OFF"
            if errors:
                raise RuntimeError("6221 failed to turn output off: " + "; ".join(errors))
    def disconnect(self) -> None:
        with self.lock:
            instrument = self.instrument
            manager = self.resource_manager
            resource_name = self.resource_name
            if instrument is None and manager is None:
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            if instrument is not None:
                for command in ("*CLS", "SYST:LOC"):
                    try:
                        instrument.write(command)
                    except BaseException:
                        pass
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = None
            self.resource_manager = None
            self.resource_name = ""
            self.identity = ""
            self.output_enabled = False
            self.current_a = 0.0
            release_instrument_lease(resource_name, self)
            self.logger("Keithley 6221 disconnected")
            if shutdown_error is not None:
                raise shutdown_error
class NonLocalVI2410Controller:
    def __init__(self, logger: Callable[[str], None], model: str = KEITHLEY_DEFAULT_MODEL) -> None:
        self.logger = logger
        self.model = KEITHLEY_DEFAULT_MODEL
        self.manager = None
        self.instrument = None
        self.identity = ""
        self.resource_name = ""
        self.source_mode = None
        self.output_enabled = False
        self.iv_sweep_max_abs_v = NONLOCAL_VI_MAX_ABS_PULSE_V
        self.high_voltage_active = False
        self.lock = threading.RLock()
        self.set_model(model)
    @property
    def connected(self) -> bool:
        return self.instrument is not None
    def set_model(self, model: str) -> None:
        model = str(model).strip()
        if model not in KEITHLEY_MODELS:
            raise ValueError(f"Keithley model must be one of {', '.join(KEITHLEY_MODELS)}")
        if self.instrument is not None and model != self.model:
            raise RuntimeError("Disconnect before changing the Keithley model")
        self.model = model
    def _require_instrument(self):
        if self.instrument is None:
            raise RuntimeError(f"Non-local VI Keithley {self.model} is not connected")
        return self.instrument
    def _write_checked(self, command: str) -> None:
        self._require_instrument().write(command)
        self._check_error(command)
    def _check_error(self, command: str, after: str | None = None) -> None:
        instrument = self._require_instrument()
        time.sleep(0.03)
        response = instrument.query("SYST:ERR?").strip()
        try:
            code = int(response.split(",", 1)[0].strip())
        except ValueError as error:
            raise RuntimeError(f"Keithley {self.model} error status cannot be parsed: {response}") from error
        if code != 0:
            raise RuntimeError(f'Keithley {self.model} reported an error after {after or repr(command)}: {response}')
    def _query_float(self, command: str) -> float:
        return float(self._require_instrument().query(command).strip())
    def connect(self, resource: str, model: str | None = None) -> str:
        model = self.model if model is None else str(model).strip()
        if model not in KEITHLEY_MODELS:
            raise ValueError(f"Keithley model must be one of {', '.join(KEITHLEY_MODELS)}")
        if pyvisa is None:
            raise RuntimeError('pyvisa is missing; please run in PowerShell: py -m pip install pyvisa pyvisa-py')
        with self.lock:
            if self.connected:
                if model != self.model:
                    raise RuntimeError("Disconnect before changing the Keithley model")
                return self.identity
            previous_model, self.model = self.model, model
            try:
                acquire_instrument_lease(resource, self, f"Non-local VI {self.model}")
            except BaseException:
                self.model = previous_model
                raise
            manager = None
            instrument = None
            try:
                manager = acquire_shared_visa_manager()
                instrument = manager.open_resource(resource)
                instrument.timeout = 10000
                instrument.write_termination = "\n"
                instrument.read_termination = "\n"
                try:
                    instrument.query_delay = 0.05
                except (AttributeError, ValueError):
                    pass
                identity = instrument.query("*IDN?").strip()
                if not Keithley2410Controller.identity_matches(identity, self.model):
                    raise RuntimeError(f'{resource} is not a Keithley {self.model}: {identity}; check the model selected on the page')
                self.manager = manager
                self.instrument = instrument
                self.identity = identity
                self.resource_name = resource
                self.setup_voltage_mode(NONLOCAL_VI_2410_CURRENT_COMPLIANCE_A)
                self.logger(f"Non-local VI Keithley {self.model} connected: {identity}")
                return identity
            except BaseException:
                if instrument is not None:
                    for command in (":SOUR:VOLT 0", ":OUTP OFF"):
                        try:
                            instrument.write(command)
                        except BaseException:
                            pass
                    try:
                        instrument.close()
                    except BaseException:
                        pass
                release_shared_visa_manager(manager)
                self.manager = self.instrument = None
                self.identity = ""
                self.resource_name = ""
                self.source_mode = None
                self.output_enabled = False
                self.model = previous_model
                release_instrument_lease(resource, self)
                raise
    def _drain_before_reset_locked(self) -> None:
        if not self.__dict__.get("high_voltage_active") and int(self._query_float(":OUTP?")) == 1:
            self.high_voltage_active = self.source_mode != "CURR"
        if self.__dict__.get("high_voltage_active"):
            self.safe_shutdown(reset=False)
    def setup_voltage_mode(self, current_compliance_a: float) -> None:
        with self.lock:
            instrument = self._require_instrument()
            self._drain_before_reset_locked()
            self.iv_sweep_max_abs_v = NONLOCAL_VI_MAX_ABS_PULSE_V
            instrument.write("*RST")
            instrument.write("*CLS")
            for command in (
                ":SOUR:FUNC VOLT",
                ":SOUR:VOLT:MODE FIXED",
                f":SOUR:VOLT:PROT {NONLOCAL_VI_2410_SOURCE_OVP_V:.12g}",
                f":SOUR:VOLT:RANG {KEITHLEY_LOW_SOURCE_RANGE_V:.12g}",
                ":SOUR:VOLT 0",
                ":SENS:FUNC 'CURR'",
                f":SENS:CURR:PROT {current_compliance_a:.12g}",
                ":SENS:CURR:RANG:AUTO ON",
                ":FORM:ELEM VOLT,CURR",
                ":OUTP OFF",
            ):
                self._write_checked(command)
            self.source_mode = "VOLT"
            self.output_enabled = False
            self.high_voltage_active = False
            ovp = self._query_float(":SOUR:VOLT:PROT?")
            source_range = self._query_float(":SOUR:VOLT:RANG?")
            if not (
                math.isfinite(ovp)
                and abs(ovp - NONLOCAL_VI_2410_SOURCE_OVP_V) <= NONLOCAL_VI_2410_SOURCE_OVP_V * 0.01
                and math.isfinite(source_range)
                and KEITHLEY_LOW_SOURCE_RANGE_V <= source_range + 1e-9
                and source_range <= KEITHLEY_LOW_SOURCE_RANGE_V * 1.06
            ):
                raise RuntimeError(f'Keithley {self.model} pulse setup reads OVP {ovp:g} V and range {source_range:g} V, not {NONLOCAL_VI_2410_SOURCE_OVP_V:g} V and {KEITHLEY_LOW_SOURCE_RANGE_V:g} V')
            self.confirm_output_off("after voltage-mode initialization")
    def confirm_output_off(self, context: str) -> None:
        with self.lock:
            state = int(self._query_float(":OUTP?"))
            if state != 0:
                self.safe_shutdown(reset=False)
                state = int(self._query_float(":OUTP?"))
            if state != 0:
                raise RuntimeError(f'Keithley {self.model} output is still ON {context}; reading the SR830 is forbidden')
            self.output_enabled = False
    def safe_shutdown(self, reset: bool = False) -> None:
        with self.lock:
            instrument = self.instrument
            if instrument is None:
                return
            errors = []
            zero_command = ':SOUR:CURR 0' if self.source_mode == 'CURR' else ':SOUR:VOLT 0'
            commands = [zero_command, ":OUTP OFF"]
            if reset:
                commands.extend(("*RST", "*CLS"))
            drain = self.source_mode != "CURR" and bool(self.__dict__.get("high_voltage_active"))
            try:
                instrument.write(zero_command)
            except BaseException as error:
                errors.append(f"{zero_command}: {error}")
            if drain:
                try:
                    drain = int(round(float(instrument.query(":OUTP?").strip()))) == 1
                except BaseException as error:
                    errors.append(f":OUTP?: {error}")
                    drain = False
                if not drain:
                    self.high_voltage_active = False
                else:
                    try:
                        self._drain_locked(instrument)
                    except BaseException as error:
                        errors.append(str(error))
            for command in commands[1:]:
                try:
                    instrument.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            if drain and not errors:
                self.high_voltage_active = False
            self.output_enabled = False
            self.iv_sweep_max_abs_v = NONLOCAL_VI_MAX_ABS_PULSE_V
            if reset:
                self.source_mode = None
            if errors:
                raise RuntimeError(f'Keithley {self.model} safe shutdown failed: ' + '; '.join(errors))
    def _drain_locked(self, instrument) -> None:
        started = time.monotonic()
        time.sleep(NONLOCAL_KEITHLEY_DISCHARGE_S)
        limit_a = abs(float(instrument.query(":SENS:CURR:PROT?").strip()))
        calm = 0
        while True:
            values = [float(value) for value in instrument.query(":READ?").strip().split(",")]
            calm = calm + 1 if abs(values[1]) < 0.9 * limit_a else 0
            if calm >= 2:
                return
            if time.monotonic() - started >= NONLOCAL_KEITHLEY_DRAIN_MAX_S:
                raise RuntimeError(f'Keithley {self.model} still at its {limit_a:g} A current limit after {NONLOCAL_KEITHLEY_DRAIN_MAX_S:g} s at 0 V: the sample may still be charged')
            time.sleep(NONLOCAL_KEITHLEY_SAMPLE_INTERVAL_S)
    def disconnect(self) -> None:
        with self.lock:
            instrument, manager = self.instrument, self.manager
            resource_name = self.resource_name
            error = None
            try:
                self.safe_shutdown(reset=True)
            except BaseException as caught:
                error = caught
            self.high_voltage_active = False
            if instrument is not None:
                try:
                    instrument.close()
                except BaseException:
                    pass
            release_shared_visa_manager(manager)
            self.instrument = self.manager = None
            self.identity = ""
            self.resource_name = ""
            self.source_mode = None
            self.output_enabled = False
            release_instrument_lease(resource_name, self)
            self.logger(f"Non-local VI Keithley {self.model} zeroed, output turned off and disconnected")
            if error is not None:
                raise error
_MFLI_BRIDGE_PREFIX = "MOKE_MFLI_JSON:"
_MFLI_BRIDGE_SOURCE = r'''
from __future__ import print_function

import json
import math
import sys
import time
import traceback

PREFIX = "MOKE_MFLI_JSON:"
DEVICE_REQUEST = sys.argv[1]
API_LEVEL = int(sys.argv[2])
DEMOD = int(sys.argv[3])
EXTREF_DEMOD = 1
EXTREF = 0
# The id of the request being answered, echoed in its reply, so a reply that
# arrives after its request timed out is never taken for the next one's.
REQUEST_ID = None


def emit(payload):
    if REQUEST_ID is not None and "id" not in payload:
        payload["id"] = REQUEST_ID
    sys.stdout.write(PREFIX + json.dumps(payload, ensure_ascii=True) + "\n")
    sys.stdout.flush()


def scalar(sample, field, required=True):
    try:
        value = sample[field]
    except (KeyError, TypeError):
        if required:
            raise RuntimeError("MFLI sample missing field: " + field)
        return None
    try:
        value = value[-1]
    except (IndexError, KeyError, TypeError):
        pass
    result = float(value)
    if not math.isfinite(result):
        raise RuntimeError("MFLI sample has non-finite field: " + field)
    return result


def input_state(reset_extrema=False):
    range_node = "/%s/sigins/0/range" % device
    max_node = "/%s/sigins/0/max" % device
    min_node = "/%s/sigins/0/min" % device
    result = {"input_range_v": float(daq.getDouble(range_node))}
    try:
        result["input_max_normalized"] = float(daq.getDouble(max_node))
        result["input_min_normalized"] = float(daq.getDouble(min_node))
        if reset_extrema:
            daq.setDouble(max_node, 0.0)
            daq.setDouble(min_node, 0.0)
    except Exception:
        result["input_max_normalized"] = None
        result["input_min_normalized"] = None
    return result


def run_autorange(timeout_s=8.0):
    old_range = float(daq.getDouble("/%s/sigins/0/range" % device))
    autorange_node = "/%s/sigins/0/autorange" % device
    daq.setInt(autorange_node, 1)
    # As zhinst.utils.sigin_autorange: the set must take effect before the
    # poll, or a stale 0 ends it at once.
    daq.sync()
    deadline = time.monotonic() + float(timeout_s)
    while int(daq.getInt(autorange_node)) != 0:
        if time.monotonic() >= deadline:
            raise RuntimeError("MFLI Signal Input 1 autorange timed out")
        time.sleep(0.02)
    daq.sync()
    result = input_state(reset_extrema=True)
    result["old_input_range_v"] = old_range
    return result


daq = None
device = ""
configured_extref_demod = DEMOD
try:
    import zhinst.utils as zi_utils

    session = zi_utils.create_api_session(DEVICE_REQUEST, API_LEVEL)
    if not isinstance(session, tuple) or len(session) < 3:
        raise RuntimeError("Unexpected create_api_session result: %r" % (session,))
    daq, discovered, props = session[:3]
    device = str(discovered).strip().lower()
    if not device:
        raise RuntimeError("LabOne Discovery returned an empty device name")
    try:
        zi_utils.api_server_version_check(daq)
    except AttributeError:
        pass
    enable_node = "/%s/demods/%d/enable" % (device, DEMOD)
    daq.setInt(enable_node, 1)
    daq.sync()
    daq.getSample("/%s/demods/%d/sample" % (device, DEMOD))
    version = ""
    options = ""
    if isinstance(props, dict):
        version = str(props.get("serverversion") or props.get("version") or "")
        raw_options = props.get("options") or ""
        if isinstance(raw_options, (tuple, list)):
            options = ",".join(str(item) for item in raw_options)
        else:
            options = str(raw_options)
    if not options:
        try:
            options = str(daq.getString("/%s/features/options" % device))
        except Exception:
            pass
    try:
        daq.getInt("/%s/demods/1/enable" % device)
        has_demod_2 = True
    except Exception:
        has_demod_2 = False
    try:
        daq.getInt("/%s/demods/3/enable" % device)
        daq.getInt("/%s/extrefs/1/demodselect" % device)
        has_demod_4 = True
    except Exception:
        has_demod_4 = False
    identity = "Zurich Instruments MFLI - " + device
    if version:
        identity += " - LabOne " + version
    emit({"ok": True, "event": "ready", "device": device,
          "version": version, "options": options,
          "has_demod_2": has_demod_2, "has_demod_4": has_demod_4, "identity": identity})
except BaseException:
    emit({"ok": False, "event": "ready", "error": traceback.format_exc()})
    try:
        if daq is not None:
            daq.disconnect()
    except BaseException:
        pass
    sys.exit(2)

for request_line in sys.stdin:
    REQUEST_ID = None
    try:
        request = json.loads(request_line)
        REQUEST_ID = request.get("id")
        command = request.get("command")
        if command in ("configure_second_harmonic", "configure_third_harmonic"):
            harmonic = 2 if command == "configure_second_harmonic" else 3
            measurement_demod = harmonic - 1 if configured_extref_demod == 3 else harmonic
            base = "/%s/demods/%d/" % (device, measurement_demod)
            if configured_extref_demod not in (1, 3) or measurement_demod == configured_extref_demod:
                raise RuntimeError("Measurement demodulator conflicts with external reference")
            for name, value in (("adcselect", 0), ("oscselect", 0), ("harmonic", harmonic),
                                ("order", int(request["order"])), ("enable", 1)):
                daq.setInt(base + name, value)
            for name in ("timeconstant", "rate"):
                daq.setDouble(base + name, float(request[name]))
            daq.sync()
            for name, value in (("adcselect", 0), ("oscselect", 0), ("harmonic", harmonic), ("enable", 1)):
                if daq.getInt(base + name) != value:
                    raise RuntimeError("Additional harmonic readback mismatch: " + name)
            emit({"ok": True})
        elif command == "disable_unused_demods":
            for index in request["indices"]:
                if index not in (1, 2, 3) or index == configured_extref_demod:
                    raise RuntimeError("Cannot disable active reference demodulator")
                node = "/%s/demods/%d/enable" % (device, index)
                daq.setInt(node, 0)
                daq.sync()
                if daq.getInt(node) != 0:
                    raise RuntimeError("Unused demodulator disable readback mismatch")
            emit({"ok": True})
        elif command == "configure":
            requested_ac = 1 if str(request["coupling"]).upper() == "AC" else 0
            requested_imp50 = int(request.get("input_imp50", 0))
            requested_scaling = float(request.get("input_scaling", 1.0))
            requested_harmonic = int(request["harmonic"])
            requested_reference_input = int(request["reference_adcselect"])
            requested_timeconstant = float(request["timeconstant_s"])
            requested_order = int(request["filter_order"])
            requested_rate = float(request["sample_rate_hz"])
            extref_demod = int(request.get("extref_demod", EXTREF_DEMOD))
            if extref_demod == 3:
                routes = [i for i in range(2)
                          if int(daq.getInt("/%s/extrefs/%d/demodselect" % (device, i))) == 3]
                if len(routes) != 1:
                    raise RuntimeError("Cannot identify external reference controller for Demod 4")
                EXTREF = routes[0]
            else:
                EXTREF = 0
            for other in range(2):
                # Only the chosen reference PLL: another left on (an earlier
                # session) would drive oscillator 0 as well.
                if other != EXTREF:
                    try:
                        daq.setInt("/%s/extrefs/%d/enable" % (device, other), 0)
                    except Exception:
                        pass
            configured_extref_demod = extref_demod
            ac_node = "/%s/sigins/0/ac" % device
            imp50_node = "/%s/sigins/0/imp50" % device
            scaling_node = "/%s/sigins/0/scaling" % device
            harmonic_node = "/%s/demods/%d/harmonic" % (device, DEMOD)
            enable_node = "/%s/demods/%d/enable" % (device, DEMOD)
            osc_node = "/%s/demods/%d/oscselect" % (device, DEMOD)
            extref_demod_node = "/%s/extrefs/%d/demodselect" % (device, EXTREF)
            extref_auto_node = "/%s/extrefs/%d/automode" % (device, EXTREF)
            extref_enable_node = "/%s/extrefs/%d/enable" % (device, EXTREF)
            extref_adc_node = "/%s/extrefs/%d/adcselect" % (device, EXTREF)
            measurement_adc_node = "/%s/demods/%d/adcselect" % (device, DEMOD)
            timeconstant_node = "/%s/demods/%d/timeconstant" % (device, DEMOD)
            order_node = "/%s/demods/%d/order" % (device, DEMOD)
            rate_node = "/%s/demods/%d/rate" % (device, DEMOD)
            daq.setInt(ac_node, requested_ac)
            daq.setInt(imp50_node, requested_imp50)
            daq.setDouble(scaling_node, requested_scaling)
            ext_demod_node = "/%s/demods/%d/adcselect" % (device, extref_demod)
            ext_osc_node = "/%s/demods/%d/oscselect" % (device, extref_demod)
            ext_harmonic_node = "/%s/demods/%d/harmonic" % (device, extref_demod)
            ext_demod_enable_node = "/%s/demods/%d/enable" % (device, extref_demod)
            daq.setInt(ext_demod_node, requested_reference_input)
            daq.setInt(ext_osc_node, 0)
            if extref_demod != DEMOD:
                daq.setInt(ext_harmonic_node, 1)
            daq.setInt(ext_demod_enable_node, 1)
            selected_extref_input = int(daq.getInt(ext_demod_node))
            try:
                daq.setInt(extref_demod_node, extref_demod)
            except Exception:
                pass
            # automode/demodselect/locked were exposed as dedicated nodes in
            # newer LabOne releases.  LabOne 18.12 can still enable ExtRef,
            # but does not necessarily expose all three nodes to the API.
            try:
                daq.setInt(extref_auto_node, 4)
            except Exception:
                pass
            daq.setInt(extref_enable_node, 1)
            if extref_demod == 3:
                daq.sync()
                if daq.getInt(extref_demod_node) != 3:
                    raise RuntimeError("External reference Demod 4 readback mismatch")
            # A base MFLI temporarily uses Demod 1 to select/latch the chosen
            # external reference, then returns its measurement input to
            # Signal In 1.
            if extref_demod == DEMOD:
                daq.sync()
                if selected_extref_input != requested_reference_input:
                    raise RuntimeError(
                        "Requested external reference was not selected: "
                        "%d != %d" %
                        (selected_extref_input, requested_reference_input)
                    )
                daq.setInt(measurement_adc_node, 0)
            daq.setInt(osc_node, 0)
            daq.setInt(harmonic_node, requested_harmonic)
            daq.setDouble(timeconstant_node, requested_timeconstant)
            daq.setInt(order_node, requested_order)
            daq.setDouble(rate_node, requested_rate)
            daq.setInt(enable_node, 1)
            daq.sync()
            if extref_demod != DEMOD:
                try:
                    selected_extref_input = int(daq.getInt(extref_adc_node))
                except Exception:
                    pass
            configured_input = input_state(reset_extrema=True)
            emit({"ok": True, "extref_channel": EXTREF, "actual_ac": int(daq.getInt(ac_node)),
                  "actual_imp50": int(daq.getInt(imp50_node)),
                  "actual_scaling": float(daq.getDouble(scaling_node)),
                  "actual_harmonic": int(daq.getInt(harmonic_node)),
                  "actual_extref_harmonic": (
                      int(daq.getInt(ext_harmonic_node))
                      if extref_demod != DEMOD else 1),
                  "extref_enabled": int(daq.getInt(extref_enable_node)),
                  "extref_adcselect": selected_extref_input,
                  "timeconstant_s": float(daq.getDouble(timeconstant_node)),
                  "filter_order": int(daq.getInt(order_node)),
                  "sample_rate_hz": float(daq.getDouble(rate_node)),
                  "input_range_v": configured_input["input_range_v"]})
        elif command == "read":
            sample = daq.getSample("/%s/demods/%d/sample" % (device, DEMOD))
            payload = {"x": scalar(sample, "x"), "y": scalar(sample, "y")}
            frequency = scalar(sample, "frequency", required=False)
            flags = scalar(sample, "flags", required=False)
            if frequency is not None:
                payload["frequency"] = frequency
            if flags is not None:
                payload["flags"] = flags
            try:
                payload["extref_locked"] = int(daq.getInt(
                    "/%s/extrefs/%d/locked" % (device, EXTREF)))
            except Exception:
                payload["extref_locked"] = None
            payload.update(input_state(reset_extrema=True))
            try:
                payload["device_status_flags"] = int(daq.getInt(
                    "/%s/status/flags/binary" % device))
            except Exception:
                payload["device_status_flags"] = None
            emit({"ok": True, "sample": payload})
        elif command == "read_demods":
            channels = []
            for index in range(int(request.get("count", 4))):
                node = "/%s/demods/%d" % (device, index)
                enabled = int(daq.getInt(node + "/enable"))
                if not enabled:
                    channels.append({"enabled": 0})
                    continue
                raw = daq.getSample(node + "/sample")
                channels.append({"x": scalar(raw, "x"), "y": scalar(raw, "y"),
                    "frequency": scalar(raw, "frequency"),
                    "timestamp": scalar(raw, "timestamp", required=False),
                    "harmonic": int(daq.getInt(node + "/harmonic")),
                    "adcselect": int(daq.getInt(node + "/adcselect")), "enabled": enabled})
            emit({"ok": True, "demods": channels})
        elif command == "autorange":
            emit({"ok": True, "autorange": run_autorange()})
        elif command == "close":
            try:
                daq.setInt("/%s/extrefs/%d/enable" % (device, EXTREF), 0)
                daq.setInt("/%s/demods/%d/enable" % (device, DEMOD), 0)
                if configured_extref_demod != DEMOD:
                    daq.setInt("/%s/demods/%d/enable" %
                               (device, configured_extref_demod), 0)
                daq.sync()
            finally:
                daq.disconnect()
            emit({"ok": True})
            break
        else:
            raise ValueError("Unknown bridge command: %r" % (command,))
    except BaseException:
        emit({"ok": False, "error": traceback.format_exc()})
'''
def _find_mfli_legacy_python() -> Path:
    configured = os.environ.get(NONLOCAL_MFLI_LEGACY_PYTHON_ENV, "").strip()
    candidates = []
    if configured:
        candidates.append(Path(configured.strip('"')))
    system_drive = os.environ.get("SystemDrive", "C:")
    drive_root = Path(system_drive + os.sep if system_drive.endswith(':') else system_drive)
    user_profile = os.environ.get("USERPROFILE", "")
    local_app_data = os.environ.get("LOCALAPPDATA", "")
    if local_app_data:
        candidates.append(Path(local_app_data) / 'NBB/MOKE_MFLI_PY37/python.exe')
    candidates.append(PROGRAM_DIRECTORY / '.mfli_py37/python.exe')
    candidates.extend((drive_root / 'ProgramData/miniconda3/envs/GMS_VENV_PYTHON/python.exe', drive_root / 'ProgramData/anaconda3/envs/GMS_VENV_PYTHON/python.exe'))
    if user_profile:
        candidates.extend((Path(user_profile) / 'miniconda3/envs/GMS_VENV_PYTHON/python.exe', Path(user_profile) / 'anaconda3/envs/GMS_VENV_PYTHON/python.exe'))
    rejected = []
    validation_code = (
        "import sys,pkg_resources,numpy,zhinst,zhinst.utils;"
        "v=pkg_resources.get_distribution('zhinst').version;"
        "assert sys.version_info[:2]==(3,7),sys.version;"
        "assert v=='18.12.59443',v;"
        "assert numpy.__version__=='1.21.6',numpy.__version__;print(v)"
    )
    for candidate in candidates:
        try:
            if not candidate.is_file():
                continue
            check = subprocess.run(
                [str(candidate), "-c", validation_code],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8.0,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            if check.returncode == 0:
                return candidate
            detail = (check.stderr or check.stdout or "verification failed").strip()
            rejected.append(f"{candidate} ({short_status_error(detail, 160)})")
        except (OSError, subprocess.SubprocessError) as error:
            rejected.append(f"{candidate} ({short_status_error(error, 160)})")
            continue
    searched = "; ".join(str(path) for path in candidates)
    rejected_text = "; ".join(rejected) if rejected else "none"
    raise RuntimeError(
        "No verified Python 3.7 + zhinst 18.12.59443 environment was found. Please run "
        r"INSTALL_MFLI_LABONE_18_12.bat first, or confirm that "
        r"C:\ProgramData\miniconda3\envs\GMS_VENV_PYTHON\python.exe "
        f"exists, or set the environment variable {NONLOCAL_MFLI_LEGACY_PYTHON_ENV}."
        f"Checked: {searched}. Rejected environments: {rejected_text}"
    )
class LegacyMFLIBridge:
    def __init__(self, device_id: str, timeout_s: float = 20.0) -> None:
        self.python_path = _find_mfli_legacy_python()
        self.process = None
        self.responses: queue.Queue = queue.Queue()
        self.diagnostics: list[str] = []
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        command = [str(self.python_path), '-u', '-c', _MFLI_BRIDGE_SOURCE, str(device_id), str(NONLOCAL_MFLI_API_LEVEL), str(NONLOCAL_MFLI_DEMODULATOR)]
        try:
            self.process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
                creationflags=creationflags,
            )
            threading.Thread(target=self._read_stdout, name='MFLI-bridge-stdout', daemon=True).start()
            threading.Thread(target=self._read_stderr, name='MFLI-bridge-stderr', daemon=True).start()
            ready = self._receive(timeout_s)
            if ready.get("event") != "ready":
                raise RuntimeError(f"MFLI bridge start reply is abnormal: {ready!r}")
            self.device = str(ready.get("device", device_id)).strip().lower()
            self.version = str(ready.get("version", ""))
            self.options = str(ready.get("options", ""))
            self.has_demod_2 = bool(ready.get("has_demod_2", False))
            self.has_demod_4 = bool(ready.get("has_demod_4", False))
            self.identity = str(ready.get("identity", self.device))
        except BaseException:
            self.close(force=True)
            raise
    def _append_diagnostic(self, line: str) -> None:
        line = str(line).strip()
        if not line:
            return
        self.diagnostics.append(line)
        del self.diagnostics[:-12]
    def _read_stdout(self) -> None:
        stream = self.process.stdout if self.process is not None else None
        if stream is None:
            self.responses.put({"_eof": True})
            return
        try:
            for raw_line in stream:
                line = raw_line.rstrip("\r\n")
                if line.startswith(_MFLI_BRIDGE_PREFIX):
                    try:
                        self.responses.put(json.loads(line[len(_MFLI_BRIDGE_PREFIX):]))
                    except BaseException as error:
                        self._append_diagnostic(f"JSON parse failed: {error}: {line}")
                else:
                    self._append_diagnostic(line)
        finally:
            self.responses.put({"_eof": True})
    def _read_stderr(self) -> None:
        stream = self.process.stderr if self.process is not None else None
        if stream is None:
            return
        for line in stream:
            self._append_diagnostic(line)
    def _diagnostic_suffix(self) -> str:
        if not self.diagnostics:
            return ""
        return "; legacy environment output: " + " | ".join(self.diagnostics[-5:])
    def _receive(self, timeout_s: float, request_id: int | None = None) -> dict[str, object]:
        deadline = time.monotonic() + max(0.1, float(timeout_s))
        while True:
            try:
                reply = self.responses.get(timeout=max(0.01, deadline - time.monotonic()))
            except queue.Empty as error:
                raise RuntimeError(f'The legacy LabOne bridge did not reply within {timeout_s:g} s' + self._diagnostic_suffix()) from error
            if request_id is None or reply.get('_eof') or reply.get('id') in (None, request_id):
                break
            self._append_diagnostic(f"dropped a late reply to request {reply.get('id')}")
        if reply.get("_eof"):
            exit_code = self.process.poll() if self.process is not None else None
            raise RuntimeError(f'The legacy LabOne bridge exited unexpectedly (code={exit_code})' + self._diagnostic_suffix())
        if not reply.get("ok"):
            detail = str(reply.get("error", "unknown error")).strip()
            raise RuntimeError('Legacy LabOne bridge failed: ' + detail + self._diagnostic_suffix())
        return reply
    def request(self, command: str, timeout_s: float=10.0, **parameters) -> dict[str, object]:
        if self.process is None or self.process.poll() is not None:
            raise RuntimeError('Legacy LabOne bridge is not running' + self._diagnostic_suffix())
        if self.process.stdin is None:
            raise RuntimeError("Legacy LabOne bridge stdin is unavailable")
        self.request_id = getattr(self, "request_id", 0) + 1
        payload = {"command": str(command), "id": self.request_id}
        payload.update(parameters)
        try:
            self.process.stdin.write(json.dumps(payload, ensure_ascii=True) + "\n")
            self.process.stdin.flush()
        except (BrokenPipeError, OSError) as error:
            raise RuntimeError('Cannot send a command to the legacy LabOne bridge' + self._diagnostic_suffix()) from error
        return self._receive(timeout_s, self.request_id)
    def close(self, force: bool = False) -> None:
        process = self.process
        if process is None:
            return
        if process.poll() is None and not force:
            try:
                self.request("close", timeout_s=5.0)
                try:
                    process.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    force = True
            except BaseException:
                force = True
        if process.poll() is None and force:
            try:
                process.terminate()
                process.wait(timeout=2.0)
            except BaseException:
                try:
                    process.kill()
                except BaseException:
                    pass
        for stream in (process.stdin, process.stdout, process.stderr):
            try:
                if stream is not None:
                    stream.close()
            except BaseException:
                pass
        self.process = None
class NonLocalACController:
    CLEAR_ON_READ_QUERIES = ("LIAS?", "*ESR?", "ERRS?")
    MFLI_RANGE_FRESH_REASONS = ("initial", "STFMR frequency start")
    SR830_LIAS_UNREADABLE = 0x0F
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.resource_manager = None
        self.source = None
        self.lockins: dict[str, object] = {}
        self.mfli_daq = None
        self.mfli_bridge: LegacyMFLIBridge | None = None
        self.mfli_device = ""
        self.mfli_props: dict[str, object] = {}
        self.mfli_config: dict[str, object] = {}
        self.nanovoltmeter = None
        self.source_identity = ""
        self.lockin_identities: dict[str, str] = {}
        self.mfli_identity = ""
        self.nanovoltmeter_identity = ""
        self.source_resource = ""
        self.lockin_resources: dict[str, str] = {}
        self.nanovoltmeter_resource = ""
        self.mfli_lease_resource = ""
        self.output_enabled = False
        self.source_output_mode = "AC"
        self.lock = threading.RLock()
        self.sensitivity_indices: dict[str, int] = {}
        self.low_range_counts: dict[str, int] = {}
        self.range_cooldowns: dict[str, int] = {}
        self.overload_floors: dict[str, int] = {}
        self.overload_floor_memory: dict[tuple[str, int], int] = {}
        self.lockin_harmonics: dict[str, int] = {}
        self.mfli_low_range_count = 0
        self.mfli_range_cooldown = 0
        self.mfli_low_floor_v = 0.0
        self.mfli_stepped_down = False
        self.mfli_low_readings_needed = LOCKIN_DOWNRANGE_READINGS
        self.mfli_initial_autorange_pending = False
        self.mfli_auto_range_enabled = True
        self.mfli_in_scan = False
        self.lias_clear_pending: dict[str, bool] = {}
    @property
    def connected(self) -> bool:
        return self.source is not None and (bool(self.lockins) or self.mfli_connected or self.nanovoltmeter is not None)
    @property
    def source_connected(self) -> bool:
        return self.source is not None
    @property
    def any_connected(self) -> bool:
        return self.source is not None or bool(self.lockins) or self.mfli_connected or (self.nanovoltmeter is not None)
    @property
    def shared_source_lockin_connected(self) -> bool:
        return self.source is not None or bool(self.lockins)
    @property
    def mfli_connected(self) -> bool:
        return self.mfli_daq is not None or self.mfli_bridge is not None
    @property
    def connected_lockin_keys(self) -> tuple[str, ...]:
        return tuple(sorted(self.lockins, key=int))
    @staticmethod
    def _configure_transport(instrument) -> None:
        instrument.timeout = 5000
        instrument.write_termination = "\n"
        instrument.read_termination = "\n"
        try:
            instrument.query_delay = 0.05
        except (AttributeError, ValueError):
            pass
    def _ensure_resource_manager(self):
        if pyvisa is None:
            raise RuntimeError("pyvisa is missing; please run: py -m pip install pyvisa pyvisa-py")
        if self.resource_manager is None:
            self.resource_manager = acquire_shared_visa_manager()
        return self.resource_manager
    def _close_manager_if_unused(self) -> None:
        if self.source is not None or self.lockins or self.nanovoltmeter is not None or (self.resource_manager is None):
            return
        manager = self.resource_manager
        self.resource_manager = None
        release_shared_visa_manager(manager)
    def connect_source(self, resource: str) -> str:
        with self.lock:
            if self.source is not None:
                return self.source_identity
            acquire_instrument_lease(resource, self, "Non-local 6221")
            source = None
            try:
                manager = self._ensure_resource_manager()
                source = manager.open_resource(resource)
                self._configure_transport(source)
                identity = source.query("*IDN?").strip()
                if "6221" not in identity.upper():
                    raise RuntimeError(f"{resource} is not a Keithley 6221: {identity}")
                try:
                    source.clear()
                except Exception:
                    pass
                source.write("OUTP OFF")
                self.source = source
                self.source_identity = identity
                self.source_resource = resource
                self.output_enabled = False
                self.logger(f"Non-local IV 6221 connected: {identity}")
                return identity
            except BaseException:
                if source is not None:
                    try:
                        source.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise
    def connect_lockin(self, key: str, resource: str) -> str:
        key = str(key)
        if key not in ("8", "9"):
            raise ValueError(f"Unsupported SR830 number: {key}")
        with self.lock:
            if key in self.lockins:
                return self.lockin_identities[key]
            acquire_instrument_lease(resource, self, f"Non-local SR830 #{key}")
            lockin = None
            try:
                manager = self._ensure_resource_manager()
                lockin = manager.open_resource(resource)
                self._configure_transport(lockin)
                lockin.write("OUTX 1")
                identity = lockin.query("*IDN?").strip()
                if "SR830" not in identity.upper():
                    raise RuntimeError(f"{resource} is not an SR830: {identity}")
                try:
                    lockin.clear()
                except Exception:
                    pass
                lockin.write("OUTX 1")
                time.sleep(0.05)
                show_sr830_x_and_y(lockin, self.logger, f"Non-local IV SR830 #{key}")
                self.lockins[key] = lockin
                self.lockin_identities[key] = identity
                self.lockin_resources[key] = resource
                self.sensitivity_indices.pop(key, None)
                self.low_range_counts.pop(key, None)
                self.range_cooldowns.pop(key, None)
                self.__dict__.setdefault("overload_floors", {}).pop(key, None)
                self.__dict__.setdefault("lockin_harmonics", {}).pop(key, None)
                self.logger(f"Non-local IV SR830 #{key} connected: {identity}")
                return identity
            except BaseException:
                if lockin is not None:
                    try:
                        lockin.close()
                    except BaseException:
                        pass
                self._close_manager_if_unused()
                release_instrument_lease(resource, self)
                raise
    def connect(self, source_resource: str, lockin_resources: dict[str, str]) -> tuple[str, dict[str, str]]:
        if not lockin_resources:
            raise ValueError("Select at least one SR830")
        source_was_connected = self.source_connected
        existing_keys = set(self.connected_lockin_keys)
        try:
            source_identity = self.connect_source(source_resource)
            for key, resource in lockin_resources.items():
                self.connect_lockin(key, resource)
            identities = {key: self.lockin_identities[key] for key in lockin_resources}
            return source_identity, identities
        except BaseException:
            for key in set(self.connected_lockin_keys) - existing_keys:
                try:
                    self.disconnect_lockin(key)
                except BaseException:
                    pass
            if not source_was_connected and self.source_connected:
                try:
                    self.disconnect_source()
                except BaseException:
                    pass
            raise
    def output_off(self) -> None:
        with self.lock:
            if self.source is None:
                return
            errors = []
            for command in ("SOUR:WAVE:ABOR", "CURR 0", "OUTP OFF"):
                try:
                    self.source.write(command)
                except BaseException as error:
                    errors.append(f"{command}: {error}")
            self.output_enabled = False
            if errors:
                raise RuntimeError("6221 failed to turn output off: " + "; ".join(errors))
    def disconnect(self) -> None:
        with self.lock:
            source, manager = self.source, self.resource_manager
            lockins = list(self.lockins.values())
            source_resource = self.source_resource
            lockin_resources = tuple(self.lockin_resources.values())
            nanovoltmeter_resource = self.nanovoltmeter_resource
            mfli_lease_resource = self.mfli_lease_resource
            mfli_daq = self.mfli_daq
            mfli_bridge = self.mfli_bridge
            nanovoltmeter = self.nanovoltmeter
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            for instrument in lockins + [nanovoltmeter, source]:
                if instrument is not None:
                    try:
                        instrument.write("*CLS")
                        instrument.close()
                    except BaseException:
                        pass
            if mfli_daq is not None:
                try:
                    mfli_daq.setInt(f"/{self.mfli_device}/extrefs/{self.mfli_config.get('extref_channel', NONLOCAL_MFLI_EXTREF_CHANNEL)}/enable", 0)
                    mfli_daq.setInt(f'/{self.mfli_device}/demods/{NONLOCAL_MFLI_DEMODULATOR}/enable', 0)
                    extref_demod = int(self.mfli_config.get('extref_demodulator', NONLOCAL_MFLI_EXTREF_DEMODULATOR))
                    if extref_demod != NONLOCAL_MFLI_DEMODULATOR:
                        mfli_daq.setInt(f'/{self.mfli_device}/demods/{extref_demod}/enable', 0)
                    mfli_daq.sync()
                except BaseException:
                    pass
                try:
                    mfli_daq.disconnect()
                except BaseException:
                    pass
            if mfli_bridge is not None:
                try:
                    mfli_bridge.close()
                except BaseException:
                    mfli_bridge.close(force=True)
            release_shared_visa_manager(manager)
            self.source = self.nanovoltmeter = self.resource_manager = None
            self.mfli_daq = None
            self.mfli_bridge = None
            self.mfli_device = ""
            self.mfli_props = {}
            self.mfli_config = {}
            self.mfli_identity = ""
            self.lockins = {}
            self.source_identity = ""
            self.lockin_identities = {}
            self.source_resource = ""
            self.lockin_resources = {}
            self.nanovoltmeter_resource = ""
            self.mfli_lease_resource = ""
            self.nanovoltmeter_identity = ""
            self.sensitivity_indices = {}
            self.low_range_counts = {}
            self.range_cooldowns = {}
            self.mfli_low_range_count = 0
            self.mfli_range_cooldown = 0
            self.mfli_initial_autorange_pending = False
            self.output_enabled = False
            self.source_output_mode = "AC"
            release_instrument_lease(source_resource, self)
            for resource in lockin_resources:
                release_instrument_lease(resource, self)
            release_instrument_lease(nanovoltmeter_resource, self)
            release_instrument_lease(mfli_lease_resource, self)
            self.logger("Non-local IV stopped the 6221 output and disconnected all instruments")
            if shutdown_error is not None:
                raise shutdown_error
    def disconnect_source(self) -> None:
        with self.lock:
            source = self.source
            resource = self.source_resource
            if source is None:
                self.source_resource = ""
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            shutdown_error = None
            try:
                self.output_off()
            except BaseException as error:
                shutdown_error = error
            try:
                source.write("*CLS")
            except BaseException:
                pass
            try:
                source.close()
            except BaseException:
                pass
            self.source = None
            self.source_identity = ""
            self.source_resource = ""
            self.source_output_mode = "AC"
            self.output_enabled = False
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger("Non-local IV 6221 output stopped and disconnected")
            if shutdown_error is not None:
                raise shutdown_error
    def disconnect_lockin(self, key: str) -> None:
        key = str(key)
        with self.lock:
            lockin = self.lockins.pop(key, None)
            resource = self.lockin_resources.pop(key, "")
            if lockin is None:
                release_instrument_lease(resource, self)
                self._close_manager_if_unused()
                return
            try:
                lockin.write("*CLS")
            except BaseException:
                pass
            try:
                lockin.close()
            except BaseException:
                pass
            self.lockin_identities.pop(key, None)
            self.sensitivity_indices.pop(key, None)
            self.low_range_counts.pop(key, None)
            self.range_cooldowns.pop(key, None)
            release_instrument_lease(resource, self)
            self._close_manager_if_unused()
            self.logger(f"Non-local IV SR830 #{key} disconnected")
class MagnetProtocolError(RuntimeError):
    pass
class MagnetAsciiSerialDevice:
    def __init__(self, port: str, label: str, logger: Callable[[str], None]) -> None:
        self.port = port
        self.label = label
        self.logger = logger
        self.handle = None
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return bool(self.handle is not None and self.handle.is_open)
    def _log(self, text: str) -> None:
        self.logger(f"{self.label}: {text}")
    def connect(self) -> None:
        if serial is None:
            raise RuntimeError("pyserial is missing; please run: py -m pip install pyserial")
        with self.lock:
            self.close()
            self.handle = serial.Serial(
                port=self.port,
                baudrate=MAGNET_BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=MAGNET_READ_TIMEOUT_S,
                write_timeout=MAGNET_WRITE_TIMEOUT_S,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
            )
            self.handle.reset_input_buffer()
            self.handle.reset_output_buffer()
            self._log(f"Opened {self.port} (115200 / 8N1)")
    def close(self) -> None:
        with self.lock:
            handle = self.handle
            self.handle = None
            if handle is not None:
                try:
                    if handle.is_open:
                        handle.close()
                finally:
                    self._log(f"Closed {self.port}")
    def _require_open(self):
        if not self.connected:
            raise RuntimeError(f"{self.label} is not connected")
        return self.handle
    @staticmethod
    def _decode(raw: bytes) -> str:
        return raw.decode("ascii", errors="replace").strip("\x00\r\n ")
    def exchange(self, command: str, matcher: Callable[[str], object | None] | None=None, deadline_s: float=MAGNET_REPLY_DEADLINE_S, attempts: int=1):
        wire = command.rstrip("\r\n").encode("ascii") + b"\r"
        with self.lock:
            handle = self._require_open()
            all_received: list[str] = []
            attempts = max(1, int(attempts))
            for attempt in range(1, attempts + 1):
                if attempt > 1:
                    self._log(f"Attempt {attempt}/{attempts} of {command!r}")
                    time.sleep(MAGNET_RETRY_DELAY_S)
                if attempt == 1:
                    handle.reset_input_buffer()
                handle.write(wire)
                handle.flush()
                self._log(f"TX {wire!r}")
                if matcher is None:
                    self._drain_quiet(handle)
                    return None
                result, received = self._read_matching_reply(handle, matcher, deadline_s)
                all_received.extend(received)
                if result is not None:
                    return result
            summary = " | ".join(all_received) if all_received else "<no response>"
            raise MagnetProtocolError(f'{self.label} did not return the expected data in {attempts} consecutive attempts; received: {summary}')
    def _read_matching_reply(self, handle, matcher: Callable[[str], object | None], deadline_s: float) -> tuple[object | None, list[str]]:
        deadline = time.monotonic() + deadline_s
        pending = bytearray()
        received: list[str] = []
        def consume(raw: bytes):
            text = self._decode(raw)
            if not text:
                return None
            received.append(text)
            self._log(f"RX {raw!r}")
            return matcher(text)
        while time.monotonic() < deadline:
            waiting = int(getattr(handle, "in_waiting", 0) or 0)
            chunk = handle.read(waiting if waiting > 0 else 1)
            if not chunk:
                continue
            pending.extend(chunk)
            while True:
                delimiter_indexes = [index for index in (pending.find(b'\r'), pending.find(b'\n')) if index >= 0]
                if not delimiter_indexes:
                    break
                index = min(delimiter_indexes)
                raw = bytes(pending[:index])
                del pending[: index + 1]
                result = consume(raw)
                if result is not None:
                    return result, received
            if pending:
                text = self._decode(bytes(pending))
                result = matcher(text) if text else None
                if result is not None:
                    received.append(text)
                    self._log(f"RX {bytes(pending)!r}")
                    return result, received
        if pending:
            consume(bytes(pending))
        return None, received
    def _drain_quiet(self, handle) -> None:
        end = time.monotonic() + MAGNET_QUIET_TIME_S
        while time.monotonic() < end:
            if handle.in_waiting <= 0:
                time.sleep(0.005)
                continue
            raw = handle.read_until(b"\n")
            if raw:
                text = self._decode(raw)
                if text:
                    self._log(f"RX {raw!r}")
                end = time.monotonic() + MAGNET_QUIET_TIME_S
class MagnetKepcoBOP(MagnetAsciiSerialDevice):
    def __init__(self, port: str, label: str, logger: Callable[[str], None]) -> None:
        super().__init__(port, label, logger)
        self.output_armed = False
    def connect(self) -> None:
        super().connect()
        self.output_armed = False
    def close(self) -> None:
        self.output_armed = False
        super().close()
    @staticmethod
    def _parse_current(line: str) -> float | None:
        cleaned = MAGNET_CHECKSUM_RE.sub("", line)
        match = MAGNET_CURRENT_RE.search(cleaned)
        return float(match.group(1)) if match else None
    def set_current(self, amperes: float) -> None:
        value = float(amperes)
        if not math.isfinite(value):
            raise ValueError("Magnet current must be a finite value")
        if abs(value) > MAGNET_CURRENT_LIMIT_A + 1e-12:
            raise ValueError(f'Current {value:g} A exceeds the software limit ±{MAGNET_CURRENT_LIMIT_A:g} A')
        if value != 0.0 and not self.output_armed:
            raise RuntimeError(f'{self.label} is not enabled; please click "Enable/Zero" first')
        self.exchange(f"T {value:.3f}")
    def query_current(self) -> float:
        return float(self.exchange('IQ', self._parse_current, attempts=MAGNET_QUERY_ATTEMPTS))
    def prepare_remote(self) -> None:
        self.output_armed = False
        self.exchange("remote")
        time.sleep(MAGNET_REMOTE_SETTLE_S)
    def initialize_at_zero(self) -> float:
        self.output_armed = False
        self.prepare_remote()
        self.set_current(0.0)
        self.exchange("en")
        self.output_armed = True
        self.set_current(0.0)
        time.sleep(MAGNET_COMMAND_SETTLE_S)
        return self.query_current()
class MagnetGaussMeter(MagnetAsciiSerialDevice):
    @staticmethod
    def _parse_field(line: str) -> float | None:
        match = MAGNET_FIELD_RE.search(line)
        return float(match.group(1)) if match else None
    def query_field(self) -> float:
        return float(self.exchange('GS', self._parse_field, attempts=MAGNET_QUERY_ATTEMPTS))
@dataclass
class MagnetChannel:
    key: str
    bop: MagnetKepcoBOP | None = None
    gauss: MagnetGaussMeter | None = None
    def close(self) -> None:
        if self.bop is not None:
            self.bop.close()
        if self.gauss is not None:
            self.gauss.close()
        self.bop = None
        self.gauss = None
class K10CR1KinesisController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.device = None
        self.configuration = None
        self.serial_no = K10CR1_DEFAULT_SERIAL
        self._connection_lock = threading.RLock()
        self._api_loaded = False
        self._DeviceManagerCLI = None
        self._DeviceConfiguration = None
        self._CageRotator = None
        self._Decimal = None
        self._Convert = None
        self._MotorDirection = None
    @property
    def connected(self) -> bool:
        return self.device is not None
    def _log(self, text: str) -> None:
        self.logger(f"Rotation stage: {text}")
    @staticmethod
    def _kinesis_directory() -> Path:
        for directory in K10CR1_KINESIS_DIRECTORIES:
            if all((directory / dll).is_file() for dll in K10CR1_REQUIRED_DLLS):
                return directory
        checked = "\n".join(str(path) for path in K10CR1_KINESIS_DIRECTORIES)
        raise RuntimeError(f'No complete Thorlabs Kinesis installation was found. Checked:\n{checked}\nPlease install a Kinesis matching the Python bitness.')
    def _load_api(self) -> None:
        if self._api_loaded:
            return
        if sys.platform != "win32":
            raise RuntimeError("Thorlabs Kinesis control can only run on Windows with Kinesis installed")
        directory = self._kinesis_directory()
        try:
            import clr
        except ImportError as error:
            raise RuntimeError('pythonnet is missing; please run on the control PC: py -m pip install pythonnet') from error
        try:
            for filename in K10CR1_REQUIRED_DLLS:
                clr.AddReference(str(directory / filename))
            from System import Convert, Decimal
            from Thorlabs.MotionControl.DeviceManagerCLI import DeviceConfiguration, DeviceManagerCLI
            from Thorlabs.MotionControl.GenericMotorCLI import MotorDirection
            from Thorlabs.MotionControl.IntegratedStepperMotorsCLI import CageRotator
        except BaseException as error:
            raise RuntimeError(f"Kinesis DLL load failed: {error}") from error
        self._Decimal = Decimal
        self._DeviceManagerCLI = DeviceManagerCLI
        self._DeviceConfiguration = DeviceConfiguration
        self._CageRotator = CageRotator
        self._api_loaded = True
        self._Convert = Convert
        self._MotorDirection = MotorDirection
        self._log(f"Loaded Kinesis: {directory}")
    @staticmethod
    def _flag(status, name: str) -> bool:
        try:
            return bool(getattr(status, name))
        except BaseException:
            return False
    @staticmethod
    def _text(value) -> str:
        try:
            return str(value)
        except BaseException:
            return ""
    def _require_device(self):
        if self.device is None:
            raise RuntimeError("K10CR1 rotation stage is not connected")
        return self.device
    def connect(self, serial_no: str) -> dict[str, object]:
        serial_no = serial_no.strip()
        if not serial_no.isdigit():
            raise ValueError("Rotation stage S/N must contain digits only")
        with self._connection_lock:
            if self.device is not None:
                if serial_no == self.serial_no:
                    return self.read_state()
                self.disconnect()
            self._load_api()
            self._DeviceManagerCLI.BuildDeviceList()
            devices = [str(item) for item in self._DeviceManagerCLI.GetDeviceList()]
            if serial_no not in devices:
                shown = ", ".join(devices) if devices else "no Kinesis devices found"
                raise RuntimeError(f"S/N {serial_no} not found; device list: {shown}")
            device = self._CageRotator.CreateCageRotator(serial_no)
            if device is None:
                raise RuntimeError(f"Kinesis cannot create a CageRotator for S/N {serial_no}")
            self.device = device
            self.serial_no = serial_no
            polling_started = False
            try:
                device.Connect(serial_no)
                if not bool(device.IsSettingsInitialized()):
                    device.WaitForSettingsInitialized(15_000)
                if not bool(device.IsSettingsInitialized()):
                    raise TimeoutError("Timed out waiting for K10CR1 settings initialization")
                device.StartPolling(250)
                polling_started = True
                time.sleep(0.5)
                device.EnableDevice()
                time.sleep(1.0)
                self.configuration = device.LoadMotorConfiguration(serial_no, self._DeviceConfiguration.DeviceSettingsUseOptionType.UseFileSettings)
                if self.configuration is None:
                    raise RuntimeError("LoadMotorConfiguration returned an empty configuration")
                settings_name = self._text(getattr(self.configuration, 'DeviceSettingsName', ''))
                description = self._text(getattr(device.GetDeviceInfo(), "Description", ""))
                identity = f"{description} {settings_name}".lower()
                if "k10cr" not in identity and "rotation" not in identity:
                    raise RuntimeError(f'The loaded device settings do not look like a K10CR1; motion refused: Description={description!r}, Settings={settings_name!r}')
                self._log(f"Connected S/N {serial_no}; {description or 'K10CR1'}; settings {settings_name or 'loaded'}")
                return self.read_state()
            except BaseException as error:
                try:
                    if polling_started:
                        device.StopPolling()
                except BaseException:
                    pass
                try:
                    device.Disconnect()
                except BaseException:
                    pass
                self.device = None
                self.configuration = None
                raise RuntimeError(
                    "K10CR1 connection or initialization failed. Please confirm USB/power are normal and close "
                    f"the official Thorlabs Kinesis GUI first. Original error: {error}"
                ) from error
    def disconnect(self) -> None:
        with self._connection_lock:
            device = self.device
            self.device = None
            self.configuration = None
            if device is None:
                return
            try:
                status = device.Status
                if self._flag(status, 'IsMoving') or self._flag(status, 'IsHoming') or self._flag(status, 'IsJogging'):
                    device.StopImmediate()
                    time.sleep(0.1)
            except BaseException:
                pass
            try:
                device.StopPolling()
            except BaseException:
                pass
            try:
                device.Disconnect()
            finally:
                self._log(f"Disconnected S/N {self.serial_no}")
    def read_state(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.RequestStatus()
            time.sleep(0.1)
        except BaseException:
            pass
        status = device.Status
        info = device.GetDeviceInfo()
        return {
            "serial": self.serial_no,
            "description": self._text(getattr(info, "Description", "K10CR1")),
            "settings": self._text(
                getattr(self.configuration, "DeviceSettingsName", "")
            ),
            "position": float(self._Convert.ToDouble(device.Position)),
            "homed": self._flag(status, "IsHomed"),
            "homing": self._flag(status, "IsHoming"),
            "moving": self._flag(status, "IsMoving"),
            "jogging": self._flag(status, "IsJogging"),
            "enabled": self._flag(status, "IsEnabled"),
            "error": self._flag(status, "IsError"),
            "forward_limit": self._flag(status, "ForwardLimit"),
            "reverse_limit": self._flag(status, "ReverseLimit"),
        }
    def _run_motion(self, name: str, operation: Callable[[], None]) -> dict[str, object]:
        device = self._require_device()
        try:
            operation()
            state = self.read_state()
            self._log(f"{name} complete; position {float(state['position']):.6f}°")
            return state
        except BaseException as error:
            try:
                device.StopImmediate()
            except BaseException:
                pass
            raise RuntimeError(f"{name} failed: {error}") from error
    def home(self, timeout_ms: int = 120_000) -> dict[str, object]:
        device = self._require_device()
        state = self.read_state()
        if bool(state["forward_limit"]) and bool(state["reverse_limit"]):
            raise RuntimeError("Both forward and reverse limits are triggered; Home refused, please check the sensors or Kinesis configuration")
        self._log("Starting Home; the rotation stage may perform a large-angle motion")
        state = self._run_motion("Home", lambda: device.Home(int(timeout_ms)))
        time.sleep(0.25)
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("IsHomed is still False after the Home command returned")
        return state
    def _move_relative_impl(self, angle_deg: float, timeout_ms: int, require_homed: bool) -> dict[str, object]:
        state = self.read_state()
        if require_homed and not bool(state["homed"]):
            raise RuntimeError("Device is not homed; relative motion is disabled. Please Home first or only use the ±1° diagnostic nudge")
        angle = float(angle_deg)
        if not math.isfinite(angle) or abs(angle) > 360.0:
            raise ValueError("Relative angle must be within -360° to +360°")
        if abs(angle) < 1e-12:
            self._log("Relative angle is 0; no motion command sent")
            return state
        direction = self._MotorDirection.Forward if angle > 0.0 else self._MotorDirection.Backward
        device = self._require_device()
        return self._run_motion(f'Relative move {angle:+g}°', lambda: device.MoveRelative(direction, self._Decimal(float(abs(angle))), int(timeout_ms)))
    def move_relative(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        return self._move_relative_impl(angle_deg, timeout_ms, require_homed=True)
    def move_absolute(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("Device is not homed; absolute motion is disabled")
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle < 0.0 or angle > 360.0:
            raise ValueError("Absolute angle must be within 0° to 360°")
        device = self._require_device()
        return self._run_motion(f'Move to {angle:g}°', lambda: device.MoveTo(self._Decimal(float(angle)), int(timeout_ms)))
    def diagnostic_nudge(self, angle_deg: float, timeout_ms: int = 30_000) -> dict[str, object]:
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle == 0.0 or abs(angle) > 1.0:
            raise ValueError("Diagnostic nudge must be non-zero and not exceed ±1°")
        return self._move_relative_impl(angle, timeout_ms, require_homed=False)
    def identify(self) -> None:
        self._require_device().IdentifyDevice()
        self._log("Device identify command sent")
    def stop(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.StopImmediate()
        except BaseException as first_error:
            try:
                device.Stop(5_000)
            except BaseException as second_error:
                raise RuntimeError(f'StopImmediate failed: {first_error}; Stop also failed: {second_error}') from second_error
        time.sleep(0.1)
        self._log("Immediate stop sent")
        return self.read_state()
class LEDProtocolError(RuntimeError):
    pass
@dataclass
class ChannelSettings:
    current: int = 0
    mode: int = 0
    p: int = 5
    g: int = 0
    d: int = 5
    f: int = 0
    def values(self) -> dict[str, int]:
        return {'i': self.current, 'm': self.mode, 'p': self.p, 'g': self.g, 'd': self.d, 'f': self.f}
class LEDSerialController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self._serial = None
        self._lock = threading.RLock()
        self._logger = logger
    @property
    def is_connected(self) -> bool:
        return self._serial is not None and self._serial.is_open
    @property
    def port(self) -> str | None:
        return None if self._serial is None else self._serial.port
    def connect(self, port: str) -> None:
        if serial is None:
            raise RuntimeError("pyserial is missing: py -m pip install pyserial")
        port = port.strip()
        if not port:
            raise ValueError("Serial port name cannot be empty")
        with self._lock:
            self.disconnect()
            connection = serial.Serial()
            connection.port = port
            connection.baudrate = BAUD_RATE
            connection.bytesize = serial.EIGHTBITS
            connection.parity = serial.PARITY_NONE
            connection.stopbits = serial.STOPBITS_ONE
            connection.timeout = READ_TIMEOUT_S
            connection.write_timeout = WRITE_TIMEOUT_S
            connection.xonxoff = False
            connection.rtscts = False
            connection.dsrdtr = False
            connection.dtr = False
            connection.rts = False
            try:
                connection.open()
                connection.reset_input_buffer()
                connection.reset_output_buffer()
            except BaseException:
                if connection.is_open:
                    connection.close()
                raise
            self._serial = connection
        self._logger(f"Connected {port}: {BAUD_RATE}, 8-N-1")
    def disconnect(self) -> None:
        with self._lock:
            connection = self._serial
            self._serial = None
            if connection is not None and connection.is_open:
                port = connection.port
                connection.close()
                self._logger(f"Disconnected {port}")
    def _connection(self):
        if not self.is_connected:
            raise RuntimeError("LED controller is not connected")
        return self._serial
    @staticmethod
    def _command(parameter: str, channel: int, value: int | str) -> str:
        command = f"{parameter}{channel}={value}"
        if COMMAND_RE.fullmatch(command) is None:
            raise ValueError(f"Illegal LED command: {command!r}")
        return command
    def _write_locked(self, command: str) -> None:
        connection = self._connection()
        payload = (command + "\r").encode("ascii")
        connection.write(payload)
        connection.flush()
        self._logger(f"TX  {command}\\r")
        time.sleep(COMMAND_DELAY_S)
    def query_parameter(self, parameter: str, channel: int) -> int:
        expected = f"{parameter}{channel}"
        with self._lock:
            connection = self._connection()
            connection.reset_input_buffer()
            self._write_locked(self._command(parameter, channel, "?"))
            response_bytes = connection.read_until(b"\n")
        if not response_bytes:
            raise TimeoutError(f"Query {expected} timed out")
        try:
            response = response_bytes.decode("ascii").strip("\r\n")
        except UnicodeDecodeError as error:
            raise LEDProtocolError(f"Received non-ASCII data: {response_bytes!r}") from error
        self._logger(f"RX  {response_bytes!r}")
        match = RESPONSE_RE.fullmatch(response)
        if match is None:
            raise LEDProtocolError(f"Unrecognized response: {response!r}")
        returned = f"{match.group(1)}{match.group(2)}"
        if returned != expected:
            raise LEDProtocolError(f"Queried {expected}, controller returned {returned}")
        return int(match.group(3))
    def query_channel(self, channel: int) -> ChannelSettings:
        values = {parameter: self.query_parameter(parameter, channel) for parameter in PARAMETERS}
        return ChannelSettings(current=values['i'], mode=values['m'], p=values['p'], g=values['g'], d=values['d'], f=values['f'])
    def query_all(self) -> dict[int, ChannelSettings]:
        return {channel: self.query_channel(channel) for channel in CHANNELS}
    def apply_channel(self, channel: int, settings: ChannelSettings) -> None:
        with self._lock:
            for parameter, value in settings.values().items():
                self._write_locked(self._command(parameter, channel, value))
    def apply_all(self, settings: dict[int, ChannelSettings]) -> None:
        with self._lock:
            for channel in CHANNELS:
                for parameter, value in settings[channel].values().items():
                    self._write_locked(self._command(parameter, channel, value))
    def all_off(self) -> None:
        with self._lock:
            for channel in CHANNELS:
                self._write_locked(self._command("i", channel, 0))
            for channel in CHANNELS:
                self._write_locked(self._command("m", channel, 0))
@dataclass
class CameraFrame:
    raw: object
    preview: object
    difference: object
    display_difference: object
    exposure_ms: float
    raw_mean: float
    raw_max: int
    contrast_auto: bool
    background_enabled: bool
    background_mode: str
    drift_dx: float
    drift_dy: float
    drift_response: float
    temporal_average_count: int
    spatial_binning: int
    mean_filter_size: int
    window_start_monotonic: float = math.nan
    exposure_start_monotonic: float = math.nan
    background_serial: int = 0
    background_raw: object = None
_BACKGROUND_SERIAL_LOCK = threading.Lock()
_BACKGROUND_SERIAL = [0]
def next_background_serial() -> int:
    with _BACKGROUND_SERIAL_LOCK:
        _BACKGROUND_SERIAL[0] += 1
        return _BACKGROUND_SERIAL[0]
CAMERA_EXPOSURE_START_MARGIN_S = 0.05
CAMERA_STOP_JOIN_S = 3.0
CAMERA_WAIT_SLICE_S = 1.0
CAMERA_RELEASE_POLL_MS = 500
class CameraVideoRecorder:
    def __init__(self, path: Path, fps: float, width: int, height: int) -> None:
        if cv2 is None or np is None:
            raise RuntimeError('Video recording requires OpenCV; install with: py -m pip install opencv-python')
        self.path = Path(path)
        self.fps = float(fps)
        self.width = max(2, int(width) // 2 * 2)
        self.height = max(2, int(height) // 2 * 2)
        self.frame_queue: queue.Queue[object] = queue.Queue(maxsize=16)
        self.stats_lock = threading.Lock()
        self.frames_written = 0
        self.frames_dropped = 0
        self.start_monotonic = time.monotonic()
        self.next_frame_monotonic = self.start_monotonic
        self.accepting = True
        self.writer = None
        self.codec = ""
        self.is_color = True
        self.error: BaseException | None = None
        self.path.parent.mkdir(parents=True, exist_ok=True)
        for codec in ("MJPG", "I420", "WMV2", "XVID"):
            candidate = cv2.VideoWriter(str(self.path), cv2.VideoWriter_fourcc(*codec), self.fps, (self.width, self.height), True)
            if candidate.isOpened():
                self.writer = candidate
                self.codec = codec
                break
            candidate.release()
        if self.writer is None:
            raise RuntimeError('Cannot create a Windows-compatible AVI recording; none of the MJPG/I420/WMV2/XVID encoders is available')
        self.thread = threading.Thread(target=self._writer_loop, name='camera-video-writer', daemon=True)
        self.thread.start()
    def reserve_frame_slot(self) -> bool:
        if not self.accepting or self.error is not None:
            return False
        now = time.monotonic()
        if now + 1e-9 < self.next_frame_monotonic:
            return False
        period = 1.0 / self.fps
        self.next_frame_monotonic += period
        if self.next_frame_monotonic <= now:
            self.next_frame_monotonic = now + period
        return True
    def enqueue(self, frame) -> None:
        if not self.accepting:
            return
        array = np.asarray(frame, dtype=np.uint8)
        if array.ndim != 2:
            raise ValueError("Recording frames must be 2-D 8-bit grayscale images")
        if array.shape != (self.height, self.width):
            array = cv2.resize(array, (self.width, self.height), interpolation=cv2.INTER_AREA)
        else:
            array = array.copy()
        try:
            self.frame_queue.put_nowait(array)
        except queue.Full:
            try:
                self.frame_queue.get_nowait()
            except queue.Empty:
                pass
            with self.stats_lock:
                self.frames_dropped += 1
            try:
                self.frame_queue.put_nowait(array)
            except queue.Full:
                with self.stats_lock:
                    self.frames_dropped += 1
    def _writer_loop(self) -> None:
        try:
            while True:
                frame = self.frame_queue.get()
                if frame is None:
                    break
                compatible_frame = np.repeat(frame[:, :, None], 3, axis=2)
                self.writer.write(compatible_frame)
                with self.stats_lock:
                    self.frames_written += 1
        except BaseException as error:
            self.error = error
        finally:
            try:
                self.writer.release()
            except BaseException:
                pass
    def stop(self) -> dict[str, object]:
        if self.accepting:
            self.accepting = False
            while True:
                try:
                    self.frame_queue.put_nowait(None)
                    break
                except queue.Full:
                    try:
                        self.frame_queue.get_nowait()
                    except queue.Empty:
                        break
                    with self.stats_lock:
                        self.frames_dropped += 1
        self.thread.join(timeout=8.0)
        if self.thread.is_alive():
            raise TimeoutError("Finalising the video file took more than 8 s; do not shut down the PC immediately")
        if self.error is not None:
            raise RuntimeError(f"Video write failed: {self.error}")
        return self.snapshot()
    def snapshot(self) -> dict[str, object]:
        with self.stats_lock:
            written = int(self.frames_written)
            dropped = int(self.frames_dropped)
        return {
            "path": self.path,
            "fps": self.fps,
            "codec": self.codec,
            "pixel_layout": "BGR-compatible grayscale",
            "width": self.width,
            "height": self.height,
            "frames": written,
            "dropped": dropped,
            "elapsed_s": max(0.0, time.monotonic() - self.start_monotonic),
        }
class CameraAcquisitionWorker:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.frames: queue.Queue[CameraFrame] = queue.Queue(maxsize=1)
        self.errors: queue.Queue[BaseException] = queue.Queue(maxsize=1)
        self.stop_event = threading.Event()
        self.settings_lock = threading.Lock()
        self.contrast_auto = False
        self.fixed_low = 0.0
        self.fixed_high = 65535.0
        self.last_low = 0.0
        self.last_high = 65535.0
        self.fixed_difference_max_abs = 1.0
        self.fixed_difference_center = 0.0
        self.last_difference_max_abs = 1.0
        self.last_difference_center = 0.0
        self.difference_contrast_valid = False
        self.difference_manual_clim: tuple[float, float] | None = None
        self.difference_temporal_average_count = DIFFERENCE_TEMPORAL_AVERAGE_FRAMES
        self.difference_spatial_binning = DIFFERENCE_SPATIAL_BINNING
        self.difference_mean_filter_size = DIFFERENCE_MEAN_FILTER_SIZE
        self.difference_average_reset_requested = True
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None
        self.requested_exposure_s = EXPOSURE_S
        self.active_exposure_s = EXPOSURE_S
        self.exposure_update_requested = False
        self.background_mode = "off"
        self.last_background_mode = "tracking"
        self.background_enabled = False
        self.background_capture_requested = False
        self.background = None
        self.background_serial = 0
        self._background_prepared: DriftBackground | None = None
        self.thread = threading.Thread(target=self._run, name='pco-camera', daemon=True)
    def start(self) -> None:
        self.thread.start()
    def stop(self) -> bool:
        self.stop_event.set()
        if self.thread.is_alive():
            self.thread.join(timeout=CAMERA_STOP_JOIN_S)
        return not self.releasing
    @property
    def releasing(self) -> bool:
        return self.thread.ident is not None and self.thread.is_alive()
    def _wait_for_new_image(self, camera) -> bool:
        supported = self.__dict__.get("_wait_timeout_supported")
        if supported is None:
            import inspect
            try:
                supported = "timeout" in inspect.signature(camera.wait_for_new_image).parameters
            except (TypeError, ValueError):
                supported = False
            self._wait_timeout_supported = supported
        if not supported:
            camera.wait_for_new_image()
            return True
        try:
            camera.wait_for_new_image(timeout=CAMERA_WAIT_SLICE_S)
        except Exception as error:
            if isinstance(error, TimeoutError) or "timeout" in type(error).__name__.lower():
                return False
            raise
        return True
    def toggle_contrast(self) -> bool:
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                self.difference_manual_clim = None
                self.contrast_auto = True
                self.difference_contrast_valid = False
                return True
            if self.contrast_auto:
                self.fixed_low = self.last_low
                self.fixed_high = self.last_high
                if self.difference_contrast_valid:
                    self.fixed_difference_max_abs = self.last_difference_max_abs
                    self.fixed_difference_center = self.last_difference_center
                self.contrast_auto = False
            else:
                self.contrast_auto = True
                self.difference_contrast_valid = False
            return self.contrast_auto
    def update_auto_contrast_bounds(self, low: float, high: float) -> None:
        with self.settings_lock:
            if self.contrast_auto:
                self.last_low = float(low)
                self.last_high = float(high)
    def resolve_difference_contrast(self, auto_center: float, auto_max_abs: float) -> tuple[float, float]:
        candidate_center = float(auto_center)
        candidate = max(float(auto_max_abs), DIFFERENCE_MIN_HALF_RANGE)
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                low, high = self.difference_manual_clim
                return (low + high) / 2.0, (high - low) / 2.0
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    self.last_difference_center = candidate_center
                    self.last_difference_max_abs = candidate
                else:
                    self.last_difference_center += DIFFERENCE_CENTER_SMOOTHING * (candidate_center - self.last_difference_center)
                    smoothing = DIFFERENCE_EXPAND_SMOOTHING if candidate > self.last_difference_max_abs else DIFFERENCE_CONTRACT_SMOOTHING
                    self.last_difference_max_abs += smoothing * (candidate - self.last_difference_max_abs)
                self.difference_contrast_valid = True
                return (self.last_difference_center, self.last_difference_max_abs)
            if not self.difference_contrast_valid:
                self.fixed_difference_max_abs = candidate
                self.fixed_difference_center = candidate_center
                self.last_difference_max_abs = candidate
                self.last_difference_center = candidate_center
                self.difference_contrast_valid = True
            return self.fixed_difference_center, self.fixed_difference_max_abs
    def set_difference_manual_clim(self, low: float, high: float) -> None:
        low = float(low)
        high = float(high)
        if not math.isfinite(low) or not math.isfinite(high):
            raise ValueError("CLim limits must be finite values")
        if high <= low:
            raise ValueError("CLim upper limit must be greater than the lower limit")
        with self.settings_lock:
            self.difference_manual_clim = (low, high)
    def clear_difference_manual_clim(self) -> None:
        with self.settings_lock:
            self.difference_manual_clim = None
            self.contrast_auto = True
            self.difference_contrast_valid = False
    def difference_contrast_state(self) -> tuple[str, tuple[float, float] | None]:
        with self.settings_lock:
            manual = self.difference_manual_clim
            if manual is not None:
                return "MANUAL", manual
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    return "AUTO", None
                center = self.last_difference_center
                half_range = self.last_difference_max_abs
                return "AUTO", (center - half_range, center + half_range)
            if not self.difference_contrast_valid:
                return "FIXED", None
            center = self.fixed_difference_center
            half_range = self.fixed_difference_max_abs
            return "FIXED", (center - half_range, center + half_range)
    def set_difference_display_average(self, temporal_count: int, spatial_binning: int, mean_filter_size: int) -> None:
        temporal_count = int(temporal_count)
        if temporal_count not in {1, 2, 4, 8}:
            raise ValueError("Difference temporal average count must be 1, 2, 4 or 8")
        spatial_binning = int(spatial_binning)
        if spatial_binning not in {1, 2, 4, 8}:
            raise ValueError("Display binning must be 1×1, 2×2, 4×4 or 8×8")
        mean_filter_size = int(mean_filter_size)
        if mean_filter_size not in {1, 2, 4}:
            raise ValueError("Mean filter must be off, 2×2 or 4×4")
        with self.settings_lock:
            changed = temporal_count != self.difference_temporal_average_count or spatial_binning != self.difference_spatial_binning or mean_filter_size != self.difference_mean_filter_size
            self.difference_temporal_average_count = temporal_count
            self.difference_spatial_binning = spatial_binning
            self.difference_mean_filter_size = mean_filter_size
            if changed:
                self.difference_average_reset_requested = True
                self.difference_contrast_valid = False
    def difference_display_average_state(self) -> tuple[int, int, int]:
        with self.settings_lock:
            return (self.difference_temporal_average_count, self.difference_spatial_binning, self.difference_mean_filter_size)
    def request_exposure_ms(self, exposure_ms: float) -> None:
        exposure_ms = float(exposure_ms)
        if not math.isfinite(exposure_ms):
            raise ValueError("Exposure time must be a finite value")
        if not 0.01 <= exposure_ms <= 10_000.0:
            raise ValueError("Exposure time must be within 0.01–10000 ms")
        with self.settings_lock:
            self.requested_exposure_s = exposure_ms / 1000.0
            self.exposure_update_requested = True
    def active_exposure_ms(self) -> float:
        with self.settings_lock:
            return self.active_exposure_s * 1000.0
    def _reset_difference_display_average(self) -> None:
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None
        self._difference_average_start = math.nan
        self._difference_average_previous_start = math.nan
    def _difference_for_display(self, difference, temporal_count: int, spatial_binning: int, mean_filter_size: int, reset: bool, exposure_start: float=math.nan):
        if reset:
            self._reset_difference_display_average()
        source = np.asarray(difference, dtype=np.float32)
        if temporal_count <= 1:
            display = source
            self.display_window_start = exposure_start
        else:
            if self._difference_average_sum is not None and self._difference_average_sum.shape != source.shape:
                self._reset_difference_display_average()
            if self._difference_average_sum is None:
                self._difference_average_sum = source.copy()
                self._difference_average_samples = 1
                self._difference_average_start = exposure_start
            else:
                self._difference_average_sum += source
                self._difference_average_samples += 1
            samples = self._difference_average_samples
            block_start = self.__dict__.get("_difference_average_start", math.nan)
            if samples >= temporal_count:
                display = self._difference_average_sum / float(temporal_count)
                self._difference_average_previous = display
                self._difference_average_previous_start = block_start
                self.display_window_start = block_start
                self._difference_average_sum = None
                self._difference_average_samples = 0
            elif self._difference_average_previous is None:
                display = self._difference_average_sum / float(samples)
                self.display_window_start = block_start
            else:
                self.display_window_start = self.__dict__.get('_difference_average_previous_start', math.nan)
                remaining = temporal_count - samples
                display = self._difference_average_previous * (remaining / float(temporal_count)) + self._difference_average_sum / float(temporal_count)
        if spatial_binning > 1:
            display = spatial_bin_average_full_size(display, spatial_binning)
        if mean_filter_size > 1:
            display = mean_filter_full_size(display, mean_filter_size)
        return display
    def toggle_background(self) -> bool:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            else:
                self.last_background_mode = self.background_mode
                self.background_mode = "off"
            self.background_enabled = self.background_mode != "off"
            if self.background_enabled and self.background is None:
                self.background_capture_requested = True
            elif not self.background_enabled:
                self.background_capture_requested = False
            return self.background_enabled
    def set_background_mode(self, mode: str) -> str:
        if mode not in {"off", "plain", "tracking"}:
            raise ValueError(f"Unknown difference mode: {mode}")
        with self.settings_lock:
            previous_mode = self.background_mode
            self.background_mode = mode
            self.background_enabled = mode != "off"
            if mode != previous_mode and mode != "off":
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            if self.background_enabled:
                self.last_background_mode = mode
                if self.background is None:
                    self.background_capture_requested = True
            else:
                self.background_capture_requested = False
            return self.background_mode
    def capture_background(self) -> None:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
            self.background_enabled = True
            self.background_capture_requested = True
            self.difference_contrast_valid = False
            self.difference_average_reset_requested = True
    @staticmethod
    def _make_preview(image_raw, low: float, high: float):
        preview = np.asarray(image_raw).astype(np.float32)
        preview -= float(low)
        preview *= 255.0 / max(high - low, 1.0)
        np.clip(preview, 0.0, 255.0, out=preview)
        return preview.astype(np.uint8)
    def _put_latest(self, frame: CameraFrame) -> None:
        try:
            self.frames.put_nowait(frame)
            return
        except queue.Full:
            pass
        try:
            self.frames.get_nowait()
        except queue.Empty:
            pass
        try:
            self.frames.put_nowait(frame)
        except queue.Full:
            pass
    def _run(self) -> None:
        camera = None
        try:
            camera = pco.Camera()
            camera.default_configuration()
            camera.exposure_time = EXPOSURE_S
            camera.configuration = {"timestamp": "off", "metadata": "off"}
            camera.record(RING_BUFFER_FRAMES, "ring buffer")
            self.logger("PCO camera live preview started")
            while not self.stop_event.is_set():
                with self.settings_lock:
                    requested_exposure = self.requested_exposure_s if self.exposure_update_requested else None
                    self.exposure_update_requested = False
                    previous_exposure = self.active_exposure_s
                if requested_exposure is not None:
                    try:
                        camera.stop()
                        camera.exposure_time = requested_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    except BaseException as error:
                        self.logger(f"Camera exposure update failed: {error}")
                        try:
                            camera.stop()
                        except BaseException:
                            pass
                        camera.exposure_time = previous_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    else:
                        self.background = None
                        self._background_prepared = None
                        self._reset_difference_display_average()
                        with self.settings_lock:
                            self.active_exposure_s = requested_exposure
                            self.difference_contrast_valid = False
                            self.difference_average_reset_requested = True
                            if self.background_mode != "off":
                                self.background_capture_requested = True
                        self.logger(f'Camera exposure updated: {requested_exposure * 1000.0:g} ms; the difference background will be recaptured')
                if not self._wait_for_new_image(camera):
                    continue
                image_raw, _metadata = camera.image(0xFFFFFFFF)
                exposure_start = time.monotonic() - self.active_exposure_s - CAMERA_EXPOSURE_START_MARGIN_S
                image_raw = orient_camera_image(image_raw)
                with self.settings_lock:
                    auto = self.contrast_auto
                    fixed_low = self.fixed_low
                    fixed_high = self.fixed_high
                    last_low = self.last_low
                    last_high = self.last_high
                    background_mode = self.background_mode
                    background_enabled = background_mode != "off"
                    temporal_average_count = self.difference_temporal_average_count
                    spatial_binning = self.difference_spatial_binning
                    mean_filter_size = self.difference_mean_filter_size
                    reset_display_average = self.difference_average_reset_requested
                    if reset_display_average:
                        self.difference_average_reset_requested = False
                    capture_background = self.background_capture_requested
                    if capture_background:
                        self.background_capture_requested = False
                if capture_background:
                    self.background = image_raw.copy()
                    self.background_serial = next_background_serial()
                    self.logger("Camera background captured")
                if background_enabled:
                    if self.background is None:
                        self.background = image_raw.copy()
                        self.background_serial = next_background_serial()
                    prepared = self._background_prepared
                    if prepared is None or prepared.raw is not self.background:
                        prepared = DriftBackground(self.background)
                        self._background_prepared = prepared
                    if background_mode == "tracking":
                        difference, dx, dy, response = subtract_background_after_drift(image_raw, prepared)
                    else:
                        difference = image_raw.astype(np.float32)
                        difference -= prepared.float32
                        dx, dy, response = 0.0, 0.0, 0.0
                    display_difference = self._difference_for_display(difference, temporal_average_count, spatial_binning, mean_filter_size, reset_display_average, exposure_start)
                    window_start = self.display_window_start
                    preview = np.zeros(image_raw.shape, dtype=np.uint8)
                else:
                    difference = None
                    display_difference = None
                    window_start = math.nan
                    if reset_display_average:
                        self._reset_difference_display_average()
                    dx, dy, response = 0.0, 0.0, 0.0
                    if auto:
                        low, high = last_low, last_high
                    else:
                        low = fixed_low
                        high = fixed_high
                    preview = self._make_preview(image_raw, low, high)
                frame = CameraFrame(
                    raw=image_raw,
                    preview=preview,
                    difference=difference,
                    display_difference=display_difference,
                    exposure_ms=self.active_exposure_s * 1000.0,
                    raw_mean=_frame_mean(image_raw),
                    raw_max=int(np.max(image_raw)),
                    contrast_auto=auto,
                    background_enabled=background_enabled,
                    background_mode=background_mode,
                    drift_dx=dx,
                    drift_dy=dy,
                    drift_response=response,
                    temporal_average_count=temporal_average_count,
                    spatial_binning=spatial_binning,
                    mean_filter_size=mean_filter_size,
                    window_start_monotonic=window_start,
                    exposure_start_monotonic=exposure_start,
                    background_serial=self.background_serial if background_enabled else 0,
                    background_raw=self.background if background_enabled else None,
                )
                self._put_latest(frame)
        except BaseException as error:
            try:
                self.errors.put_nowait(error)
            except queue.Full:
                pass
        finally:
            if camera is not None:
                try:
                    camera.stop()
                except BaseException:
                    pass
                try:
                    camera.close()
                except BaseException:
                    pass
            self.logger("PCO camera live preview stopped")
class TkCameraWindow:
    def __init__(self, root: tk.Tk, app) -> None:
        if CAMERA_IMPORT_ERROR is not None:
            raise RuntimeError('Camera dependencies are missing. Install pco, numpy and Pillow, and check the PCO driver.\n\n' + str(CAMERA_IMPORT_ERROR))
        self.root = root
        self.app = app
        self.window = tk.Toplevel(root)
        self.window.withdraw()
        self.window.title(CAMERA_WINDOW)
        self.window.geometry(geometry_string(self.app.window_layout["camera"]))
        camera_geometry = self.app.window_layout["camera"]
        self.window.minsize(min(camera_geometry[0], max(360, int(520 * self.app.ui_scale))), min(camera_geometry[1], max(280, int(400 * self.app.ui_scale))))
        self.window.protocol("WM_DELETE_WINDOW", self.hide)
        self.window_visible = False
        self.canvas = tk.Canvas(self.window, bg="black", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<MouseWheel>", self._mouse_wheel)
        self.canvas.bind("<Button-4>", lambda event: self._zoom_at(event.x, event.y, 1))
        self.canvas.bind("<Button-5>", lambda event: self._zoom_at(event.x, event.y, -1))
        self.canvas.bind("<ButtonPress-1>", self._pan_start)
        self.canvas.bind("<B1-Motion>", self._pan_move)
        self.canvas.bind("<ButtonRelease-1>", self._pan_end)
        self.window.bind("<KeyPress-a>", self._toggle_contrast)
        self.window.bind("<KeyPress-A>", self._toggle_contrast)
        self.window.bind("<KeyPress-b>", self._toggle_background)
        self.window.bind("<KeyPress-B>", self._toggle_background)
        self.window.bind("<KeyPress-n>", self._capture_background)
        self.window.bind("<KeyPress-N>", self._capture_background)
        self.window.bind("<KeyPress-c>", self._clear_roi)
        self.window.bind("<KeyPress-C>", self._clear_roi)
        self.window.bind("<KeyPress-r>", self._reset_zoom)
        self.window.bind("<KeyPress-R>", self._reset_zoom)
        self.window.bind("<KeyPress-m>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-M>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-q>", lambda _event: self.app.request_close())
        self.window.bind("<Escape>", lambda _event: self.app.request_close())
        self.window.bind("<ButtonPress>", self._take_keyboard, add="+")
        self.window.focus_set()
        self.window.after_idle(lambda: force_english_input_mode(self.window))
        self.key_feedback = None
        self.worker = CameraAcquisitionWorker(self.app.thread_log)
        self.latest_frame: CameraFrame | None = None
        self.latest_display_image = None
        self.latest_display_geometry = None
        self.latest_display = None
        self.photo = None
        self.mapping = None
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        self.panning = False
        self.pan_start_x = 0
        self.pan_start_y = 0
        self.pan_center_x = 0.0
        self.pan_center_y = 0.0
        self.selecting_roi = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.objective_100x_marker_visible = False
        self.video_recorder: CameraVideoRecorder | None = None
        self.video_status_last_update = 0.0
        self.error_shown = False
        self.connection_announced = False
        self.after_id = None
        self.render_pause_count = 0
        self.render_pause_reason = ""
        self.worker.start()
        self.after_id = self.window.after(15, self._poll)
    @property
    def rendering_paused(self) -> bool:
        return self.render_pause_count > 0
    def show(self) -> None:
        try:
            if not self.window.winfo_exists():
                raise RuntimeError("Camera Live window has been closed")
            self.window.deiconify()
            self.window.lift()
            self.window.focus_set()
            self.window_visible = True
            self.app.camera_window_visibility_changed(True)
            if self.latest_frame is not None and not self.rendering_paused:
                self._draw(self.latest_frame)
        except tk.TclError as error:
            raise RuntimeError("Cannot show the Camera Live window") from error
    def hide(self) -> None:
        self.window_visible = False
        try:
            if self.window.winfo_exists():
                self.window.withdraw()
        except tk.TclError:
            pass
        self.app.camera_window_visibility_changed(False)
    def pause_rendering(self, reason: str = "background operation") -> None:
        self.render_pause_count += 1
        self.render_pause_reason = str(reason or "background operation")
        if self.render_pause_count != 1:
            return
        try:
            width = max(self.canvas.winfo_width(), 320)
            height = max(self.canvas.winfo_height(), 240)
            self.canvas.delete("camera_pause_overlay")
            self.canvas.create_rectangle(12, height - 48, width - 12, height - 12, fill='#1e293b', outline='#f4c542', width=2, tags='camera_pause_overlay')
            self.canvas.create_text(
                width / 2,
                height - 30,
                text=f"Live display paused · {self.render_pause_reason}",
                fill="#ffe66d",
                font=(self.app.ui_font_family, 11, "bold"),
                tags="camera_pause_overlay",
            )
            self.canvas.tag_raise("camera_pause_overlay")
        except tk.TclError:
            pass
    def resume_rendering(self) -> None:
        if self.render_pause_count <= 0:
            return
        self.render_pause_count -= 1
        if self.render_pause_count > 0:
            return
        self.render_pause_reason = ""
        try:
            self.canvas.delete("camera_pause_overlay")
        except tk.TclError:
            pass
        frame = self.latest_frame
        if frame is not None:
            try:
                if self.window.winfo_exists() and self.window_visible:
                    self._draw(frame)
            except tk.TclError:
                pass
    def stop(self) -> None:
        if self.video_recorder is not None:
            try:
                self.stop_video_recording()
            except BaseException as error:
                self.app.append_log(f"Camera recording finalisation failed: {error}")
        try:
            if self.after_id is not None and self.window.winfo_exists():
                self.window.after_cancel(self.after_id)
        except tk.TclError:
            pass
        self.after_id = None
        self.worker.stop()
    def close(self) -> None:
        self.window_visible = False
        self.stop()
        try:
            if self.window.winfo_exists():
                self.window.destroy()
        except tk.TclError:
            pass
    def _poll(self) -> None:
        try:
            error = self.worker.errors.get_nowait()
        except queue.Empty:
            error = None
        if error is not None and not self.error_shown:
            self.error_shown = True
            self.app.append_log(f"Camera error: {error}")
            self.app.camera_start_failed(error)
            messagebox.showerror('Camera acquisition failed', str(error) + '\n\nThe LED control window remains usable.', parent=self.root)
            return
        newest = None
        while True:
            try:
                newest = self.worker.frames.get_nowait()
            except queue.Empty:
                break
        if newest is not None:
            self.latest_frame = newest
            focus = self.app.__dict__.get("auto_focus")
            if focus is not None:
                focus.frame_arrived(newest)
            if not self.connection_announced:
                self.connection_announced = True
                self.app.camera_connection_ready()
            if (self.window_visible or self.video_recorder is not None) and (not self.selecting_roi) and (not self.rendering_paused):
                self._draw(newest)
            elif not self.selecting_roi:
                self._ingest_roi_values(newest)
                self.app.update_difference_status(newest.background_mode, newest.drift_dx, newest.drift_dy, newest.drift_response)
                self.app.camera_exposure_status_var.set(f'{newest.exposure_ms:g} ms')
        try:
            if self.window.winfo_exists():
                self.after_id = self.window.after(15, self._poll)
        except tk.TclError:
            self.after_id = None
    def _crop_bounds(self, width: int, height: int):
        if self.center_x is None:
            self.center_x = width / 2.0
        if self.center_y is None:
            self.center_y = height / 2.0
        crop_width = max(1, int(width / self.zoom))
        crop_height = max(1, int(height / self.zoom))
        self.center_x = float(np.clip(self.center_x, crop_width / 2.0, width - crop_width / 2.0))
        self.center_y = float(np.clip(self.center_y, crop_height / 2.0, height - crop_height / 2.0))
        x1 = int(np.clip(round(self.center_x - crop_width / 2.0), 0, width - crop_width))
        y1 = int(np.clip(round(self.center_y - crop_height / 2.0), 0, height - crop_height))
        return x1, y1, x1 + crop_width, y1 + crop_height
    def _draw(self, frame: CameraFrame) -> None:
        if self.rendering_paused:
            return
        image_height, image_width = frame.raw.shape[:2]
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        x1, y1, x2, y2 = self._crop_bounds(image_width, image_height)
        visible_bounds = (x1, y1, x2, y2)
        active_difference_clim = None
        if frame.difference is not None:
            display_difference = frame.display_difference if frame.display_difference is not None else frame.difference
            auto_center, auto_max_abs = difference_contrast_parameters(display_difference, visible_bounds)
            active_center, active_max_abs = self.worker.resolve_difference_contrast(auto_center, auto_max_abs)
            preview = difference_preview(display_difference, max_abs=active_max_abs, center=active_center)
            active_difference_clim = (active_center - active_max_abs, active_center + active_max_abs)
        elif frame.contrast_auto:
            low, high = auto_contrast_limits(frame.raw, visible_bounds)
            self.worker.update_auto_contrast_bounds(low, high)
            preview = self.worker._make_preview(frame.raw, low, high)
        else:
            preview = frame.preview
        cropped = preview[y1:y2, x1:x2]
        scale = min(canvas_width / cropped.shape[1], canvas_height / cropped.shape[0])
        display_width = max(1, int(cropped.shape[1] * scale))
        display_height = max(1, int(cropped.shape[0] * scale))
        offset_x = (canvas_width - display_width) // 2
        offset_y = (canvas_height - display_height) // 2
        pil_image = Image.fromarray(cropped)
        pil_image = pil_image.resize((display_width, display_height), Image.Resampling.BILINEAR)
        display_array = np.asarray(pil_image, dtype=np.uint8)
        self.latest_display_image = display_array.copy()
        self.latest_display_geometry = (offset_x, offset_y, canvas_width, canvas_height)
        self.latest_display = (self.latest_display_image, self.latest_display_geometry, frame)
        self._record_current_8bit_view(display_array, offset_x, offset_y, canvas_width, canvas_height)
        self.photo = ImageTk.PhotoImage(pil_image)
        self.canvas.delete("all")
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.canvas.create_image(offset_x, offset_y, image=self.photo, anchor="nw")
        self.mapping = {
            "crop_x1": x1,
            "crop_y1": y1,
            "crop_width": x2 - x1,
            "crop_height": y2 - y1,
            "offset_x": offset_x,
            "offset_y": offset_y,
            "display_width": display_width,
            "display_height": display_height,
            "image_width": image_width,
            "image_height": image_height,
        }
        margin = 35
        label_font = (self.app.ui_font_family, 46, "bold")
        self.canvas.create_text(margin, margin, text=CAMERA_CORNER_LABELS['nw'], fill='yellow', font=label_font, anchor='nw')
        self.canvas.create_text(margin, canvas_height - margin, text=CAMERA_CORNER_LABELS['sw'], fill='yellow', font=label_font, anchor='sw')
        self.canvas.create_text(canvas_width - margin, canvas_height - margin, text=CAMERA_CORNER_LABELS['se'], fill='yellow', font=label_font, anchor='se')
        self.canvas.create_text(canvas_width - margin, margin, text=CAMERA_CORNER_LABELS['ne'], fill='yellow', font=label_font, anchor='ne')
        if frame.difference is not None:
            contrast_mode, active_clim = self.worker.difference_contrast_state()
            if active_clim is None:
                contrast = contrast_mode
            else:
                contrast = f'{contrast_mode} CLim [{active_clim[0]:.4g}, {active_clim[1]:.4g}]'
        else:
            contrast = "AUTO" if frame.contrast_auto else "FIXED"
        temporal_average = frame.temporal_average_count
        spatial_binning = frame.spatial_binning
        mean_filter_size = frame.mean_filter_size
        average_text = f"Avg {temporal_average}"
        if spatial_binning > 1:
            average_text += f" + Bin {spatial_binning}x{spatial_binning}"
        if mean_filter_size > 1:
            average_text += f" + Mean {mean_filter_size}x{mean_filter_size}"
        exposure_text = f"Exp {frame.exposure_ms:g} ms"
        focus = self.app.__dict__.get("auto_focus")
        if frame.background_mode == "tracking" and focus is not None and focus.super_on:
            camera_status = (
                f"Super ON   dx {frame.drift_dx:+.2f}   dy {frame.drift_dy:+.2f}   "
                f"match {frame.drift_response:.2f}   {focus.super_overlay_text()}   {exposure_text}   "
                f"{average_text}   Contrast {contrast}"
            )
            status_color = "#ff9df0"
        elif frame.background_mode == "tracking":
            camera_status = f'Tracking subtraction ON   dx {frame.drift_dx:+.2f}   dy {frame.drift_dy:+.2f}   match {frame.drift_response:.2f}   {exposure_text}   {average_text}   Contrast {contrast}'
            status_color = "#6dff6d"
        elif frame.background_mode == "plain":
            camera_status = f'Plain subtraction ON   Zoom {self.zoom:.2f}x   {exposure_text}   {average_text}   Contrast {contrast}'
            status_color = "#ffe66d"
        else:
            camera_status = f'Zoom {self.zoom:.2f}x   {exposure_text}   Contrast {contrast}   BG OFF'
            status_color = "#6de7ff"
        self.canvas.create_text(canvas_width / 2, 17, text=camera_status, fill=status_color, font=(self.app.ui_font_family, self.app.ui_font_size + 2, 'bold'), anchor='n')
        self.canvas.create_text(
            canvas_width / 2,
            42,
            text=(
                f"Raw mean {frame.raw_mean:.1f}   max {frame.raw_max}   "
                "[A] contrast  [B] BG  [N] new BG  [C] clear ROI  "
                "[R] reset  [M] marker  [Q] quit"
            ),
            fill="yellow",
            font=(self.app.ui_font_family, self.app.ui_font_size),
            anchor="n",
        )
        if self.video_recorder is not None:
            self.canvas.create_text(12, 10, text='● REC', fill='#ff2d2d', font=(self.app.ui_font_family, self.app.ui_font_size + 2, 'bold'), anchor='nw')
        self._draw_roi(frame)
        self._draw_100x_marker()
        self._draw_measurement_marker()
        self._draw_key_feedback()
        self.app.update_difference_status(frame.background_mode, frame.drift_dx, frame.drift_dy, frame.drift_response)
        self.app.camera_exposure_status_var.set(f"{frame.exposure_ms:g} ms")
        if frame.difference is not None and active_difference_clim is not None:
            self.app.update_difference_histogram(display_difference, visible_bounds, active_difference_clim)
    def _canvas_to_image(self, x: int, y: int):
        if not self._on_image(x, y):
            return None
        mapping = self.mapping
        image_x = mapping['crop_x1'] + (x - mapping['offset_x']) / mapping['display_width'] * mapping['crop_width']
        image_y = mapping['crop_y1'] + (y - mapping['offset_y']) / mapping['display_height'] * mapping['crop_height']
        return image_x, image_y
    def start_video_recording(self, path: Path, fps: float) -> dict[str, object]:
        if self.video_recorder is not None:
            raise RuntimeError("Camera Live recording is already in progress")
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        recorder = CameraVideoRecorder(path, fps, canvas_width, canvas_height)
        self.video_recorder = recorder
        self.video_status_last_update = 0.0
        return recorder.snapshot()
    def stop_video_recording(self) -> dict[str, object] | None:
        recorder = self.detach_video_recorder()
        if recorder is None:
            return None
        return recorder.stop()
    def detach_video_recorder(self) -> CameraVideoRecorder | None:
        recorder = self.video_recorder
        self.video_recorder = None
        return recorder
    def _record_current_8bit_view(self, display_image, offset_x: int, offset_y: int, canvas_width: int, canvas_height: int) -> None:
        recorder = self.video_recorder
        if recorder is None or not recorder.reserve_frame_slot():
            return
        frame = np.zeros((canvas_height, canvas_width), dtype=np.uint8)
        image = np.asarray(display_image, dtype=np.uint8)
        paste_height = min(image.shape[0], canvas_height - offset_y)
        paste_width = min(image.shape[1], canvas_width - offset_x)
        if paste_height > 0 and paste_width > 0:
            frame[offset_y:offset_y + paste_height, offset_x:offset_x + paste_width] = image[:paste_height, :paste_width]
        measurement_marker = self.app.current_camera_marker_text()
        if measurement_marker:
            font_scale = max(0.45, min(canvas_width, canvas_height) / 1400.0)
            thickness = max(1, int(round(font_scale * 2.0)))
            (text_width, text_height), baseline = cv2.getTextSize(measurement_marker, cv2.FONT_HERSHEY_SIMPLEX, font_scale, thickness)
            text_x = max(6, (canvas_width - text_width) // 2)
            text_y = canvas_height - 14
            cv2.rectangle(frame, (text_x - 5, text_y - text_height - 6), (min(canvas_width - 1, text_x + text_width + 5), text_y + baseline + 4), 0, -1)
            cv2.putText(frame, measurement_marker, (text_x, text_y), cv2.FONT_HERSHEY_SIMPLEX, font_scale, 255, thickness, cv2.LINE_AA)
        recorder.enqueue(frame)
        now = time.monotonic()
        if now - self.video_status_last_update >= 0.25:
            self.video_status_last_update = now
            self.app.update_camera_video_status(recorder.snapshot())
    def set_100x_marker_visible(self, visible: bool) -> None:
        self.objective_100x_marker_visible = bool(visible)
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
    def _draw_100x_marker(self) -> None:
        self.canvas.delete("objective_100x_marker")
        mapping = self.mapping
        if not self.objective_100x_marker_visible or mapping is None:
            return
        image_x = mapping['image_width'] * OBJECTIVE_100X_MARKER_X_FRACTION
        image_y = mapping['image_height'] * OBJECTIVE_100X_MARKER_Y_FRACTION
        center_x = mapping['offset_x'] + (image_x - mapping['crop_x1']) / mapping['crop_width'] * mapping['display_width']
        center_y = mapping['offset_y'] + (image_y - mapping['crop_y1']) / mapping['crop_height'] * mapping['display_height']
        image_to_canvas_scale = min(mapping['display_width'] / mapping['crop_width'], mapping['display_height'] / mapping['crop_height'])
        radius = max(10.0, min(mapping['image_width'], mapping['image_height']) * OBJECTIVE_100X_MARKER_RADIUS_FRACTION * image_to_canvas_scale)
        self.canvas.create_oval(center_x - radius, center_y - radius, center_x + radius, center_y + radius, outline='#ff2d00', width=4, tags='objective_100x_marker')
        self.canvas.create_text(
            center_x,
            center_y - radius - 5,
            text="100× FOV",
            fill="#ff2d00",
            font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
            anchor="s",
            tags="objective_100x_marker",
        )
        self.canvas.tag_raise("objective_100x_marker")
    def _draw_measurement_marker(self) -> None:
        marker_text = self.app.current_camera_marker_text()
        if not marker_text:
            return
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        text_id = self.canvas.create_text(canvas_width / 2, canvas_height - 12, text=marker_text, fill='#ffd54f', font=(self.app.ui_font_family, 11, 'bold'), anchor='s', tags='measurement_marker')
        bounds = self.canvas.bbox(text_id)
        if bounds is not None:
            left, top, right, bottom = bounds
            background_id = self.canvas.create_rectangle(left - 5, top - 3, right + 5, bottom + 3, fill='#111111', outline='#ffd54f', width=1, tags='measurement_marker')
            self.canvas.tag_lower(background_id, text_id)
        self.canvas.tag_raise("measurement_marker")
    def _ingest_roi_values(self, frame: CameraFrame) -> str:
        fresh = frame is not self.__dict__.get("_roi_ingested_frame")
        if fresh:
            self._roi_ingested_frame = frame
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        if roi is None or self.mapping is None:
            return ""
        raw_roi_values = values_inside_rotated_roi(frame.raw, roi)
        raw_mean_value = None
        if raw_roi_values.size:
            raw_mean_value = float(np.mean(raw_roi_values))
            if not self.selecting_roi and fresh:
                self.app.ingest_led_roi_sample(raw_mean_value)
        if frame.difference is None:
            if raw_mean_value is None:
                label = "ROI outside image"
            else:
                label = f"Raw ROI mean {raw_mean_value:.3f} · BG not subtracted"
        else:
            processed_difference = frame.display_difference if frame.display_difference is not None else frame.difference
            roi_values = values_inside_rotated_roi(processed_difference, roi)
            if roi_values.size:
                mean_value = float(np.mean(roi_values))
                label = f"Processed ROI mean {mean_value:.3f}"
                if not self.selecting_roi and fresh:
                    self.app.ingest_moke_roi_sample(mean_value, getattr(frame, 'window_start_monotonic', math.nan))
                    self.app.ingest_2410_roi_sample(mean_value, getattr(frame, 'window_start_monotonic', math.nan))
            else:
                label = "ROI outside image"
        return label
    def _draw_roi(self, frame: CameraFrame) -> None:
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        if roi is None or self.mapping is None:
            return
        label = self._ingest_roi_values(frame)
        self._update_roi_overlay(roi, label)
    def _update_roi_overlay(self, roi, label: str) -> None:
        mapping = self.mapping
        if roi is None or mapping is None:
            return
        def to_canvas(image_x, image_y):
            return (
                mapping["offset_x"]
                + (image_x - mapping["crop_x1"])
                / mapping["crop_width"]
                * mapping["display_width"],
                mapping["offset_y"]
                + (image_y - mapping["crop_y1"])
                / mapping["crop_height"]
                * mapping["display_height"],
            )
        canvas_points = [to_canvas(x, y) for x, y in rotated_roi_points(roi)]
        flattened = [coordinate for point in canvas_points for coordinate in point]
        if self.roi_overlay_id is None:
            self.roi_overlay_id = self.canvas.create_polygon(*flattened, outline='#6dff6d', fill='', width=2, tags=('roi_overlay',))
        else:
            self.canvas.coords(self.roi_overlay_id, *flattened)
        label_x, label_y = canvas_points[0]
        label_coordinates = (label_x, max(66, label_y - 5))
        if self.roi_label_id is None:
            self.roi_label_id = self.canvas.create_text(
                *label_coordinates,
                text=label,
                fill="#6dff6d",
                font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
                anchor="sw",
                tags=("roi_overlay",),
            )
        else:
            self.canvas.coords(self.roi_label_id, *label_coordinates)
            self.canvas.itemconfigure(self.roi_label_id, text=label)
        self.canvas.tag_raise("roi_overlay")
    def _update_selection_overlay(self) -> None:
        if not self.selecting_roi or self.roi_start is None or self.roi_end is None:
            return
        x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
        y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
        selection = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        self._update_roi_overlay(selection, f"Selecting ROI · W {selection['w']:.1f} px · H {selection['h']:.1f} px")
    def edit_roi(self, action: str, steps: dict[str, float]) -> None:
        if self.roi is None:
            return
        if action == "rotate_left":
            self.roi["angle"] = (self.roi["angle"] - steps["A"]) % 180.0
        elif action == "rotate_right":
            self.roi["angle"] = (self.roi["angle"] + steps["A"]) % 180.0
        elif action == "width_minus":
            self.roi["w"] = max(2.0, self.roi["w"] - steps["W"])
        elif action == "width_plus":
            self.roi["w"] += steps["W"]
        elif action == "height_minus":
            self.roi["h"] = max(2.0, self.roi["h"] - steps["H"])
        elif action == "height_plus":
            self.roi["h"] += steps["H"]
        elif action == "move_left":
            self.roi["cx"] -= steps["X"]
        elif action == "move_right":
            self.roi["cx"] += steps["X"]
        elif action == "move_up":
            self.roi["cy"] -= steps["Y"]
        elif action == "move_down":
            self.roi["cy"] += steps["Y"]
        if self.latest_frame is not None:
            height, width = self.latest_frame.preview.shape[:2]
            self.roi["cx"] = float(np.clip(self.roi["cx"], 0, width - 1))
            self.roi["cy"] = float(np.clip(self.roi["cy"], 0, height - 1))
            self._draw(self.latest_frame)
        self.app.set_2410_roi(self.roi)
    def _on_image(self, x: int, y: int) -> bool:
        if self.mapping is None:
            return False
        m = self.mapping
        return m['offset_x'] <= x < m['offset_x'] + m['display_width'] and m['offset_y'] <= y < m['offset_y'] + m['display_height']
    def _mouse_wheel(self, event) -> None:
        self._zoom_at(event.x, event.y, 1 if event.delta > 0 else -1)
    def _zoom_at(self, x: int, y: int, direction: int) -> None:
        if not self._on_image(x, y):
            return
        m = self.mapping
        mouse_image_x = m['crop_x1'] + (x - m['offset_x']) / m['display_width'] * m['crop_width']
        mouse_image_y = m['crop_y1'] + (y - m['offset_y']) / m['display_height'] * m['crop_height']
        old_zoom = self.zoom
        self.zoom = min(self.zoom * ZOOM_FACTOR, MAX_ZOOM) if direction > 0 else max(self.zoom / ZOOM_FACTOR, MIN_ZOOM)
        if self.zoom == old_zoom:
            return
        new_width = m["image_width"] / self.zoom
        new_height = m["image_height"] / self.zoom
        relative_x = (mouse_image_x - m["crop_x1"]) / max(m["crop_width"], 1.0)
        relative_y = (mouse_image_y - m["crop_y1"]) / max(m["crop_height"], 1.0)
        self.center_x = mouse_image_x - relative_x * new_width + new_width / 2.0
        self.center_y = mouse_image_y - relative_y * new_height + new_height / 2.0
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
    def _pan_start(self, event) -> None:
        if not self._on_image(event.x, event.y):
            return
        if event.state & 0x0001:
            if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
                self.app.difference_status_var.set("The ROI cannot be reselected during a scan")
                return
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is None:
                return
            self.selecting_roi = True
            self.panning = False
            self.roi_start = image_point
            self.roi_end = image_point
            self._update_selection_overlay()
            return
        self.panning = True
        self.pan_start_x = event.x
        self.pan_start_y = event.y
        self.pan_center_x = self.center_x
        self.pan_center_y = self.center_y
    def _pan_move(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
                self._update_selection_overlay()
            return
        if not self.panning or self.mapping is None:
            return
        m = self.mapping
        self.center_x = self.pan_center_x - (event.x - self.pan_start_x) * m['crop_width'] / m['display_width']
        self.center_y = self.pan_center_y - (event.y - self.pan_start_y) * m['crop_height'] / m['display_height']
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
    def _pan_end(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
            self.selecting_roi = False
            if self.roi_start is not None and self.roi_end is not None:
                x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
                y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
                if x2 - x1 >= 2 and y2 - y1 >= 2:
                    self.roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
                    self.app.set_2410_roi(self.roi)
            if self.latest_frame is not None:
                self._draw(self.latest_frame)
            return
        self.panning = False
    def _clear_roi(self, _event=None) -> None:
        had_roi = self.roi is not None
        self.app.clear_camera_roi()
        if self.roi is not None:
            self.show_key_feedback("[C] ROI not cleared: a scan is running", "#ff8a80")
        else:
            self.show_key_feedback("[C] ROI cleared" if had_roi else "[C] no ROI to clear", "#7cff7c")
    def _take_keyboard(self, _event=None) -> None:
        try:
            focused = self.window.focus_get()
        except (tk.TclError, KeyError):
            focused = None
        try:
            if focused is None or focused.winfo_toplevel() is not self.window:
                self.window.focus_force()
        except tk.TclError:
            return
        force_english_input_mode(self.window)
    def show_key_feedback(self, text: str, colour: str, seconds: float = 2.5) -> None:
        self.key_feedback = (text, time.monotonic() + seconds, colour)
        self.app.append_log(f"Camera Live: {text}")
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
        self._draw_key_feedback()
    def _draw_key_feedback(self) -> None:
        self.canvas.delete("key_feedback")
        feedback = self.__dict__.get("key_feedback")
        if not feedback or time.monotonic() > feedback[1]:
            self.key_feedback = None
            return
        text, _until, colour = feedback
        self.canvas.create_text(
            max(1, self.canvas.winfo_width()) / 2, 68, text=text, fill=colour,
            font=(self.app.ui_font_family, self.app.ui_font_size + 2, "bold"),
            anchor="n", tags=("key_feedback",),
        )
    def clear_roi_selection(self) -> None:
        self.selecting_roi = False
        self.panning = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.canvas.delete("roi_overlay")
        self.roi_overlay_id = None
        self.roi_label_id = None
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
    def _toggle_contrast(self, _event=None) -> None:
        automatic = self.worker.toggle_contrast()
        self.app.append_log("Camera contrast: " + ("auto" if automatic else "fixed"))
    def toggle_background(self) -> bool:
        previous = self.worker.background_mode
        enabled = self.worker.toggle_background()
        mode = self.worker.background_mode
        if mode != "off" and mode != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "off", "plain": "plain difference", "tracking": "drift-tracking difference"}[mode]
        self.app.append_log("Difference mode: " + mode_label)
        return enabled
    def set_background_mode(self, mode: str) -> str:
        previous = self.worker.background_mode
        selected = self.worker.set_background_mode(mode)
        if selected != "off" and selected != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "off", "plain": "plain difference", "tracking": "drift-tracking difference"}[selected]
        self.app.append_log("Difference mode: " + mode_label)
        return selected
    def capture_background(self) -> None:
        focus = self.app.__dict__.get("auto_focus")
        if focus is not None:
            focus.note_capture_request()
        self.worker.capture_background()
        self.app.reset_difference_live_time_window(restart_clock=True)
        self.app.append_log("Recapturing the background from the next frame…")
    def _toggle_background(self, _event=None) -> None:
        if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
            self.app.difference_status_var.set("The difference mode cannot be changed during a scan")
            return
        self.toggle_background()
    def _capture_background(self, _event=None) -> None:
        if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
            self.app.difference_status_var.set("The background cannot be recaptured during a scan")
            return
        self.capture_background()
    def _reset_zoom(self, _event=None) -> None:
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
SCAN_FILE_NAME_PROMPT = "Optional file name (leave blank for a timestamped default):"
def scan_file_stem(name: str) -> str:
    """The shared file-name rule, under the application's own name."""
    return _scan_file_stem(name)
def ask_scan_file_stem(parent, title: str) -> str | None:
    name = simpledialog.askstring(title, SCAN_FILE_NAME_PROMPT, parent=parent)
    if name is None:
        return None
    try:
        return scan_file_stem(name)
    except ValueError as error:
        messagebox.showerror(title, str(error), parent=parent)
        return None
def make_scan_run_folder(parent: Path, stem: str) -> Path:
    """The shared unique-folder allocator, under the application's own name."""
    return _make_scan_run_folder(parent, stem)
def scan_log_line(name: str, details: dict) -> str:
    """The shared log line with the application's clock (tests replace it)."""
    return _scan_log_line(name, details, datetime_class=datetime_module.datetime)
SCAN_PLOT_SNAPSHOT_SETTLE_S = 0.05
class ScanRunRecorder(_CoreScanRunRecorder):
    """The package's recorder bound to this application: its file name and
    version in the log, its own helpers (so replacing app.scan_file_stem,
    make_scan_run_folder or scan_log_line still takes effect), and the list of
    open runs the folder dialog reads."""

    @property
    def PROGRAM_NAME(self):
        return Path(_PROGRAM_FILE).name

    @property
    def APPLICATION_VERSION(self):
        return APP_VERSION

    def _validated_stem(self, stem: str) -> str:
        return scan_file_stem(stem)

    def _make_run_folder(self, parent: Path, stem: str) -> Path:
        return make_scan_run_folder(parent, stem)

    def _format_log(self, name: str, details: dict) -> str:
        return scan_log_line(name, details)

    def _opened(self) -> None:
        _OPEN_SCAN_RUNS.add(self)
def begin_scan_run(parent, page_label: str, folder_title: str, initial_dir, settings: dict, *, prefix: str | None=None, make=None) -> ScanRunRecorder | None:
    where = {"initialdir": str(initial_dir)} if initial_dir else {}
    folder = filedialog.askdirectory(parent=parent, title=folder_title, **where)
    if not folder:
        return None
    typed = ask_scan_file_stem(parent, f"{page_label} file name")
    if typed is None:
        return None
    try:
        if make is not None:
            return make(Path(folder), typed)
        return ScanRunRecorder(Path(folder), prefix or page_label, typed, settings, label=page_label)
    except Exception as error:
        messagebox.showerror(f'{page_label} run folder', f'Could not create the run folder and its files; the scan was not started: {error}', parent=parent)
        return None
PAIR_FLIP_LIMIT = 8
FOCUS_RANGE_UM = 10.0
FOCUS_STEP_UM = 0.5
FOCUS_BACKLASH_STEPS = 2
FOCUS_LOCAL_HALF_STEPS = 3
FOCUS_PAST_PEAK_STEPS = 2
FOCUS_MIN_CONTRAST = 0.03
FOCUS_MIN_GAIN = 0.02
FOCUS_FRAMES_PER_POSITION = 2
FOCUS_SETTLE_S = 0.5
FOCUS_FRAME_TIMEOUT_S = 10.0
FOCUS_MOVE_TIMEOUT_S = 10.0
FOCUS_IDLE_INTERVAL_S = 30.0
FOCUS_IDLE_TICK_MS = 1000
FOCUS_STOP_WAIT_S = 15.0
FOCUS_DOWNSAMPLE_TARGET_PX = 512
FOCUS_POSITION_TOLERANCE_UM = 0.02
FOCUS_CSV_COLUMN = "focus_position_um"
FOCUS_DIALOG_TITLE = "Auto focus"
def focus_sharpness(image, roi=None) -> float:
    if np is None:
        raise RuntimeError("numpy is required for the auto focus")
    array = np.asarray(image, dtype=np.float64)
    if array.ndim == 3:
        array = array.mean(axis=2)
    if array.ndim != 2 or min(array.shape) < 3:
        raise ValueError(f"Auto focus needs a 2-D image, not shape {array.shape}")
    if roi is not None:
        min_y, max_y, min_x, max_x, mask = _rotated_roi_mask(roi, array.shape[0], array.shape[1])
        if mask is None or mask.shape[0] < 3 or mask.shape[1] < 3:
            raise ValueError("the ROI lies outside the image or is under 3 x 3 pixels")
        crop = array[min_y:max_y, min_x:max_x]
        inner = mask[1:-1, 1:-1]
        if not inner.any():
            raise ValueError("the ROI is too thin for the auto focus (under 3 pixels across)")
        mean = float(np.mean(crop[mask]))
        if not math.isfinite(mean) or mean <= 0.0:
            return 0.0
        laplacian = crop[:-2, 1:-1] + crop[2:, 1:-1] + crop[1:-1, :-2] + crop[1:-1, 2:] - 4.0 * crop[1:-1, 1:-1]
        value = float(np.var(laplacian[inner])) / (mean * mean)
        return value if math.isfinite(value) else 0.0
    factor = max(1, int(math.ceil(max(array.shape) / FOCUS_DOWNSAMPLE_TARGET_PX)))
    if factor > 1 and min(array.shape) // factor >= 3:
        height = array.shape[0] // factor * factor
        width = array.shape[1] // factor * factor
        array = array[:height, :width].reshape(height // factor, factor, width // factor, factor).mean(axis=(1, 3))
    mean = float(np.mean(array))
    if not math.isfinite(mean) or mean <= 0.0:
        return 0.0
    laplacian = array[:-2, 1:-1] + array[2:, 1:-1] + array[1:-1, :-2] + array[1:-1, 2:] - 4.0 * array[1:-1, 1:-1]
    value = float(np.var(laplacian)) / (mean * mean)
    return value if math.isfinite(value) else 0.0
class FocusError(RuntimeError):
    pass
class FocusCancelled(RuntimeError):
    pass
@dataclass
class FocusResult:
    kind: str
    reference_um: float
    start_um: float
    best_um: float
    start_score: float
    best_score: float
    peak_found: bool
    at_window_edge: bool
    moves: int
    positions: list
class FocusSearch:
    def __init__(self, reference_um, current_um, max_position_um, move, measure, cancelled,
                 *, range_um=FOCUS_RANGE_UM, step_um=FOCUS_STEP_UM, log=None,
                 min_contrast=None, min_gain=None, name="Auto focus", describe=None):
        self.reference_um = float(reference_um)
        self.min_contrast = FOCUS_MIN_CONTRAST if min_contrast is None else float(min_contrast)
        self.min_gain = FOCUS_MIN_GAIN if min_gain is None else float(min_gain)
        self.name = str(name)
        self.describe = describe or (lambda score: f"scores {score:.6g}")
        self.range_um = float(range_um)
        self.step_um = float(step_um)
        self.max_position_um = float(max_position_um)
        self.move, self.measure, self.cancelled = move, measure, cancelled
        self.log = log or (lambda text: None)
        steps = int(math.floor(self.range_um / self.step_um + 1e-9))
        self.k_min = max(-steps, int(math.ceil(-self.reference_um / self.step_um - 1e-9)))
        self.k_max = min(steps, int(math.floor((self.max_position_um - self.reference_um) / self.step_um + 1e-09)))
        offset = (float(current_um) - self.reference_um) / self.step_um
        k = int(round(offset))
        if abs(float(current_um) - self.position(k)) > FOCUS_POSITION_TOLERANCE_UM:
            raise FocusError(f'the motor at {float(current_um):g} µm is not on the {self.step_um:g} µm grid of the focus reference {self.reference_um:g} µm')
        if not self.k_min <= k <= self.k_max:
            raise FocusError(f'the motor at {float(current_um):g} µm is outside the focus window {self.position(self.k_min):g}–{self.position(self.k_max):g} µm')
        self.k = self.start_k = k
        self.moves = 0
        self.positions: list[tuple[float, float]] = []
    def position(self, k: int) -> float:
        return round(self.reference_um + k * self.step_um, 6)
    def _check_cancel(self) -> None:
        if self.cancelled():
            raise FocusCancelled("auto focus stopped")
    def _move_to(self, k: int) -> None:
        self._check_cancel()
        target = self.position(k)
        if not self.k_min <= k <= self.k_max or abs(target - self.reference_um) > self.range_um + 1e-09 or (not 0.0 <= target <= self.max_position_um):
            raise FocusError(f"focus target {target:g} µm is outside the focus window")
        self.move(target)
        self.k = k
        self.moves += 1
    def goto(self, k: int) -> None:
        if k == self.k:
            return
        if k < self.k:
            below = max(self.k_min, k - FOCUS_BACKLASH_STEPS)
            if below < k:
                self._move_to(below)
        self._move_to(k)
    def _score_here(self) -> float:
        self._check_cancel()
        score = float(self.measure())
        self.positions.append((self.position(self.k), score))
        self.log(f"{self.name}: {self.position(self.k):g} µm {self.describe(score)}")
        return score
    def _score_at(self, k: int, scores: dict) -> float:
        self.goto(k)
        scores[k] = self._score_here()
        return scores[k]
    @staticmethod
    def _contrast(scores: dict) -> float:
        best = max(scores.values())
        return (best - min(scores.values())) / best if best > 0 else 0.0
    def search(self) -> FocusResult:
        start_k = self.k
        scores: dict[int, float] = {}
        start_score = self._score_here()
        scores[start_k] = start_score
        low = max(self.k_min, start_k - FOCUS_LOCAL_HALF_STEPS)
        high = min(self.k_max, start_k + FOCUS_LOCAL_HALF_STEPS)
        for k in range(low, high + 1):
            self._score_at(k, scores)
        while True:
            best = max(scores, key=scores.get)
            top, bottom = max(scores), min(scores)
            if top - best < FOCUS_PAST_PEAK_STEPS and top < self.k_max:
                self._score_at(top + 1, scores)
                continue
            if best - bottom < FOCUS_PAST_PEAK_STEPS and bottom > self.k_min:
                block = max(self.k_min, bottom - 2 * FOCUS_PAST_PEAK_STEPS)
                for k in range(block, bottom):
                    self._score_at(k, scores)
                continue
            break
        if self._contrast(scores) < self.min_contrast:
            self.log(f"{self.name}: no clear peak near the start; sweeping the whole window")
            scores = {}
            for k in range(self.k_min, self.k_max + 1):
                self._score_at(k, scores)
        peak = self._contrast(scores) >= self.min_contrast
        best = max(scores, key=scores.get) if peak else start_k
        self.goto(best)
        final_score = self._score_here()
        return FocusResult(
            "search", self.reference_um, self.position(start_k), self.position(best),
            start_score, final_score, peak, peak and best in (self.k_min, self.k_max),
            self.moves, list(self.positions),
        )
    def check(self) -> FocusResult:
        start_k = self.k
        start_score = self._score_here()
        scores = {start_k: start_score}
        for k in (start_k + 1, start_k - 1):
            if self.k_min <= k <= self.k_max:
                self._score_at(k, scores)
        gain = 1.0 + self.min_gain
        best_k = max(scores, key=scores.get)
        at_edge = False
        if best_k != start_k and scores[best_k] > start_score * gain:
            direction = best_k - start_k
            k = best_k + direction
            while True:
                if not self.k_min <= k <= self.k_max:
                    at_edge = True
                    break
                if self._score_at(k, scores) > scores[best_k] * gain:
                    best_k = k
                    k += direction
                    continue
                break
        else:
            best_k = start_k
        self.goto(best_k)
        return FocusResult('check', self.reference_um, self.position(start_k), self.position(best_k), start_score, scores[best_k], best_k != start_k, at_edge, self.moves, list(self.positions))
SUPER_GRID_TARGET_PX = 1024
SUPER_EDGE_PERCENTILE = 92.0
SUPER_EDGE_DILATE_PX = 2
SUPER_HIGHPASS_PX = 31
SUPER_BORDER_PX = 16
SUPER_MIN_EDGE_PIXELS = 16
SUPER_EPSILON = 1e-9
SUPER_MIN_CONTRAST = 0.10
SUPER_MIN_GAIN = 0.05
SUPER_LIVE_INTERVAL_S = 1.0
SUPER_AUTO_MIN_RESIDUAL = 0.06
SUPER_AUTO_RATIO = 1.5
SUPER_AUTO_COOLDOWN_S = 10.0
SUPER_MODE_LABEL = "Super"
def _super_block_mean(array, factor: int):
    if factor <= 1:
        return array
    height = array.shape[0] // factor * factor
    width = array.shape[1] // factor * factor
    return array[:height, :width].reshape(height // factor, factor, width // factor, factor).mean(axis=(1, 3))
def _super_sobel(array):
    p = np.pad(array, 1, mode="edge")
    gx = (p[:-2, 2:] + 2.0 * p[1:-1, 2:] + p[2:, 2:]) - (p[:-2, :-2] + 2.0 * p[1:-1, :-2] + p[2:, :-2])
    gy = (p[2:, :-2] + 2.0 * p[2:, 1:-1] + p[2:, 2:]) - (p[:-2, :-2] + 2.0 * p[:-2, 1:-1] + p[:-2, 2:])
    return gx / 8.0, gy / 8.0
def _super_dilate(mask, radius: int):
    out = mask.copy()
    for axis in (0, 1):
        for _ in range(int(radius)):
            grown = out.copy()
            if axis == 0:
                grown[1:] |= out[:-1]
                grown[:-1] |= out[1:]
            else:
                grown[:, 1:] |= out[:, :-1]
                grown[:, :-1] |= out[:, 1:]
            out = grown
    return out
def _super_box_mean(array, size: int):
    half = int(size) // 2
    size = 2 * half + 1
    if half < 1 or min(array.shape) <= half:
        return np.full(array.shape, float(np.mean(array)))
    padded = np.pad(array, half, mode="reflect")
    integral = np.pad(padded, ((1, 0), (1, 0))).cumsum(axis=0).cumsum(axis=1)
    height, width = array.shape
    total = integral[size:size + height, size:size + width] - integral[:height, size:size + width] - integral[size:size + height, :width] + integral[:height, :width]
    return total / float(size * size)
class EdgeResidualReference:
    def __init__(self, background, spatial_binning: int = 1, mean_filter_size: int = 1) -> None:
        if np is None:
            raise RuntimeError("numpy is required for Super")
        array = np.asarray(background, dtype=np.float64)
        if array.ndim != 2:
            raise ValueError(f"Super needs a 2-D BG, not shape {array.shape}")
        self.shape = array.shape
        self.spatial_binning = int(spatial_binning)
        self.mean_filter_size = int(mean_filter_size)
        processed = array.astype(np.float32)
        if self.spatial_binning > 1:
            processed = spatial_bin_average_full_size(processed, self.spatial_binning)
        if self.mean_filter_size > 1:
            processed = mean_filter_full_size(processed, self.mean_filter_size)
        binning = max(1, self.spatial_binning)
        needed = max(1, int(math.ceil(max(self.shape) / SUPER_GRID_TARGET_PX)))
        self.factor = binning * int(math.ceil(needed / binning))
        grid = _super_block_mean(np.asarray(processed, dtype=np.float64), self.factor)
        if min(grid.shape) <= 2 * SUPER_BORDER_PX + 4:
            raise ValueError(f"the image ({array.shape[1]} x {array.shape[0]}) is too small for Super")
        self.grid = grid
        self.gx, self.gy = _super_sobel(grid)
        valid = np.zeros(grid.shape, dtype=bool)
        border = SUPER_BORDER_PX
        valid[border:-border, border:-border] = True
        gradient = np.hypot(self.gx, self.gy)
        threshold = float(np.percentile(gradient[valid], SUPER_EDGE_PERCENTILE))
        core = (gradient > threshold) & valid
        if not math.isfinite(threshold) or threshold <= 0.0 or int(core.sum()) < SUPER_MIN_EDGE_PIXELS:
            raise ValueError("the BG shows no edges for Super to judge (a flat or dark image)")
        self.edge = _super_dilate(core, SUPER_EDGE_DILATE_PX)
        self.edge &= valid
        self.background_highpass = grid - _super_box_mean(grid, SUPER_HIGHPASS_PX)
    def window(self, drift_px: float = 0.0):
        extra = int(math.ceil(abs(float(drift_px)) / self.factor)) if math.isfinite(drift_px) else 0
        margin = SUPER_BORDER_PX + extra
        height, width = self.grid.shape
        if 2 * margin + 4 >= min(height, width):
            raise ValueError("the drift leaves too little of the image for Super")
        return (slice(margin, height - margin), slice(margin, width - margin))
def _super_roi_grid(reference: EdgeResidualReference, roi):
    key = tuple(float(roi[name]) for name in ("cx", "cy", "w", "h", "angle"))
    cache = reference.__dict__.setdefault("_roi_cache", {})
    cached = cache.get(key)
    if cached is not None:
        return cached
    height, width = reference.shape
    min_y, max_y, min_x, max_x, mask = _rotated_roi_mask(roi, height, width)
    full = np.zeros(reference.shape, dtype=np.float64)
    if mask is not None:
        full[min_y:max_y, min_x:max_x] = mask
    inside = _super_block_mean(full, reference.factor) >= 0.5
    if len(cache) >= 4:
        cache.clear()
    cache[key] = inside
    return inside
def edge_residual(difference, reference: EdgeResidualReference, drift_px: float = 0.0, roi=None) -> float:
    d = np.asarray(difference, dtype=np.float64)
    if d.shape != reference.shape:
        raise ValueError(f"the difference ({d.shape}) and the BG ({reference.shape}) differ in size")
    d = _super_block_mean(d, reference.factor)
    rows, cols = reference.window(drift_px)
    if roi is not None:
        inside = _super_roi_grid(reference, roi)[rows, cols]
        if int(inside.sum()) < 16:
            raise ValueError("the ROI is too small or outside the image for Super")
    else:
        inside = np.ones(d[rows, cols].shape, dtype=bool)
    regressors = [np.ones(int(inside.sum())), reference.grid[rows, cols][inside], reference.gx[rows, cols][inside], reference.gy[rows, cols][inside]]
    target = d[rows, cols][inside]
    gram = np.array([[float(np.vdot(a, b)) for b in regressors] for a in regressors])
    rhs = np.array([float(np.vdot(a, target)) for a in regressors])
    coefficients = np.linalg.lstsq(gram, rhs, rcond=None)[0]
    cleaned = d - (coefficients[0] + coefficients[1] * reference.grid + coefficients[2] * reference.gx + coefficients[3] * reference.gy)
    highpass = cleaned - _super_box_mean(cleaned, SUPER_HIGHPASS_PX)
    edge = reference.edge[rows, cols] & inside
    if int(edge.sum()) < SUPER_MIN_EDGE_PIXELS:
        raise ValueError('too few BG edges inside the ROI for Super' if roi is not None else 'too few BG edges left inside the image for Super')
    residual = float(np.mean(highpass[rows, cols][edge] ** 2))
    contrast = float(np.mean(reference.background_highpass[rows, cols][edge] ** 2))
    value = math.sqrt(residual / (contrast + SUPER_EPSILON))
    if not math.isfinite(value):
        raise ValueError("the edge residual is not finite")
    return value
class SuperFocusSearch(FocusSearch):
    def __init__(self, reference_um, current_um, max_position_um, move, measure_residual, cancelled, *, log=None, **options):
        def measure() -> float:
            value = float(measure_residual())
            if not math.isfinite(value) or value < 0.0:
                raise FocusError(f"the edge residual {value!r} is not usable")
            return 1.0 / max(value, SUPER_EPSILON)
        super().__init__(
            reference_um, current_um, max_position_um, move, measure, cancelled, log=log,
            min_contrast=SUPER_MIN_CONTRAST, min_gain=SUPER_MIN_GAIN, name="Super focus",
            describe=lambda score: f"edge residual {super_residual_text(SuperFocusSearch.residual(score))}",
            **options,
        )
    @staticmethod
    def residual(score: float) -> float:
        return 1.0 / score if score > 0 else math.inf
def super_residual_text(value) -> str:
    try:
        value = float(value)
    except (TypeError, ValueError):
        return "--"
    if not math.isfinite(value):
        return "--"
    return f"{value * 100.0:.2g} %" if value < 0.1 else f"{value * 100.0:.0f} %"
class AutoFocusManager:
    def __init__(self, app, keep_var=None, status_var=None) -> None:
        self.app = app
        self.keep_var = keep_var if keep_var is not None else tk.BooleanVar(value=False)
        self.status_var = status_var if status_var is not None else tk.StringVar(value='Focus: not run (needs the motor homed, the camera live and an ROI)')
        self.roi = None
        self.super_roi = None
        self.buttons: list = []
        self.ticks: list = []
        self.camera_ready = False
        self.lock = threading.Lock()
        self.cancel_event = threading.Event()
        self.running_kind: str | None = None
        self.keep_on = False
        self.reference_um: float | None = None
        self.expected_counts: int | None = None
        self.unknown_counts: int | None = None
        self.frames_after = -math.inf
        self.last_check_monotonic = -math.inf
        self.idle_after_id = None
        self.running_metric = "sharpness"
        self.super_on = False
        self.seen_serial = 0
        self.background_focus = None
        self.capture_request_counts = None
        self.super_serial = None
        self.super_reference_um: float | None = None
        self.super_reference_reason: str | None = "no BG has been captured yet"
        self.super_live_residual: float | None = None
        self.super_live_error: str | None = None
        self.super_start_residual: float | None = None
        self.super_best_residual: float | None = None
        self._live_busy = False
        self._live_last = -math.inf
        self._edge_lock = threading.Lock()
        self._edge_cache = None
    def _motor(self):
        return self.app.__dict__.get("motor_app")
    def _cancelled(self, stop_events=()) -> bool:
        return self.cancel_event.is_set() or bool(self.app.__dict__.get('closing')) or any((event.is_set() for event in stop_events))
    def _scan_running(self) -> bool:
        return bool(self.app.__dict__.get('magnet_scan_running') or self.app.__dict__.get('keithley_scan_running') or self.app.__dict__.get('k6221_scan_running'))
    def acquisition_busy(self) -> str | None:
        app = self.app
        if app.__dict__.get("magnet_scan_collecting"):
            return "a MOKE magnet point is acquiring"
        if app.__dict__.get("keithley_collecting"):
            return "a MOKE-24 point is acquiring"
        camera = app.__dict__.get("camera_window")
        if camera is not None:
            if getattr(camera, "video_recorder", None) is not None or app.__dict__.get("camera_video_stopping"):
                return "Camera Live is recording"
            worker = getattr(camera, "worker", None)
            if worker is not None and getattr(worker, "background_capture_requested", False):
                return "a background is being captured"
        if app.__dict__.get("active_file_exports"):
            return "images are being saved"
        return None
    def position_for_row(self):
        motor = self._motor()
        if motor is None:
            return ""
        try:
            if not (motor.controller.connected and motor.homed):
                return ""
            counts = int(motor.command_counts)
            scale = float(motor.abs_counts_per_um)
        except (AttributeError, TypeError, ValueError):
            return ""
        if self.unknown_counts is not None and counts == self.unknown_counts:
            return ""
        return round(counts / scale, 4)
    def _log(self, text: str, recorder_attrs=()) -> None:
        self.app.thread_log(text)
        for attribute in recorder_attrs:
            self.app._scan_log(attribute, "note", text=str(text))
    def _call_on_tk(self, function, stop_events=(), timeout_s=FOCUS_MOVE_TIMEOUT_S):
        handoff = Future()
        def run():
            if not handoff.set_running_or_notify_cancel():
                return
            try:
                handoff.set_result(function())
            except BaseException as error:
                handoff.set_exception(error)
        self.app.post_ui(run)
        deadline = time.monotonic() + timeout_s
        while not handoff.done():
            if self._cancelled(stop_events) or time.monotonic() >= deadline:
                if handoff.cancel():
                    if self._cancelled(stop_events):
                        raise FocusCancelled("auto focus stopped")
                    raise FocusError(f'the program did not send the focus move within {timeout_s:g} s')
                break
            time.sleep(0.01)
        return handoff.result(timeout=timeout_s)
    def _move(self, target_um: float, stop_events=(), recorder_attrs=(), reference_um=None) -> None:
        motor = self._motor()
        if motor is None:
            raise FocusError("the focus motor is not attached")
        reference = self.reference_um if reference_um is None else float(reference_um)
        name = "Super focus" if self.running_metric == "super" else "Auto focus"
        whose = "the BG's focus" if self.running_metric == "super" else "the reference"
        def send():
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if self.expected_counts is not None and motor.command_counts != self.expected_counts:
                raise FocusError("the focus motor was moved by another command during the auto focus")
            return motor.submit_focus_target(target_um, f'{target_um - reference:+.1f} µm from the reference {reference:g} µm')
        try:
            future, counts, travel_s = self._call_on_tk(send, stop_events)
        except (FocusCancelled, FocusError):
            raise
        except BaseException as error:
            raise FocusError(f"the focus move to {target_um:g} µm was refused: {error}") from error
        self._log(f'{name} move: absolute {target_um:g} µm ({target_um - reference:+.1f} µm from {whose} {reference:g} µm)', recorder_attrs)
        deadline = time.monotonic() + FOCUS_MOVE_TIMEOUT_S
        while not future.done():
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if time.monotonic() >= deadline:
                self.unknown_counts = int(motor.command_counts)
                raise FocusError(f'the focus move to {target_um:g} µm was not confirmed within {FOCUS_MOVE_TIMEOUT_S:g} s')
            time.sleep(0.01)
        error = future.exception()
        if error is not None:
            self.unknown_counts = int(motor.command_counts)
            raise FocusError(f"the focus move to {target_um:g} µm failed: {error}")
        while motor.command_busy or motor.pending_target is not None or motor.command_counts != counts:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if time.monotonic() >= deadline:
                self.unknown_counts = int(motor.command_counts)
                raise FocusError(f"the focus move to {target_um:g} µm was not confirmed by the motor page")
            time.sleep(0.01)
        self.expected_counts = counts
        self.unknown_counts = None
        self.frames_after = time.monotonic() + float(travel_s) + FOCUS_SETTLE_S
    def _measure(self, stop_events=()) -> float:
        after = max(self.frames_after, time.monotonic())
        frames = []
        camera = self.app.__dict__.get("camera_window")
        latest = getattr(camera, "latest_frame", None)
        try:
            exposure_s = float(latest.exposure_ms) / 1000.0
        except (AttributeError, TypeError, ValueError):
            exposure_s = 0.0
        if not math.isfinite(exposure_s):
            exposure_s = 0.0
        deadline = time.monotonic() + FOCUS_FRAME_TIMEOUT_S + (FOCUS_FRAMES_PER_POSITION + 1) * exposure_s
        while len(frames) < FOCUS_FRAMES_PER_POSITION:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            camera = self.app.__dict__.get("camera_window")
            if camera is None:
                raise FocusError("the camera is not live")
            frame = getattr(camera, "latest_frame", None)
            try:
                start = float(getattr(frame, "exposure_start_monotonic", math.nan))
            except (TypeError, ValueError):
                start = math.nan
            if frame is not None and math.isfinite(start) and (start > after) and all((frame is not taken for taken in frames)):
                frames.append(frame)
                continue
            if time.monotonic() >= deadline:
                raise FocusError(f'no camera frame begun after the focus move came within {deadline - after:.0f} s')
            time.sleep(0.01)
        images = [np.asarray(frame.raw, dtype=np.float64) for frame in frames]
        return focus_sharpness(sum(images) / len(images), self.roi)
    def _edge_reference(self, frame) -> EdgeResidualReference:
        background = getattr(frame, "background_raw", None)
        if background is None:
            raise ValueError("the frame carries no BG")
        key = (
            int(getattr(frame, "background_serial", 0) or 0), id(background),
            int(getattr(frame, "spatial_binning", 1) or 1), int(getattr(frame, "mean_filter_size", 1) or 1),
            tuple(np.shape(background)),
        )
        with self._edge_lock:
            cached = self._edge_cache
            if cached is not None and cached[0] == key:
                return cached[1]
            reference = EdgeResidualReference(background, key[2], key[3])
            self._edge_cache = (key, reference)
            return reference
    @staticmethod
    def _frame_difference(frame):
        shown = getattr(frame, "display_difference", None)
        return shown if shown is not None else getattr(frame, "difference", None)
    @staticmethod
    def _frame_drift(frame) -> float:
        try:
            drift = max(abs(float(frame.drift_dx)), abs(float(frame.drift_dy)))
        except (AttributeError, TypeError, ValueError):
            return 0.0
        return drift if math.isfinite(drift) else 0.0
    def _measure_super(self, stop_events=(), serial=None) -> float:
        after = max(self.frames_after, time.monotonic())
        frames = []
        camera = self.app.__dict__.get("camera_window")
        latest = getattr(camera, "latest_frame", None)
        try:
            exposure_s = float(latest.exposure_ms) / 1000.0
        except (AttributeError, TypeError, ValueError):
            exposure_s = 0.0
        if not math.isfinite(exposure_s):
            exposure_s = 0.0
        try:
            average = max(1, int(getattr(latest, "temporal_average_count", 1) or 1))
        except (TypeError, ValueError):
            average = 1
        deadline = time.monotonic() + FOCUS_FRAME_TIMEOUT_S + (2 * average + FOCUS_FRAMES_PER_POSITION + 1) * exposure_s
        while len(frames) < FOCUS_FRAMES_PER_POSITION:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            camera = self.app.__dict__.get("camera_window")
            if camera is None:
                raise FocusError("the camera is not live")
            frame = getattr(camera, "latest_frame", None)
            if frame is not None:
                if getattr(frame, "background_serial", None) != serial:
                    raise FocusCancelled("the BG was recaptured")
                if getattr(frame, "background_mode", None) != "tracking" or self._frame_difference(frame) is None:
                    raise FocusCancelled("the difference display left Super")
            try:
                start = float(getattr(frame, "window_start_monotonic", math.nan))
            except (TypeError, ValueError):
                start = math.nan
            if frame is not None and math.isfinite(start) and (start > after) and all((frame is not taken for taken in frames)):
                frames.append(frame)
                continue
            if time.monotonic() >= deadline:
                raise FocusError(f'no difference frame begun after the focus move came within {deadline - after:.0f} s')
            time.sleep(0.01)
        images = [np.asarray(self._frame_difference(frame), dtype=np.float64) for frame in frames]
        try:
            value = edge_residual(sum(images) / len(images), self._edge_reference(frames[0]), max((self._frame_drift(frame) for frame in frames)), self.super_roi)
        except ValueError as error:
            raise FocusError(f"Super cannot judge the image: {error}") from error
        self.super_live_residual = value
        return value
    def _run(self, kind, reference_um, current_um, max_um, stop_events=(), recorder_attrs=()):
        def log(text):
            self.app.thread_log(text)
        result = error = None
        metric = self.running_metric
        try:
            if metric == "super":
                camera = self.app.__dict__.get("camera_window")
                roi = getattr(camera, "roi", None)
                self.super_roi = None if roi is None else dict(roi)
                serial = self.super_serial
                engine = SuperFocusSearch(
                    reference_um, current_um, max_um,
                    move=lambda target: self._move(target, stop_events, recorder_attrs, reference_um),
                    measure_residual=lambda: self._measure_super(stop_events, serial),
                    cancelled=lambda: self._cancelled(stop_events),
                    log=log,
                )
                result = engine.search() if kind == "search" else engine.check()
                return result, None
            camera = self.app.__dict__.get("camera_window")
            roi = getattr(camera, "roi", None)
            if roi is None:
                raise FocusError("draw a camera ROI first: the auto focus judges the focus inside it")
            self.roi = dict(roi)
            engine = FocusSearch(
                reference_um, current_um, max_um,
                move=lambda target: self._move(target, stop_events, recorder_attrs, reference_um),
                measure=lambda: self._measure(stop_events),
                cancelled=lambda: self._cancelled(stop_events),
                log=log,
            )
            result = engine.search() if kind == "search" else engine.check()
        except BaseException as caught:
            error = caught
        finally:
            with self.lock:
                self.running_kind = None
            self.app.post_ui(lambda: self._report(kind, result, error, recorder_attrs, metric))
        return result, error
    def _report(self, kind, result, error, recorder_attrs=(), metric="sharpness") -> None:
        if metric == "super":
            self._report_super(kind, result, error, recorder_attrs)
            return
        name = "Auto focus" if kind == "search" else "Keep in focus check"
        if result is not None:
            change = result.best_um - result.reference_um
            gain = (result.best_score / result.start_score - 1.0) * 100.0 if result.start_score > 0 else 0.0
            if kind == "search" and not result.peak_found:
                text = f"no clear peak within ±{FOCUS_RANGE_UM:g} µm; back at {result.best_um:g} µm"
            else:
                text = f"{('best' if kind == 'search' else 'checked')} at {result.best_um:g} µm ({change:+.1f} µm), sharpness {gain:+.0f} %" + (', at the window edge' if result.at_window_edge else '')
            self.status_var.set(f"Focus: {text}")
            self._log(f'{name}: {text} ({result.moves} moves; reference {result.reference_um:g} µm)', recorder_attrs)
            for attribute in recorder_attrs:
                self.app._scan_log(
                    attribute, "focus", kind=kind, position_um=result.best_um,
                    reference_um=result.reference_um, start_um=result.start_um, moves=result.moves,
                    peak_found=result.peak_found, at_window_edge=result.at_window_edge,
                )
        elif isinstance(error, FocusCancelled):
            self.status_var.set(f"Focus: {name.lower()} stopped")
            self._log(f"{name} stopped: {error}", recorder_attrs)
        else:
            self._fail(f"{name} stopped: {error}", recorder_attrs)
        self._update_controls()
    def _report_super(self, kind, result, error, recorder_attrs=()) -> None:
        name = "Super focus" if kind == "search" else "Super keep check"
        if result is not None:
            start = SuperFocusSearch.residual(result.start_score)
            best = SuperFocusSearch.residual(result.best_score)
            self.super_start_residual, self.super_live_residual = start, best
            self.super_best_residual = best
            offset = result.best_um - result.reference_um
            if kind == "search" and not result.peak_found:
                text = f"no clear edge-residual minimum within ±{FOCUS_RANGE_UM:g} µm of the BG's focus; back at {result.best_um:g} µm, edge residual {super_residual_text(best)}"
            else:
                text = (f"edge residual {super_residual_text(best)} (start {super_residual_text(start)}), "
                        f"focus {offset:+.1f} µm from the BG's focus"
                        + (", at the window edge" if result.at_window_edge else ""))
            self.status_var.set(f"Super: {text}")
            self._log(f"{name}: {text}; at {result.best_um:g} µm ({result.moves} moves; the BG's focus {result.reference_um:g} µm)", recorder_attrs)
            for attribute in recorder_attrs:
                self.app._scan_log(
                    attribute, "focus", kind=kind, metric="super", position_um=result.best_um,
                    reference_um=result.reference_um, start_um=result.start_um, moves=result.moves,
                    peak_found=result.peak_found, at_window_edge=result.at_window_edge,
                    edge_residual_start=round(start, 6), edge_residual=round(best, 6),
                )
        elif isinstance(error, FocusCancelled):
            why = str(error)
            self.status_var.set(f'Super: {name.lower()} stopped' + ('' if why in ('', 'auto focus stopped') else f' ({why})'))
            self._log(f"{name} stopped: {error}", recorder_attrs)
        else:
            self._fail(f"{name} stopped: {error}", recorder_attrs)
        self._update_controls()
    def _fail(self, text: str, recorder_attrs=()) -> None:
        self._set_keep(False)
        self.status_var.set(f"Focus: {short_status_error(text, 90)}; Keep in focus off")
        self._log(f"{text}; Keep in focus switched off", recorder_attrs)
        dialog = getattr(self.app, "_dialog_after_drain", None)
        if dialog is not None:
            dialog("showwarning", FOCUS_DIALOG_TITLE, f"{text}.\n\nKeep in focus is off.")
    def _set_keep(self, on: bool) -> None:
        self.keep_on = bool(on)
        try:
            self.keep_var.set(bool(on))
        except tk.TclError:
            pass
    def _update_controls(self) -> None:
        running = self.running_kind is not None
        idle_text = "Super focus" if self.super_on else "Auto focus"
        text = "Stop focus" if self.running_kind == "search" else idle_text
        role = button_role(text)
        for button in self.buttons:
            try:
                button.configure(text=text, style=button_role_style(role) if role else 'TButton', state='normal' if self.camera_ready or running else 'disabled')
            except tk.TclError:
                pass
        for tick in self.ticks:
            try:
                tick.configure(state="normal" if self.camera_ready else "disabled")
            except tk.TclError:
                pass
    def set_camera_ready(self, ready: bool) -> None:
        self.camera_ready = bool(ready)
        if not ready:
            self.cancel("the camera is not live", untick=True)
        self._update_controls()
    def refusal(self) -> str | None:
        if self.super_on:
            return self.super_refusal()
        motor = self._motor()
        if motor is None:
            return "the focus motor (Motor Control page) is not attached"
        reason = motor.focus_move_refusal()
        if reason:
            return reason
        camera = self.app.__dict__.get("camera_window")
        if camera is None or not self.app.__dict__.get("camera_connected"):
            return "the camera is not live"
        if getattr(camera, "latest_frame", None) is None:
            return "the camera has not produced a frame yet"
        if getattr(camera, "roi", None) is None:
            return "draw a camera ROI first: the auto focus judges the focus inside it"
        return None
    def _current(self):
        motor = self._motor()
        counts = int(motor.command_counts)
        return counts, counts / float(motor.abs_counts_per_um), float(motor.max_position_um)
    def _claim(self, kind: str) -> bool:
        with self.lock:
            if self.running_kind is not None:
                return False
            self.running_kind = kind
            self.running_metric = "super" if self.super_on else "sharpness"
            self.cancel_event.clear()
            return True
    def _confirm(self, what: str, reference_um: float, max_um: float) -> bool:
        low = max(0.0, reference_um - FOCUS_RANGE_UM)
        high = min(max_um, reference_um + FOCUS_RANGE_UM)
        if self.super_on:
            judged = f"the BG's focus {reference_um:g} µm), to make the device edges in the difference image as narrow as possible (inside the camera ROI, or the whole image when none is drawn)"
        else:
            judged = f"{reference_um:g} µm), scoring the sharpness inside the camera ROI"
        return bool(messagebox.askyesno(
            FOCUS_DIALOG_TITLE,
            f"{what} moves the focus motor in {FOCUS_STEP_UM:g} µm steps within "
            f"{low:g}–{high:g} µm (±{FOCUS_RANGE_UM:g} µm around {judged}.\n\nThe objective "
            "is close to the sample: confirm this range is safe and continue?",
            icon="warning", parent=self.app.root,
        ))
    def toggle_search(self) -> None:
        if self.running_kind == "search":
            self.cancel("Stop focus pressed")
            return
        reason = self.refusal()
        if reason is None and self.running_kind is not None:
            reason = "a Keep in focus check is running"
        if reason is None and self._scan_running():
            reason = "a scan is running (Keep in focus checks between its points)"
        if reason is None:
            reason = self.acquisition_busy()
        if reason:
            self.status_var.set(f"Focus: not started; {reason}")
            messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Auto focus was not started: {reason}.', parent=self.app.root)
            return
        counts, current_um, max_um = self._current()
        if self.super_on:
            if self.keep_on and counts != self.expected_counts:
                self._fail("The focus motor was moved by another command since Keep in focus was ticked")
                return
            reference = self.super_reference_um
            reason = self._window_refusal(reference, current_um, max_um)
            if reason:
                self.status_var.set(f"Super: not started; {reason}")
                messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Super focus was not started: {reason}.', parent=self.app.root)
                return
        elif self.reference_um is None or counts != self.expected_counts:
            if self.keep_on:
                self._fail("The focus motor was moved by another command since Keep in focus was ticked")
                return
            reference = current_um
        else:
            reference = self.reference_um
        if not self._confirm("Super focus" if self.super_on else "Auto focus", reference, max_um):
            return
        if not self._claim("search"):
            return
        self.reference_um, self.expected_counts = reference, counts
        if self.super_on:
            self.status_var.set(f"Super: searching for the narrowest edges around the BG's focus {reference:g} µm…")
        else:
            self.status_var.set(f"Focus: searching around {reference:g} µm…")
        self._update_controls()
        threading.Thread(target=self._run, args=('search', reference, current_um, max_um), name='auto-focus', daemon=True).start()
    def keep_changed(self) -> None:
        if not self.keep_var.get():
            self.keep_on = False
            if self.running_kind == "check":
                self.cancel("Keep in focus unticked")
            self.reference_um = None
            self.status_var.set("Focus: Keep in focus off")
            return
        reason = self.refusal()
        if reason is None and self.running_kind is not None:
            reason = "an auto focus search is running"
        if reason:
            self._set_keep(False)
            self.status_var.set(f"Focus: Keep in focus not started; {reason}")
            messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Keep in focus was not started: {reason}.', parent=self.app.root)
            return
        counts, current_um, max_um = self._current()
        if self.super_on:
            reference = self.super_reference_um
            reason = self._window_refusal(reference, current_um, max_um)
            if reason:
                self._set_keep(False)
                self.status_var.set(f"Super: Keep in focus not started; {reason}")
                messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Keep in focus was not started: {reason}.', parent=self.app.root)
                return
            if not self._confirm("Keep in focus (Super)", reference, max_um):
                self._set_keep(False)
                return
            self.reference_um, self.expected_counts = reference, counts
            self.keep_on = True
            self.last_check_monotonic = -math.inf
            self.status_var.set(f"Super: keeping the edges narrowest within ±{FOCUS_RANGE_UM:g} µm of the BG's focus {reference:g} µm")
            self._log(f"Keep in focus on (Super): the BG's focus {reference:g} µm, ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps, lowest edge residual")
            return
        if not self._confirm("Keep in focus", current_um, max_um):
            self._set_keep(False)
            return
        self.reference_um, self.expected_counts = current_um, counts
        self.keep_on = True
        self.last_check_monotonic = -math.inf
        self.status_var.set(f"Focus: keeping within ±{FOCUS_RANGE_UM:g} µm of {current_um:g} µm")
        self._log(f'Keep in focus on: reference {current_um:g} µm, ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps')
    def _check_ready_on_tk(self):
        if not self.keep_on or self.reference_um is None:
            return None
        motor = self._motor()
        if motor is not None and (motor.command_busy or motor.init_off_busy):
            return None
        reason = self.refusal()
        if reason:
            self._fail(f"Keep in focus stopped: {reason}")
            return None
        counts, current_um, max_um = self._current()
        if counts != self.expected_counts:
            self._fail("Keep in focus stopped: the focus motor was moved by another command")
            return None
        return self.reference_um, current_um, max_um
    def super_edges_widened(self) -> bool:
        live = self.__dict__.get("super_live_residual")
        if not self.super_on or not self.keep_on or live is None or not math.isfinite(live):
            return False
        best = self.__dict__.get("super_best_residual")
        floor = SUPER_AUTO_MIN_RESIDUAL if best is None else max(SUPER_AUTO_MIN_RESIDUAL, SUPER_AUTO_RATIO * best)
        return live > floor
    def idle_tick(self) -> None:
        root = self.app.__dict__.get("root")
        try:
            if root is not None and not self.app.__dict__.get("closing"):
                self.idle_after_id = root.after(FOCUS_IDLE_TICK_MS, self.idle_tick)
        except tk.TclError:
            self.idle_after_id = None
        since = time.monotonic() - self.last_check_monotonic
        widened = self.super_edges_widened() and since >= SUPER_AUTO_COOLDOWN_S
        if (
            not self.keep_on or self.running_kind is not None or self._scan_running()
            or self.acquisition_busy() or self.app.__dict__.get("closing")
            or (since < FOCUS_IDLE_INTERVAL_S and not widened)
        ):
            return
        ready = self._check_ready_on_tk()
        kind = "search" if widened else "check"
        if ready is None or not self._claim(kind):
            return
        self.last_check_monotonic = time.monotonic()
        if widened:
            self.status_var.set("Super: the edge lines widened; finding the focus…")
            self.app.thread_log(f'Super: edge residual {super_residual_text(self.super_live_residual)}; a Super focus search by itself (Keep in focus)')
        else:
            self.status_var.set("Focus: checking…")
        events = (_IdleStop(self),)
        threading.Thread(target=self._run, args=(kind, *ready, events), name='auto-focus-check', daemon=True).start()
    def cancel(self, reason: str, untick: bool = False) -> None:
        running = self.running_kind
        self.cancel_event.set()
        if untick and self.keep_on:
            self._set_keep(False)
            self.status_var.set(f"Focus: Keep in focus off; {reason}")
            self.app.thread_log(f"Keep in focus switched off: {reason}")
        if running is not None:
            self.app.thread_log(f"Auto focus stopped: {reason}")
    def motor_stopping(self, reason: str) -> None:
        self.cancel(reason, untick=True)
    def super_refusal(self) -> str | None:
        motor = self._motor()
        if motor is None:
            return "the focus motor (Motor Control page) is not attached"
        reason = motor.focus_move_refusal()
        if reason:
            return reason
        camera = self.app.__dict__.get("camera_window")
        if camera is None or not self.app.__dict__.get("camera_connected"):
            return "the camera is not live"
        frame = getattr(camera, "latest_frame", None)
        if frame is None:
            return "the camera has not produced a frame yet"
        if getattr(frame, "background_mode", None) != "tracking" or self._frame_difference(frame) is None:
            return "Super needs the drift-tracking difference on Camera Live"
        if self.super_reference_um is None:
            return f"the BG's focus is unknown ({self.super_reference_reason}): Recapture BG with the focus motor connected, homed and still"
        if getattr(frame, "background_serial", None) != self.super_serial:
            return "the BG is being recaptured"
        return None
    @staticmethod
    def _window_refusal(reference_um, current_um, max_um) -> str | None:
        if reference_um is None:
            return "the BG's focus is unknown: Recapture BG"
        try:
            FocusSearch(reference_um, current_um, max_um, None, None, None)
        except FocusError as error:
            return f"{error} (Super's window is ±{FOCUS_RANGE_UM:g} µm around the BG's focus {reference_um:g} µm; Recapture BG here to centre it on this position)"
        return None
    def set_super(self, on: bool, why: str = "", background_pending: bool = False) -> None:
        on = bool(on)
        if on == self.super_on:
            return
        was_keep = self.keep_on
        self.cancel(why or ("Super chosen" if on else "Super left"), untick=True)
        self.super_on = on
        self.reference_um = None
        self.super_live_residual = self.super_start_residual = None
        self.super_best_residual = None
        self.super_live_error = None
        self._live_last = -math.inf
        if on:
            self.app.thread_log('Super on: drift tracking plus the focus servo for the narrowest edges (inside the camera ROI, or the whole image when none is drawn)')
            self._take_super_reference("Super chosen", was_keep, background_pending)
        else:
            self.super_serial = self.super_reference_um = None
            self.super_reference_reason = "Super is off"
            self.status_var.set("Focus: Super off" + ("; Keep in focus off" if was_keep else ""))
            self.app.thread_log(f"Super off ({why or 'another mode chosen'})")
        self._update_controls()
    def note_capture_request(self) -> None:
        motor = self._motor()
        try:
            self.capture_request_counts = None if motor is None else int(motor.command_counts)
        except (AttributeError, TypeError, ValueError):
            self.capture_request_counts = None
        if self.super_on:
            self.cancel("Recapture BG", untick=True)
    def frame_arrived(self, frame) -> None:
        try:
            serial = int(getattr(frame, "background_serial", 0) or 0)
        except (TypeError, ValueError):
            serial = 0
        if serial and serial != self.seen_serial:
            self.seen_serial = serial
            self._background_captured(frame, serial)
        if self.super_on:
            self._schedule_live(frame)
    def _background_captured(self, frame, serial: int) -> None:
        um = counts = reason = None
        motor = self._motor()
        try:
            start = float(getattr(frame, "exposure_start_monotonic", math.nan))
        except (TypeError, ValueError):
            start = math.nan
        if motor is None:
            reason = "the focus motor was not attached"
        else:
            try:
                ready = bool(motor.controller.connected and motor.homed)
                busy = bool(motor.command_busy or motor.init_off_busy or motor.pending_target is not None)
                counts = int(motor.command_counts)
                scale = float(motor.abs_counts_per_um)
            except (AttributeError, TypeError, ValueError):
                ready, busy = False, False
            if not ready:
                reason = "the focus motor was not connected and homed"
            elif busy:
                reason = "the focus motor was busy with a command"
            elif self.running_kind is not None:
                reason = "a focus search or check was running"
            elif not math.isfinite(start):
                reason = "the BG frame's exposure time is not known"
            elif start <= self.frames_after:
                reason = "the focus motor was still settling after a focus move"
            elif self.capture_request_counts is not None and counts != self.capture_request_counts:
                reason = "the focus motor moved while the BG was being captured"
            elif self.unknown_counts is not None and counts == self.unknown_counts:
                reason = "the last focus move failed, so the position is not known"
            else:
                um = round(counts / scale, 4)
        self.capture_request_counts = None
        self.background_focus = (serial, um, counts if um is not None else None, reason)
        if self.super_on:
            self._take_super_reference("a new BG", self.keep_on)
    def _take_super_reference(self, why: str, was_keep: bool = False, pending: bool = False) -> None:
        self.cancel(why, untick=True)
        self.reference_um = None
        self.super_live_residual = self.super_start_residual = None
        self.super_best_residual = None
        self.super_live_error = None
        info = None if pending else self.background_focus
        keep_text = "; Keep in focus off (tick it again)" if was_keep else ""
        if info is not None and info[0] == self.seen_serial and info[1] is not None:
            self.super_serial, self.super_reference_um = info[0], info[1]
            self.super_reference_reason = None
            self.status_var.set(f"Super: reference {info[1]:g} µm (the BG's focus); Super focus searches ±{FOCUS_RANGE_UM:g} µm around it{keep_text}")
            self.app.thread_log(f"Super focus reference: {info[1]:g} µm, the focus motor's position when the BG was captured ({why})")
            return
        self.super_reference_um = None
        if info is None or info[0] != self.seen_serial:
            self.super_serial = None
            self.super_reference_reason = "no BG has been captured yet"
            self.status_var.set(f"Super: waiting for the BG capture{keep_text}")
            return
        self.super_serial = info[0]
        self.super_reference_reason = info[3]
        self.status_var.set(f"Super: the BG's focus is unknown ({info[3]}); Recapture BG with the motor homed and still{keep_text}")
        self.app.thread_log(f"Super: the BG's focus is unknown: {info[3]}")
    def _schedule_live(self, frame) -> None:
        if self._live_busy or self.running_kind is not None:
            return
        if time.monotonic() - self._live_last < SUPER_LIVE_INTERVAL_S:
            return
        if getattr(frame, 'background_mode', None) != 'tracking' or self._frame_difference(frame) is None or getattr(frame, 'background_raw', None) is None:
            return
        self._live_busy = True
        self._live_last = time.monotonic()
        threading.Thread(target=self._live_worker, args=(frame,), name="super-residual", daemon=True).start()
    def _live_worker(self, frame) -> None:
        value = error = None
        try:
            camera = self.app.__dict__.get("camera_window")
            roi = getattr(camera, "roi", None)
            value = edge_residual(self._frame_difference(frame), self._edge_reference(frame), self._frame_drift(frame), None if roi is None else dict(roi))
        except Exception as caught:
            error = caught
        serial = getattr(frame, "background_serial", None)
        self.app.post_ui(lambda: self._live_done(serial, value, error))
    def _live_done(self, serial, value, error) -> None:
        self._live_busy = False
        if not self.super_on or serial != self.seen_serial:
            return
        self.super_live_residual = value
        self.super_live_error = None if error is None else short_status_error(str(error), 80)
    def _focus_offset_text(self) -> str:
        if self.super_reference_um is None:
            return "BG focus unknown"
        position = self.position_for_row()
        if position == "":
            return "focus position unknown"
        return f"focus {float(position) - self.super_reference_um:+.1f} µm"
    def super_detail_text(self) -> str:
        if self.super_live_error:
            residual = f"edge residual not judged ({self.super_live_error})"
        else:
            residual = f"edge residual {super_residual_text(self.super_live_residual)}"
            if self.super_start_residual is not None:
                residual += f" (start {super_residual_text(self.super_start_residual)})"
        camera = self.app.__dict__.get("camera_window")
        area = "inside the ROI" if getattr(camera, "roi", None) is not None else "whole image (no ROI)"
        return f"Super: {residual}, {self._focus_offset_text()}; {area}"
    def super_overlay_text(self) -> str:
        text = f"Edge {super_residual_text(self.super_live_residual)}"
        if self.super_start_residual is not None:
            text += f" (start {super_residual_text(self.super_start_residual)})"
        return f"{text}   {self._focus_offset_text()}"
    def before_scan(self, recorder_attr: str | None = None) -> None:
        if recorder_attr and self.super_on:
            reference = self.super_reference_um
            if reference is not None:
                text = (f"Super focus reference: {reference:g} µm (the focus motor's position when the BG was "
                        f"captured), ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps; Keep in focus "
                        + ("on" if self.keep_on else "off"))
            else:
                text = f"Super: the BG's focus is unknown ({self.super_reference_reason}); no Super focus move"
            self._log(text, (recorder_attr,))
            self.app._scan_log(recorder_attr, 'focus', kind='super_reference', metric='super', reference_um=reference, keep_in_focus=bool(self.keep_on))
        if self.running_kind is None:
            return
        self.cancel_event.set()
        deadline = time.monotonic() + FOCUS_STOP_WAIT_S
        while self.running_kind is not None:
            if time.monotonic() >= deadline:
                raise RuntimeError(f"the auto focus did not stop within {FOCUS_STOP_WAIT_S:g} s")
            time.sleep(0.02)
    def between_points(self, recorder_attr: str, stop_event) -> None:
        if not self.keep_on or stop_event.is_set() or self.app.__dict__.get("closing"):
            return
        if self.app.__dict__.get("magnet_scan_collecting") or self.app.__dict__.get("keithley_collecting"):
            return
        kind = "search" if self.super_edges_widened() else "check"
        if not self._claim(kind):
            return
        events = (stop_event,)
        attrs = (recorder_attr,)
        try:
            ready = self._call_on_tk(self._check_ready_on_tk, events)
        except BaseException as error:
            with self.lock:
                self.running_kind = None
            if not isinstance(error, FocusCancelled):
                message = f"Keep in focus stopped: {error}"
                self.app.post_ui(lambda: self._fail(message, attrs))
            return
        if ready is None:
            with self.lock:
                self.running_kind = None
            return
        self.app.post_ui(lambda: self.status_var.set('Super: the edge lines widened; finding the focus between points…' if kind == 'search' else 'Focus: checking between points…'))
        self._run(kind, *ready, events, attrs)
        self.last_check_monotonic = time.monotonic()
class _IdleStop:
    def __init__(self, manager: AutoFocusManager) -> None:
        self.manager = manager
    def is_set(self) -> bool:
        return self.manager._scan_running() or self.manager.acquisition_busy() is not None
class CombinedControlApp:
    def __init__(self, root: tk.Tk) -> None:
        self.root = root
        self.root.title(MAIN_WINDOW_TITLE)
        apply_application_identity(self.root)
        self.window_layout = calculate_window_layout(self.root)
        self.ui_scale = float(self.window_layout["ui_scale"])
        self.canvas_scale = float(self.window_layout["canvas_scale"])
        setattr(self.root, "_moke_ui_scale", self.ui_scale)
        self.root.geometry(geometry_string(self.window_layout["control"]))
        control_geometry = self.window_layout["control"]
        self.root.minsize(min(control_geometry[0], max(620, int(760 * self.ui_scale))), min(control_geometry[1], max(500, int(650 * self.ui_scale))))
        screen_width, screen_height = self.window_layout["screen"]
        self.root.maxsize(screen_width, screen_height)
        self.root.bind_all('<FocusIn>', self._enforce_english_input_mode, add='+')
        self.root.after_idle(lambda: force_english_input_mode(self.root))
        self.ui_queue: queue.Queue[Callable[[], None]] = queue.Queue()
        self.controller = LEDSerialController(self.thread_log)
        self.executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="led-io")
        self.file_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix='file-export')
        self.active_file_exports: set[str] = set()
        self.busy = False
        self.closing = False
        self.instrument_connection_indicators: dict[str, tuple[tk.Canvas, int]] = {}
        self.port_var = tk.StringVar(value=DEFAULT_PORT)
        self.connection_var = tk.StringVar(value="Not connected")
        self.operation_var = tk.StringVar(value="Ready")
        self.auto_readback_var = tk.BooleanVar(value=True)
        self.raw_edit_var = tk.BooleanVar(value=False)
        self.global_current_var = tk.IntVar(value=0)
        self.channel_vars: dict[int, dict[str, tk.Variable]] = {}
        self.action_widgets: list[tk.Widget] = []
        self.raw_entries: list[tk.Widget] = []
        self.raw_parameter_frames: list[ttk.Frame] = []
        self.raw_edit_warning_acknowledged = False
        self.led_log_visible_var = tk.BooleanVar(value=False)
        self.stage_controller = K10CR1KinesisController(self.thread_log)
        self.stage_executor = ThreadPoolExecutor(max_workers=2, thread_name_prefix='k10cr1')
        self.stage_busy = False
        self.stage_closed = False
        self.stage_serial_var = tk.StringVar(value=K10CR1_DEFAULT_SERIAL)
        self.stage_connection_var = tk.StringVar(value="Not connected")
        self.stage_position_var = tk.StringVar(value="Position: --°")
        self.stage_state_var = tk.StringVar(value="Homed --  |  Enabled --")
        self.stage_operation_var = tk.StringVar(value="Ready")
        self.stage_safety_var = tk.BooleanVar(value=False)
        self.stage_relative_var = tk.StringVar(value="1")
        self.stage_absolute_var = tk.StringVar(value="0")
        self.stage_nudge_var = tk.StringVar(value="0.2")
        self.stage_motion_widgets: list[tk.Widget] = []
        self.motor_app_class = None
        self.motor_app = None
        self.camera_window = None
        self.camera_connected = False
        self.camera_window_visible = False
        self.notebook = None
