    def _enforce_english_input_mode(self, event=None) -> None:
        target = getattr(event, "widget", self.root)
        try:
            self.root.after_idle(lambda selected=target: force_english_input_mode(selected))
        except tk.TclError:
            pass
    def _ui_px(self, value: int | float, minimum: int=1, *, canvas: bool=False) -> int:
        scale = self.canvas_scale if canvas else self.ui_scale
        return max(int(minimum), int(round(float(value) * scale)))
    def _arrange_pair_by_width(self, container, left, right, *, gap: int=4, stack_gap: int | None=None, right_width=None, left_width=None, enabled=None):
        def arrange(_event=None) -> None:
            if enabled is not None and not enabled():
                return
            try:
                inset = self._pair_inset(container)
                available = container.winfo_width() - inset
                needed = (self._pair_natural_width(left) if left_width is None else int(left_width())) + (self._pair_natural_width(right) if right_width is None else int(right_width())) + gap
            except (tk.TclError, ValueError):
                return
            container._pair_wide_need = needed + inset
            if available <= 1:
                return
            wide = available >= needed
            if getattr(container, "_pair_side_by_side", None) is wide:
                return
            try:
                window_width = container.winfo_toplevel().winfo_width()
            except (tk.TclError, AttributeError):
                window_width = None
            now = time.monotonic()
            guard = getattr(container, "_pair_flip_guard", None)
            if guard is None or guard["window"] != window_width:
                guard = {"window": window_width, "since": now, "flips": 0, "held": False}
                container._pair_flip_guard = guard
            if guard["held"]:
                return
            if now - guard["since"] > 1.0:
                guard["since"], guard["flips"] = now, 0
            guard["flips"] += 1
            if guard["flips"] > PAIR_FLIP_LIMIT:
                guard["held"] = True
                if getattr(container, "_pair_side_by_side", None) is False:
                    return
                wide = False
            container._pair_side_by_side = wide
            if wide:
                left.grid_configure(row=0, column=0, columnspan=1, padx=(0, gap), pady=0)
                right.grid_configure(row=0, column=1, columnspan=1, padx=0, pady=0)
            else:
                left.grid_configure(row=0, column=0, columnspan=2, padx=0, pady=(0, gap if stack_gap is None else stack_gap))
                right.grid_configure(row=1, column=0, columnspan=2, padx=0, pady=0)
        container.bind("<Configure>", arrange, add="+")
        arrange()
        return arrange
    @staticmethod
    def _pair_inset(container) -> int:
        raw = container.cget("padding") if "padding" in container.keys() else ()
        padding = [int(float(str(v))) for v in container.tk.splitlist(raw)] or [0]
        inset = padding[0] + (padding[2] if len(padding) > 2 else padding[0])
        if container.winfo_class() == "TLabelframe":
            inset += 4
        return inset
    @staticmethod
    def _pair_natural_width(section) -> int:
        extra = 0
        pending = list(section.winfo_children())
        while pending:
            child = pending.pop()
            need = getattr(child, "_pair_wide_need", None)
            if need is not None and getattr(child, "_pair_side_by_side", None) is False:
                extra = max(extra, int(need) - child.winfo_reqwidth())
            pending.extend(child.winfo_children())
        return section.winfo_reqwidth() + max(0, extra)
    def build_ui(self) -> None:
        self.root.rowconfigure(0, weight=1)
        self.root.columnconfigure(0, weight=1)
        self._configure_ui_styles()
        notebook_pad = self._ui_px(3, 2)
        self.notebook = ttk.Notebook(self.root, padding=(notebook_pad, notebook_pad, notebook_pad, 0))
        self.notebook.grid(row=0, column=0, sticky="nsew")
        self.led_tab = ttk.Frame(self.notebook)
        self.motor_tab = ttk.Frame(self.notebook)
        self.difference_tab = ttk.Frame(self.notebook)
        self.keithley_tab = ttk.Frame(self.notebook)
        self.k6221_tab = ttk.Frame(self.notebook)
        self.notebook.add(self.led_tab, text="MOKE light")
        self.notebook.add(self.motor_tab, text="MOKE motor")
        self.notebook.add(self.difference_tab, text="MOKE magnet")
        self.notebook.add(self.k6221_tab, text="CIDWM")
        self.notebook.add(self.keithley_tab, text="MOKE-24")
        self.led_tab.rowconfigure(0, weight=1)
        self.led_tab.columnconfigure(0, weight=1)
        self.motor_tab.rowconfigure(0, weight=1)
        self.motor_tab.columnconfigure(0, weight=1)
        self.difference_tab.rowconfigure(0, weight=1)
        self.difference_tab.columnconfigure(0, weight=1)
        self.keithley_tab.rowconfigure(0, weight=1)
        self.keithley_tab.columnconfigure(0, weight=1)
        self.k6221_tab.rowconfigure(0, weight=1)
        self.k6221_tab.columnconfigure(0, weight=1)
        self.build_difference_ui()
        self.build_keithley_ui()
        self.build_k6221_ui()
        outer = ttk.Frame(self.led_tab, padding=8)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=0)
        outer.columnconfigure(1, weight=1)
        outer.rowconfigure(4, weight=0)
        outer.rowconfigure(6, weight=0)
        outer.rowconfigure(7, weight=1)
        self.led_outer = outer
        self.build_camera_launcher_ui(outer, row=0)
        connection = ttk.LabelFrame(outer, text="Serial connection", padding=8)
        connection.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 7))
        connection.columnconfigure(7, weight=1)
        ttk.Label(connection, text="LED port:").grid(row=0, column=0)
        self.port_combo = ttk.Combobox(connection, textvariable=self.port_var, width=11, state='normal')
        self.port_combo.grid(row=0, column=1, padx=4)
        ttk.Button(connection, text='Refresh', command=self.refresh_ports).grid(row=0, column=2, padx=3)
        self.connect_button = ttk.Button(connection, text="Connect", command=self.connect)
        self.connect_button.grid(row=0, column=3, padx=3)
        self.disconnect_button = ttk.Button(connection, text='Disconnect', command=self.disconnect)
        self.disconnect_button.grid(row=0, column=4, padx=3)
        self._create_connection_indicator(connection, 'led').grid(row=0, column=5, padx=(8, 1))
        ttk.Label(connection, textvariable=self.connection_var).grid(row=0, column=6, padx=(1, 10))
        ttk.Label(connection, textvariable=self.operation_var).grid(row=0, column=7, sticky='e')
        self.led_log_toggle_button = ttk.Button(connection, text='Show log', command=self.toggle_led_log, style='Compact.TButton', width=8)
        self.led_log_toggle_button.grid(row=0, column=8, padx=(8, 0))
        safety = ttk.Frame(outer)
        safety.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(0, 7))
        safety.columnconfigure(0, weight=1)
        ttk.Label(safety, text=f'Safety limit: current 0–{CURRENT_LIMIT}; start from 0 for a first test.', foreground='#9a4d00').grid(row=0, column=0, sticky='w')
        self.off_button = tk.Button(
            safety,
            text="Zero all / emergency off",
            command=self.all_off,
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=10,
            pady=4,
        )
        self.off_button.grid(row=0, column=1)
        global_frame = ttk.LabelFrame(outer, text="Global control", padding=8)
        global_frame.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0, 7))
        global_frame.columnconfigure(1, weight=1)
        ttk.Label(global_frame, text='All 4 currents:').grid(row=0, column=0, sticky='e', padx=(0, 6))
        preset_row = ttk.Frame(global_frame)
        preset_row.grid(row=0, column=1, sticky="ew")
        presets = ttk.Frame(preset_row)
        presets.grid(row=0, column=0, sticky="w")
        for index, value in enumerate((0, 10, 50, 100, 500)):
            button = ttk.Button(presets, text=str(value), width=6, command=lambda selected=value: self.apply_preset(selected))
            button.grid(row=0, column=index, padx=(0 if index == 0 else 4, 0))
            self.action_widgets.append(button)
        all_channel_buttons = ttk.Frame(preset_row)
        all_channel_buttons.grid(row=0, column=1, sticky="w")
        continuous = ttk.Button(all_channel_buttons, text='All 4 continuous on', command=self.all_continuous)
        continuous.grid(row=0, column=0)
        self.action_widgets.append(continuous)
        apply_all = ttk.Button(all_channel_buttons, text="Apply all", command=self.apply_all)
        apply_all.grid(row=0, column=1, padx=(4, 0))
        self.action_widgets.append(apply_all)
        query_all = ttk.Button(all_channel_buttons, text="Query all", command=self.query_all)
        query_all.grid(row=0, column=2, padx=(4, 0))
        self.action_widgets.append(query_all)
        self._arrange_pair_by_width(preset_row, presets, all_channel_buttons, gap=12, stack_gap=4)
        ttk.Label(global_frame, text='Continuous current, all 4:').grid(row=1, column=0, sticky='e', padx=(0, 6), pady=(6, 0))
        continuous_row = ttk.Frame(global_frame)
        continuous_row.grid(row=1, column=1, sticky="w", pady=(6, 0))
        ttk.Spinbox(continuous_row, from_=0, to=CURRENT_LIMIT, increment=1, textvariable=self.global_current_var, width=9).grid(row=0, column=0, sticky='w')
        set_continuous_current = ttk.Button(continuous_row, text='Set continuous current on all 4', command=self.apply_global_continuous_current)
        set_continuous_current.grid(row=0, column=1, sticky="w", padx=(6, 0))
        self.action_widgets.append(set_continuous_current)
        options_row = ttk.Frame(global_frame)
        options_row.grid(row=2, column=1, sticky="w", pady=(6, 0))
        ttk.Checkbutton(options_row, text='Read back after setting', variable=self.auto_readback_var).grid(row=0, column=0, sticky='w')
        ttk.Checkbutton(options_row, text='Show and edit advanced parameters p/g/d/f', variable=self.raw_edit_var, command=self.update_raw_state).grid(row=0, column=1, sticky='w', padx=(16, 0))
        channels_frame = ttk.Frame(outer)
        channels_frame.grid(row=4, column=0, sticky='new', padx=(0, 4), pady=(0, 7))
        channels_frame.columnconfigure(0, weight=1)
        for channel in CHANNELS:
            channels_frame.rowconfigure(channel - 1, weight=0)
            self.build_channel(channels_frame, channel, channel - 1, 0)
        led_plot = ttk.LabelFrame(outer, text='ROI intensity vs time (raw 16-bit, no background subtraction)', padding=6)
        led_plot.grid(row=4, column=1, sticky='new', padx=(4, 0), pady=(3, 10))
        led_plot.rowconfigure(1, weight=0)
        led_plot.columnconfigure(0, weight=1)
        plot_header = ttk.Frame(led_plot)
        plot_header.grid(row=0, column=0, sticky="ew", pady=(0, 4))
        roi_mean_label = ttk.Label(plot_header, textvariable=self.led_roi_mean_var, style='Metric.TLabel', width=37)
        roi_mean_label.grid(row=0, column=0, sticky="w")
        roi_hint_label = ttk.Label(plot_header, text='Shift + left-drag on the camera view to select an ROI', style='Muted.TLabel')
        roi_hint_label.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(plot_header, roi_mean_label, roi_hint_label, gap=12, stack_gap=2)
        self.led_intensity_canvas = tk.Canvas(
            led_plot,
            bg=THEME_COLORS["plot_background"],
            highlightthickness=1,
            highlightbackground=THEME_COLORS["plot_border"],
            height=self._ui_px(230, 135, canvas=True),
        )
        self.led_intensity_canvas.grid(row=1, column=0, sticky="nsew")
        self.led_intensity_canvas.bind('<Configure>', lambda _event: self._redraw_live_intensity_plots())
        self.build_stage_ui(outer, row=5, columnspan=2)
        self.led_log_frame = ttk.LabelFrame(outer, text='Program communication log', padding=5)
        self.led_log_frame.grid(row=6, column=0, columnspan=2, sticky="nsew")
        self.led_log_frame.rowconfigure(0, weight=1)
        self.led_log_frame.columnconfigure(0, weight=1)
        self.log_text = tk.Text(self.led_log_frame, height=5, wrap='none', state='disabled', font=(self.mono_font_family, self.ui_small_font_size), background='#fbfcfd', relief='flat', padx=5, pady=4)
        self.log_text.grid(row=0, column=0, sticky="nsew")
        scrollbar = ttk.Scrollbar(self.led_log_frame, command=self.log_text.yview)
        scrollbar.grid(row=0, column=1, sticky="ns")
        xscrollbar = ttk.Scrollbar(self.led_log_frame, orient='horizontal', command=self.log_text.xview)
        xscrollbar.grid(row=1, column=0, sticky="ew")
        self.log_text.configure(yscrollcommand=scrollbar.set, xscrollcommand=xscrollbar.set)
        self.log_display_paused = False
        self.log_pending_lines = []
        log_tools = ttk.Frame(self.led_log_frame)
        log_tools.grid(row=2, column=0, columnspan=2, sticky="ew")
        self.log_pause_button = ttk.Button(log_tools, text="Pause refresh", command=self.toggle_log_refresh)
        self.log_pause_button.pack(side="left")
        ttk.Button(log_tools, text="Copy shown log", command=self.copy_displayed_log).pack(side="left", padx=5)
        ttk.Button(log_tools, text="Save full log", command=self.save_communication_log).pack(side="left")
        ttk.Label(log_tools, text="Pausing only freezes the display; logging continues and catches up on resume.").pack(side="left", padx=8)
        self.led_log_frame.grid_remove()
    def build_camera_launcher_ui(self, outer: ttk.Frame, *, row: int) -> None:
        panel = ttk.LabelFrame(outer, text='PCO Camera Live', padding=self._ui_px(8, 5))
        panel.grid(row=row, column=0, columnspan=2, sticky='ew', pady=(0, 7))
        panel.columnconfigure(0, weight=1)
        ttk.Label(panel, textvariable=self.camera_window_status_var, style='Metric.TLabel').grid(row=0, column=0, sticky='w')
        actions = ttk.Frame(panel)
        actions.grid(row=0, column=1, sticky="e")
        self.camera_connect_button = ttk.Button(actions, text='Connect camera', style='Strong.TButton', command=self.connect_camera)
        self.camera_connect_button.pack(side="left", padx=(8, 4))
        self.camera_disconnect_button = ttk.Button(actions, text='Disconnect camera', command=self.disconnect_camera, state='disabled')
        self.camera_disconnect_button.pack(side="left", padx=4)
        self._create_connection_indicator(actions, 'camera').pack(side='left', padx=(5, 8))
        self.camera_show_button = ttk.Button(actions, text='Show Camera Live window', command=self.show_camera_live_window, state='disabled')
        self.camera_show_button.pack(side="left", padx=4)
        self.camera_hide_button = ttk.Button(actions, text='Hide view', command=self.hide_camera_live_window, state='disabled')
        self.camera_hide_button.pack(side="left", padx=(4, 0))
    STFMR_LOCKIN_WIDE_TABLE = {
        "f start GHz:": (0, 0), "f stop GHz:": (0, 1), "f step GHz:": (0, 2),
        "Mod. start Hz:": (0, 3), "Settle s:": (0, 4),
        "P start dBm:": (1, 0), "P stop dBm:": (1, 1), "P step dB:": (1, 2),
        "Mod. end Hz:": (1, 3), "Acquire s:": (1, 4),
        "Start A:": (2, 0), "Stop A:": (2, 1), "Step A:": (2, 2), "Loop:": (2, 3), "Comp. V:": (2, 4),
        "Meter:": (3, 0), "SR830 REF IN:": (3, 1), "SR830 TC:": (3, 2), "SR830 autorange": (3, 3),
        "Angle start °:": (3, 4),
        "MFLI reference:": (4, 0), "MFLI TC s:": (4, 1), "MFLI autorange": (4, 2),
        "Angle stop °:": (4, 3), "Step °:": (4, 4),
    }
    STFMR_LOCKIN_WIDE_GAPS = (16, 12)
    def _create_connection_indicator(self, parent: tk.Misc, key: str) -> tk.Canvas:
        status = "ref" in key.split("_") or "reference" in key
        canvas, item = create_lamp(parent, kind="status" if status else "connection")
        self.instrument_connection_indicators[key] = (canvas, item)
        return canvas
    def _set_connection_indicator(self, key: str, connected: bool, *, fault: bool = False) -> None:
        set_lamp(self.instrument_connection_indicators.get(key), lamp_state(connected, fault))
    def _configure_ui_styles(self) -> None:
        self.ui_font_family, self.mono_font_family = configure_tk_font_system(self.root)
        use_english_tk_dialogs(self.root)
        style = ttk.Style(self.root)
        if sys.platform == "darwin" and "clam" in style.theme_names():
            style.theme_use("clam")
        font_family = self.ui_font_family
        font_size = int(getattr(self.root, "_moke_ui_font_size", 10))
        small_font_size = int(getattr(self.root, "_moke_ui_small_font_size", 9))
        self.ui_font_size = font_size
        self.ui_small_font_size = small_font_size
        large_font_size = max(font_size + 3, int(round(15 * self.ui_scale)))
        px = self._ui_px
        colors = THEME_COLORS
        palette = {
            "background": colors["page"],
            "surface": colors["surface"],
            "text": colors["text"],
            "muted": colors["muted"],
            "border": colors["border"],
            "accent": colors["accent"],
            "accent_soft": "#e8f1f8",
            "success": colors["success"],
            "warning": colors["warning"],
            "status": colors["status"],
        }
        self.ui_palette = palette
        self.root.configure(background=palette["background"])
        style.configure(".", font=(font_family, font_size))
        style.configure("TFrame", background=palette["surface"])
        style.configure("TLabel", background=palette["surface"], foreground=palette["text"])
        for name in ("TCheckbutton", "TRadiobutton"):
            style.configure(name, background=palette["surface"], foreground=palette["text"])
            style.map(name, background=[("active", palette["surface"])])
        style.configure('TLabelframe', background=palette['surface'], bordercolor=palette['border'], lightcolor=palette['surface'], darkcolor=palette['surface'], relief='solid', borderwidth=1)
        style.configure('TLabelframe.Label', background=palette['surface'], foreground=palette['text'], font=(font_family, font_size, 'bold'))
        style.configure('TNotebook', background=palette['background'], borderwidth=0, tabmargins=(px(3, 2), px(3, 2), px(3, 2), 0))
        style.configure(
            "TNotebook.Tab",
            padding=(px(14, 7), px(7, 4)),
            font=(font_family, font_size),
            background=colors["tab"],
            foreground=palette["muted"],
            bordercolor=palette["border"],
            lightcolor=colors["tab"],
        )
        style.map(
            "TNotebook.Tab",
            background=[("selected", palette["surface"]), ("active", colors["button_active"])],
            foreground=[("selected", palette["accent"])],
            lightcolor=[("selected", palette["surface"])],
            font=[("selected", (font_family, font_size, "bold"))],
        )
        style.configure('TButton', background=colors['button'], bordercolor=palette['border'], lightcolor=colors['button'], darkcolor=colors['button'])
        style.map('TButton', background=[('disabled', colors['button']), ('pressed', colors['tab']), ('active', colors['button_active'])])
        for name in ("TEntry", "TCombobox", "TSpinbox"):
            style.configure(name, fieldbackground=palette['surface'], bordercolor=palette['border'], lightcolor=palette['surface'], darkcolor=palette['surface'])
            style.map(name, bordercolor=[("focus", palette["accent"])], lightcolor=[("focus", palette["accent"])])
        style.configure('Horizontal.TProgressbar', background=palette['accent'], troughcolor=colors['tab'], bordercolor=palette['border'], lightcolor=palette['accent'], darkcolor=palette['accent'])
        style.configure("Overview.TFrame", background=palette["background"])
        style.configure("Overview.TLabel", background=palette["background"], foreground=palette["muted"])
        style.configure('Tooltip.TLabel', background=palette['surface'], foreground=palette['text'], relief='solid', borderwidth=1, padding=(6, 4))
        style.configure("TButton", padding=(px(9, 5), px(6, 3)))
        style.configure("Compact.TButton", padding=(px(6, 4), px(5, 3)))
        style.configure("Inline.TButton", padding=(px(9, 5), px(3, 2)))
        style.configure("TLabel", padding=(0, px(2, 1)))
        style.configure("TCombobox", padding=(px(5, 3), px(5, 3)))
        style.configure("TSpinbox", padding=(px(5, 3), px(5, 3)))
        style.configure("TEntry", padding=(px(5, 3), px(5, 3)))
        style.configure("TCheckbutton", padding=(px(4, 2), px(4, 2)))
        style.configure("TRadiobutton", padding=(px(4, 2), px(4, 2)))
        style.configure('Strong.TButton', foreground=palette['accent'], font=(font_family, font_size, 'bold'))
        try:
            self.ui_button_roles = configure_button_roles(self.root, style)
        except Exception as error:
            self.ui_button_roles = {}
            print(f"Button styles not made: {error}", file=sys.stderr)
        style.configure('Metric.TLabel', foreground=palette['text'], font=(font_family, font_size, 'bold'))
        style.configure('LargeMetric.TLabel', foreground=palette['text'], font=(font_family, large_font_size, 'bold'))
        style.configure("Muted.TLabel", foreground=palette["muted"])
        style.configure("Warning.TLabel", foreground=palette["warning"])
        style.configure('Hint.TLabel', background='#fff1a8', foreground='#6f4500', padding=(px(8, 4), px(4, 2)), font=(font_family, font_size, 'bold'))
        style.configure('Success.TLabel', foreground=palette['success'], font=(font_family, font_size, 'bold'))
        style.configure('Status.TLabel', background=palette['status'], foreground=palette['text'], padding=(px(8, 4), px(4, 2)), relief='flat')
    def build_stage_ui(self, parent: ttk.Frame, row: int, columnspan: int=1) -> None:
        frame = ttk.LabelFrame(parent, text='Thorlabs K10CR1 analyser rotation stage (Kinesis)', padding=6)
        frame.grid(row=row, column=0, columnspan=columnspan, sticky='ew', pady=(0, 7))
        frame.columnconfigure(2, weight=1)
        row_pad = (5, 0)
        ttk.Label(frame, text="S/N:").grid(row=0, column=0, sticky="e", padx=(0, 4))
        self.stage_serial_entry = ttk.Entry(frame, textvariable=self.stage_serial_var, width=10)
        self.stage_serial_entry.grid(row=0, column=1, sticky="ew")
        connection = ttk.Frame(frame)
        connection.grid(row=0, column=2, sticky="ew", padx=(6, 0))
        connection.columnconfigure(6, weight=1)
        self.stage_connect_button = ttk.Button(connection, text='Connect', width=8, command=self.connect_stage)
        self.stage_connect_button.grid(row=0, column=0, padx=(0, 2))
        self.stage_disconnect_button = ttk.Button(connection, text='Disconnect', width=10, command=self.disconnect_stage)
        self.stage_disconnect_button.grid(row=0, column=1, padx=2)
        self.stage_read_button = ttk.Button(connection, text='Read status', width=11, command=self.refresh_stage_status)
        self.stage_read_button.grid(row=0, column=2, padx=(8, 2))
        self.stage_identify_button = ttk.Button(connection, text='Identify', width=8, command=self.identify_stage)
        self.stage_identify_button.grid(row=0, column=3, padx=2)
        self._create_connection_indicator(connection, 'stage').grid(row=0, column=4, padx=(10, 1))
        ttk.Label(connection, textvariable=self.stage_connection_var).grid(row=0, column=5, padx=(1, 4), sticky='w')
        stage_operation_label = ttk.Label(connection, width=1, anchor="e")
        stage_operation_label.grid(row=0, column=6, sticky="ew")
        show_trimmed(stage_operation_label, self.stage_operation_var)
        ttk.Label(frame, textvariable=self.stage_position_var, style='Metric.TLabel', width=20).grid(row=1, column=0, sticky='w', pady=row_pad)
        state_row = ttk.Frame(frame)
        state_row.grid(row=1, column=1, columnspan=2, sticky="ew", pady=row_pad)
        stage_state_label = ttk.Label(state_row, textvariable=self.stage_state_var, width=39)
        stage_state_label.grid(row=0, column=0, sticky="w")
        self.stage_safety_check = ttk.Checkbutton(state_row, text='Analyser, cables and motion direction confirmed safe', variable=self.stage_safety_var, command=self.update_stage_controls)
        self.stage_safety_check.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(state_row, stage_state_label, self.stage_safety_check, gap=10, stack_gap=5)
        ttk.Label(frame, text='Relative angle (°):').grid(row=2, column=0, sticky='e', padx=(0, 4), pady=row_pad)
        ttk.Entry(frame, textvariable=self.stage_relative_var, width=8).grid(row=2, column=1, sticky='ew', pady=row_pad)
        relative_button = ttk.Button(frame, text='Move relative', width=13, command=self.move_stage_relative)
        relative_button.grid(row=2, column=2, sticky="w", padx=(6, 0), pady=row_pad)
        ttk.Label(frame, text='Absolute angle (0–360°):').grid(row=3, column=0, sticky='e', padx=(0, 4), pady=row_pad)
        ttk.Entry(frame, textvariable=self.stage_absolute_var, width=8).grid(row=3, column=1, sticky='ew', pady=row_pad)
        absolute_actions = ttk.Frame(frame)
        absolute_actions.grid(row=3, column=2, sticky="w", padx=(6, 0), pady=row_pad)
        absolute_button = ttk.Button(absolute_actions, text='Go to absolute', width=14, command=self.move_stage_absolute)
        absolute_button.pack(side="left")
        home_button = ttk.Button(absolute_actions, text='Home', width=8, command=self.home_stage)
        home_button.pack(side="left", padx=(10, 0))
        self.stage_stop_button = tk.Button(
            absolute_actions,
            text="Stop now",
            command=self.stop_stage,
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=8,
        )
        self.stage_stop_button.pack(side="left", padx=(4, 0))
        ttk.Label(frame, text='Diagnostic nudge (≤1°):').grid(row=4, column=0, sticky='e', padx=(0, 4), pady=row_pad)
        ttk.Entry(frame, textvariable=self.stage_nudge_var, width=6).grid(row=4, column=1, sticky='ew', pady=row_pad)
        nudge_row = ttk.Frame(frame)
        nudge_row.grid(row=4, column=2, sticky="ew", padx=(6, 0), pady=row_pad)
        nudge_row.columnconfigure(1, weight=1)
        nudge_buttons = ttk.Frame(nudge_row)
        nudge_buttons.grid(row=0, column=0, sticky="w")
        nudge_minus = ttk.Button(nudge_buttons, text='− nudge', width=8, command=lambda: self.nudge_stage(-1))
        nudge_minus.pack(side="left")
        nudge_plus = ttk.Button(nudge_buttons, text='+ nudge', width=8, command=lambda: self.nudge_stage(1))
        nudge_plus.pack(side="left", padx=(4, 0))
        nudge_rule = ttk.Label(nudge_row, text='Only diagnostic nudges are allowed before Home; relative/absolute moves need Home first.', foreground='#9a4d00')
        nudge_rule.grid(row=0, column=1, sticky="ew", padx=(16, 0))
        nudge_rule.bind('<Configure>', lambda event: event.widget.configure(wraplength=max(200, event.width - 4)), add='+')
        tip = ttk.Label(
            frame,
            text=(
                "Tip: with the polariser at 90°, extinction is best near analyser reading 23°; "
                "with the polariser at 0°, near 12°. "
                "Fine-tune around the matching position."
                "\nRed light: 650 nm, blue light: 450 nm."
                "\nObjective turret: position 2 is the 5× objective, "
                "position 4 is the 100× objective."
            ),
            style="Hint.TLabel",
        )
        tip.grid(row=5, column=0, columnspan=3, sticky='ew', pady=(7, 0))
        tip_inset = 2 * self._ui_px(8, 4) + 6
        tip.bind('<Configure>', lambda event: event.widget.configure(wraplength=max(200, event.width - tip_inset)), add='+')
        self.stage_motion_widgets.extend((relative_button, absolute_button, nudge_minus, nudge_plus, home_button))
    def _build_moke_difference_box(self, parent) -> ttk.LabelFrame:
        mode_box = ttk.LabelFrame(parent, text="MOKE difference display", padding=5)
        mode_box.columnconfigure(0, weight=1)
        ttk.Label(mode_box, textvariable=self.difference_status_var, style='Metric.TLabel').grid(row=0, column=0, sticky='w')
        mode_row = ttk.Frame(mode_box)
        mode_row.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        mode_choices = ttk.Frame(mode_row)
        mode_choices.grid(row=0, column=0, sticky="w")
        for column, (value, label) in enumerate((('off', 'Off'), ('plain', 'Plain difference'), ('tracking', 'Drift tracking'), ('super', SUPER_MODE_LABEL))):
            button = ttk.Radiobutton(mode_choices, text=label, value=value, variable=self.difference_mode_var, command=self.select_difference_mode, state='disabled')
            button.grid(row=0, column=column, padx=(0, 6), sticky="w")
            self.difference_mode_buttons.append(button)
        mode_actions = ttk.Frame(mode_row)
        mode_actions.grid(row=1, column=0, sticky="w", pady=(3, 0))
        capture_button = ttk.Button(mode_actions, text='Recapture BG', command=self.capture_difference_background, state='disabled')
        capture_button.grid(row=0, column=0, sticky="w")
        self.difference_capture_buttons.append(capture_button)
        marker_button = ttk.Button(mode_actions, text='Add 100× marker', command=self.toggle_100x_marker, state='disabled', width=15)
        marker_button.grid(row=0, column=1, sticky="w", padx=(6, 0))
        self.objective_100x_marker_buttons.append(marker_button)
        self._arrange_pair_by_width(mode_row, mode_choices, mode_actions, gap=0, stack_gap=3)
        detail = ttk.Label(mode_box, textvariable=self.difference_detail_var, foreground='#9a4d00', width=1, wraplength=380)
        detail.grid(row=2, column=0, sticky="ew", pady=(3, 0))
        def follow_width(event) -> None:
            wrap = max(100, int(event.width) - 4)
            if int(float(str(event.widget.cget("wraplength")) or 0)) != wrap:
                event.widget.configure(wraplength=wrap)
        detail.bind("<Configure>", follow_width, add="+")
        focus = self.auto_focus
        focus_row = ttk.Frame(mode_box)
        focus_row.grid(row=3, column=0, sticky="ew", pady=(4, 0))
        focus_row.columnconfigure(2, weight=1)
        focus_button = ttk.Button(focus_row, text='Auto focus', command=focus.toggle_search, state='disabled', width=11)
        focus_button.grid(row=0, column=0, sticky="w")
        focus_tick = ttk.Checkbutton(focus_row, text='Keep in focus', variable=focus.keep_var, command=focus.keep_changed, state='disabled')
        focus_tick.grid(row=0, column=1, sticky="w", padx=(8, 0))
        focus.buttons.append(focus_button)
        focus.ticks.append(focus_tick)
        focus_status = ttk.Label(focus_row, style="Muted.TLabel", width=1)
        focus_status.grid(row=0, column=2, sticky="ew", padx=(8, 0))
        show_trimmed(focus_status, focus.status_var)
        mode_box.columnconfigure(0, weight=1)
        return mode_box
    def _build_moke_roi_edit_box(self, parent, page: str) -> ttk.LabelFrame:
        moke = page == "MOKE"
        roi_edit = ttk.LabelFrame(parent, text="MOKE ROI editing", padding=4)
        roi_edit.columnconfigure(0, weight=1)
        roi_top = ttk.Frame(roi_edit)
        roi_top.grid(row=0, column=0, sticky="ew")
        ttk.Label(roi_top, textvariable=self.moke_roi_var if moke else self.k6221_roi_var).pack(side='left')
        ttk.Label(roi_top, textvariable=self.moke_roi_mean_var if moke else self.k6221_roi_mean_var, style='Metric.TLabel').pack(side='left', padx=(8, 0))
        if moke:
            self.moke_clear_plot_button = ttk.Button(roi_top, text='Clear curve', command=self.clear_moke_plot, state='disabled')
            self.moke_clear_plot_button.pack(side="right", padx=(4, 0))
        ttk.Button(roi_top, text='Save difference raw image', command=lambda: self.save_current_processed_image(page)).pack(side='right', padx=(4, 0))
        ttk.Button(roi_top, text='Save raw 16-bit', command=lambda: self.save_current_raw_image(page)).pack(side='right', padx=(4, 0))
        ttk.Button(roi_top, text='Save current display', command=lambda: self.save_current_display_image(page)).pack(side='right', padx=(4, 0))
        roi_actions = ttk.Frame(roi_edit)
        roi_actions.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        roi_toolbar = ttk.Frame(roi_actions)
        roi_toolbar.pack(side="left")
        self._populate_roi_nudge_toolbar(roi_toolbar, self.edit_moke_roi, self.moke_roi_edit_buttons, initial_state='disabled')
        live_settings = ttk.Frame(roi_actions)
        live_settings.pack(side="right")
        ttk.Label(live_settings, text="Refresh s:").pack(side="left")
        ttk.Spinbox(live_settings, from_=0.05, to=3600.0, increment=0.1, textvariable=self.roi_live_interval_var, width=5).pack(side='left')
        ttk.Label(live_settings, text="Points:").pack(side="left", padx=(4, 1))
        ttk.Spinbox(live_settings, from_=10, to=10000, increment=10, textvariable=self.roi_live_max_points_var, width=6).pack(side='left')
        ttk.Button(live_settings, text='Apply', command=self.apply_roi_live_settings, width=5).pack(side='left', padx=(4, 0))
        roi_steps = ttk.Frame(roi_edit)
        roi_steps.grid(row=2, column=0, sticky="ew", pady=(4, 0))
        ttk.Label(roi_steps, text="Edit step:").pack(side="left")
        for key, unit in (("A", "°"), ("W", "px"), ("H", "px"), ("X", "px"), ("Y", "px")):
            ttk.Label(roi_steps, text=f"{key}=").pack(side="left", padx=(5, 1))
            ttk.Entry(roi_steps, textvariable=self.roi_edit_step_vars[key], width=5).pack(side='left')
            ttk.Label(roi_steps, text=unit).pack(side="left", padx=(1, 0))
        if moke:
            self.moke_field_source_combo = ttk.Combobox(roi_steps, textvariable=self.moke_field_source_var, values=('Unconfirmed', 'Out-of-plane', 'In-plane'), state='disabled', width=12)
            self.moke_field_source_combo.pack(side="right")
            ttk.Label(roi_steps, text="Field:").pack(side="right", padx=(6, 1))
        return roi_edit
    def _build_moke_display_controls(self, parent) -> ttk.Frame:
        display_controls = ttk.Frame(parent, padding=(5, 2, 5, 0))
        display_controls.columnconfigure(0, weight=1)
        clim_row = ttk.Frame(display_controls)
        clim_row.grid(row=0, column=0, sticky="ew", pady=(0, 4))
        clim_bar = ttk.Frame(clim_row)
        clim_bar.grid(row=0, column=0, sticky="w")
        ttk.Label(clim_bar, text="Difference CLim:").pack(side="left")
        low_entry = ttk.Entry(clim_bar, textvariable=self.difference_clim_low_var, width=6)
        low_entry.pack(side="left")
        ttk.Label(clim_bar, text="~").pack(side="left", padx=2)
        high_entry = ttk.Entry(clim_bar, textvariable=self.difference_clim_high_var, width=6)
        high_entry.pack(side="left")
        manual_button = ttk.Button(clim_bar, text='Manual', command=self.apply_difference_clim, state='disabled')
        manual_button.pack(side="left", padx=(5, 2))
        auto_button = ttk.Button(clim_bar, text='Auto', command=self.clear_difference_clim, state='disabled')
        auto_button.pack(side="left")
        histogram_button = ttk.Button(clim_bar, text='Histogram', command=self.show_difference_histogram, state='disabled')
        histogram_button.pack(side="left", padx=(3, 0))
        self.difference_clim_buttons.extend((manual_button, auto_button, histogram_button))
        ttk.Label(clim_bar, textvariable=self.difference_clim_status_var, style='Muted.TLabel', width=30, anchor='w').pack(side='left', padx=(5, 0))
        low_entry.bind("<Return>", lambda _event: self.apply_difference_clim())
        high_entry.bind("<Return>", lambda _event: self.apply_difference_clim())
        average_bar = ttk.Frame(clim_row)
        average_bar.grid(row=0, column=1, sticky="w")
        ttk.Label(average_bar, text="Difference temporal average:").pack(side="left")
        for count in (1, 2, 4, 8):
            button = ttk.Radiobutton(average_bar, text=f'{count} frames', value=count, variable=self.difference_temporal_average_var, command=self.apply_difference_display_average, state='disabled')
            button.pack(side="left", padx=(0, 4))
            self.difference_clim_buttons.append(button)
        ttk.Label(average_bar, text='Binning:').pack(side='left', padx=(5, 1))
        for factor in (1, 2, 4, 8):
            button = ttk.Radiobutton(
                average_bar,
                text=f"{factor}×{factor}",
                value=factor,
                variable=self.difference_spatial_binning_var,
                command=self.apply_difference_display_average,
                state="disabled",
            )
            button.pack(side="left", padx=(0, 3))
            self.difference_clim_buttons.append(button)
        self._arrange_pair_by_width(clim_row, clim_bar, average_bar, gap=12, stack_gap=4)
        filter_row = ttk.Frame(display_controls)
        filter_row.grid(row=1, column=0, sticky="ew", pady=(0, 4))
        filter_bar = ttk.Frame(filter_row)
        filter_bar.grid(row=0, column=0, sticky="w")
        ttk.Label(filter_bar, text="Mean filter:").pack(side="left")
        for filter_size, label in ((1, "Off"), (2, "2×2"), (4, "4×4")):
            button = ttk.Radiobutton(filter_bar, text=label, value=filter_size, variable=self.difference_mean_filter_var, command=self.apply_difference_display_average, state='disabled')
            button.pack(side="left", padx=(0, 4))
            self.difference_clim_buttons.append(button)
        ttk.Label(filter_bar, text='Sliding-window mean (applies to ROI, scans and processed images)', style='Muted.TLabel').pack(side='left', padx=(5, 0))
        exposure_bar = ttk.Frame(filter_row)
        exposure_bar.grid(row=0, column=1, sticky="w")
        ttk.Label(exposure_bar, text='Exposure ms:').pack(side='left', padx=(0, 2))
        exposure_entry = ttk.Entry(exposure_bar, textvariable=self.camera_exposure_ms_var, width=7)
        exposure_entry.pack(side="left")
        exposure_button = ttk.Button(exposure_bar, text='Apply exposure', command=self.apply_camera_exposure, state='disabled')
        exposure_button.pack(side="left", padx=(3, 2))
        self.difference_clim_buttons.append(exposure_button)
        exposure_entry.bind('<Return>', lambda _event: self.apply_camera_exposure())
        ttk.Label(exposure_bar, textvariable=self.camera_exposure_status_var, style='Muted.TLabel').pack(side='left', padx=(2, 0))
        self._arrange_pair_by_width(filter_row, filter_bar, exposure_bar, gap=12, stack_gap=4)
        video_bar = ttk.Frame(display_controls)
        video_bar.grid(row=2, column=0, sticky="ew")
        ttk.Label(video_bar, text="Camera Live 8-bit recording: FPS").pack(side="left")
        ttk.Entry(video_bar, textvariable=self.camera_video_fps_var, width=5).pack(side='left', padx=(3, 4))
        video_button = ttk.Button(video_bar, text='Start recording', command=self.toggle_camera_video_recording, state='disabled', width=13)
        video_button.pack(side="left")
        self.camera_video_buttons.append(video_button)
        if self.camera_video_button is None:
            self.camera_video_button = video_button
        ttk.Label(video_bar, textvariable=self.camera_video_status_var, style='Muted.TLabel').pack(side='left', padx=(7, 0))
        return display_controls
    def build_difference_ui(self) -> None:
        outer = ttk.Frame(self.difference_tab, padding=6)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        outer.rowconfigure(4, weight=1)
        top_row = ttk.Frame(outer)
        top_row.grid(row=0, column=0, sticky="ew", pady=(0, 3))
        top_row.columnconfigure(0, weight=1)
        mode_box = self._build_moke_difference_box(top_row)
        mode_box.grid(row=0, column=0, sticky="nsew", padx=(0, 3))
        connection = ttk.LabelFrame(top_row, text="KEPCO and gaussmeter ports", padding=5)
        connection.grid(row=0, column=1, sticky="nsew", padx=(3, 0))
        connection.columnconfigure(2, weight=1)
        connection.columnconfigure(5, weight=1)
        for row, (bop_label, bop_key, gauss_label, gauss_key) in enumerate(
            (
                ("Out-of-plane magnet", "OUT_BOP", "Out-of-plane gaussmeter", "OUT_GAUSS"),
                ("In-plane magnet", "IN_BOP", "In-plane gaussmeter", "IN_GAUSS"),
            )
        ):
            ttk.Label(connection, text=f'{bop_label}:').grid(row=row, column=0, sticky='e', padx=(0, 2), pady=1)
            self._create_connection_indicator(connection, f'magnet_{bop_key}').grid(row=row, column=1, padx=(0, 1), pady=1)
            bop_box = ttk.Combobox(connection, textvariable=self.magnet_port_vars[bop_key], width=10, state='normal')
            bop_box.grid(row=row, column=2, sticky="ew", padx=(0, 5), pady=1)
            self.magnet_port_combos[bop_key] = bop_box
            ttk.Label(connection, text=f'{gauss_label}:').grid(row=row, column=3, sticky='e', padx=(0, 2), pady=1)
            self._create_connection_indicator(connection, f'magnet_{gauss_key}').grid(row=row, column=4, padx=(0, 1), pady=1)
            gauss_box = ttk.Combobox(connection, textvariable=self.magnet_port_vars[gauss_key], width=10, state='normal')
            gauss_box.grid(row=row, column=5, sticky="ew", pady=1)
            self.magnet_port_combos[gauss_key] = gauss_box
        button_row = ttk.Frame(connection)
        button_row.grid(row=2, column=0, columnspan=6, sticky="new", pady=(2, 0))
        ttk.Button(button_row, text='Refresh', command=self.refresh_magnet_ports, width=7).pack(side='left', anchor='n', padx=2)
        self.magnet_connect_button = ttk.Button(button_row, text='Connect', command=self.connect_magnets, width=8)
        self.magnet_connect_button.pack(side="left", anchor="n", padx=2)
        self.magnet_disconnect_button = ttk.Button(button_row, text='Disconnect', command=self.disconnect_magnets, width=10)
        self.magnet_disconnect_button.pack(side="left", anchor="n", padx=2)
        connection_summary = ttk.Label(button_row, textvariable=self.magnet_connection_var, wraplength=self._ui_px(280))
        connection_summary.pack(side="left", padx=(6, 0))
        summary_line = tkfont.Font(root=self.root, family=self.ui_font_family, size=self.ui_font_size).metrics('linespace')
        connection.rowconfigure(2, minsize=int(connection_summary.winfo_reqheight()) + 2 * summary_line + 2)
        safety = ttk.Frame(outer, padding=(2, 2))
        safety.grid(row=1, column=0, sticky="ew")
        safety.columnconfigure(0, weight=1)
        ttk.Checkbutton(
            safety,
            text="Magnet polarity, cooling, wiring and personnel safety confirmed (non-zero current allowed)",
            variable=self.magnet_safety_var,
            command=self._update_magnet_controls,
        ).grid(row=0, column=0, sticky="w")
        self.magnet_initialize_button = ttk.Button(safety, text='Enable/zero active path', command=self.initialize_magnets)
        self.magnet_initialize_button.grid(row=0, column=1, padx=3)
        self.magnet_zero_button = tk.Button(
            safety,
            text="Zero both now",
            command=self.zero_both_magnets,
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=6,
            pady=1,
        )
        self.magnet_zero_button.grid(row=0, column=2)
        switch_row = ttk.Frame(safety)
        switch_row.grid(row=1, column=0, columnspan=3, sticky="ew", pady=(4, 0))
        switch_choices = ttk.Frame(switch_row)
        switch_choices.grid(row=0, column=0, sticky="w")
        ttk.Label(switch_choices, text='Physical selector:', style='Warning.TLabel').pack(side='left')
        for value, text in (('Unconfirmed', 'Unconfirmed'), ('Out-of-plane', 'Physically set to out-of-plane'), ('In-plane', 'Physically set to in-plane')):
            button = ttk.Radiobutton(switch_choices, text=text, value=value, variable=self.magnet_switch_var, command=self.select_magnet_switch)
            button.pack(side="left", padx=(3, 0))
            self.magnet_switch_buttons.append(button)
        switch_warning = ttk.Label(switch_row, text='Zero both paths before switching; the GUI must match the hardware', style='Warning.TLabel')
        switch_warning.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(switch_row, switch_choices, switch_warning, gap=10, stack_gap=2)
        control_row = ttk.Frame(outer)
        control_row.grid(row=2, column=0, sticky="ew", pady=(2, 3))
        control_row.columnconfigure(0, weight=1, uniform="moke_controls")
        control_row.columnconfigure(1, weight=1, uniform="moke_controls")
        channel_area = ttk.Frame(control_row)
        channel_area.grid(row=0, column=0, sticky="nsew", padx=(0, 3))
        channel_area.columnconfigure(0, weight=1)
        self._build_magnet_channel_ui(channel_area, "OUT", 0)
        self._build_magnet_channel_ui(channel_area, "IN", 1)
        read_row = ttk.Frame(channel_area, padding=(1, 2))
        read_row.grid(row=2, column=0, sticky="ew")
        self.magnet_read_button = ttk.Button(read_row, text='Read active path', command=self.read_all_magnets)
        self.magnet_read_button.pack(side="left", padx=(0, 4))
        ttk.Checkbutton(read_row, text='Continuous', variable=self.magnet_auto_poll_var, command=self._magnet_poll_changed).pack(side='left')
        ttk.Label(read_row, text="Interval s:").pack(side="left", padx=(5, 1))
        ttk.Spinbox(read_row, from_=0.2, to=10.0, increment=0.1, textvariable=self.magnet_poll_interval_var, width=5).pack(side='left')
        scan_box = ttk.LabelFrame(control_row, text='Magnet current scan and ROI acquisition', padding=5)
        scan_box.grid(row=0, column=1, sticky="nsew", padx=(3, 0))
        scan_box.columnconfigure(0, weight=1)
        scan_params = ttk.Frame(scan_box)
        scan_params.grid(row=0, column=0, sticky="w")
        ttk.Label(scan_params, text='Start A:').grid(row=0, column=0, sticky='e', padx=(0, 3))
        ttk.Entry(scan_params, textvariable=self.magnet_scan_start_current_var, width=7).grid(row=0, column=1, sticky='ew', padx=(0, 8))
        ttk.Label(scan_params, text='End A:').grid(row=0, column=2, sticky='e', padx=(0, 3))
        ttk.Entry(scan_params, textvariable=self.magnet_scan_end_current_var, width=7).grid(row=0, column=3, sticky='ew')
        ttk.Label(scan_params, text='Step A:').grid(row=1, column=0, sticky='e', padx=(0, 3), pady=(3, 0))
        ttk.Entry(scan_params, textvariable=self.magnet_scan_step_current_var, width=7).grid(row=1, column=1, sticky='ew', padx=(0, 8), pady=(3, 0))
        ttk.Label(scan_params, text='Loop:').grid(row=1, column=2, sticky='e', padx=(0, 3), pady=(3, 0))
        ttk.Spinbox(scan_params, from_=1, to=1000, increment=1, textvariable=self.magnet_scan_loop_var, width=5).grid(row=1, column=3, sticky='ew', pady=(3, 0))
        ttk.Label(scan_params, text='Settle s:').grid(row=2, column=0, sticky='e', padx=(0, 3), pady=(3, 0))
        ttk.Entry(scan_params, textvariable=self.magnet_scan_settle_var, width=7).grid(row=2, column=1, sticky='ew', padx=(0, 8), pady=(3, 0))
        ttk.Label(scan_params, text='Acquire s:').grid(row=2, column=2, sticky='e', padx=(0, 3), pady=(3, 0))
        ttk.Entry(scan_params, textvariable=self.magnet_scan_collect_var, width=7).grid(row=2, column=3, sticky='ew', pady=(3, 0))
        scan_buttons = ttk.Frame(scan_box)
        scan_buttons.grid(row=1, column=0, sticky="ew", pady=(4, 0))
        scan_actions = ttk.Frame(scan_buttons)
        scan_actions.grid(row=0, column=0, sticky="w")
        self.magnet_scan_start_button = ttk.Button(scan_actions, text='Start scan', command=self.start_magnet_scan, width=10)
        self.magnet_scan_start_button.pack(side="left", padx=(0, 3))
        self.magnet_scan_stop_button = ttk.Button(scan_actions, text='Stop/zero', command=self.stop_magnet_scan, width=9)
        self.magnet_scan_stop_button.pack(side="left", padx=3)
        self.magnet_scan_save_button = ttk.Button(scan_actions, text='Save CSV + PNG', command=self.save_magnet_scan_csv, width=16)
        self.magnet_scan_save_button.pack(side="left", padx=3)
        self.magnet_save_images_check = ttk.Checkbutton(scan_buttons, text='Save processed images too', variable=self.magnet_save_images_var, command=self.configure_magnet_image_saving)
        self.magnet_save_images_check.grid(row=0, column=1, sticky="w")
        self._arrange_pair_by_width(scan_buttons, scan_actions, self.magnet_save_images_check, gap=8, stack_gap=4)
        progress_row = ttk.Frame(scan_box)
        progress_row.grid(row=2, column=0, sticky="ew", pady=(5, 0))
        progress_row.columnconfigure(0, weight=1)
        self.magnet_scan_progress = ttk.Progressbar(progress_row, mode='determinate', maximum=1, value=0, length=150)
        self.magnet_scan_progress.grid(row=0, column=0, sticky="ew", padx=(0, 7))
        ttk.Label(progress_row, textvariable=self.magnet_scan_eta_var, foreground=THEME_COLORS['accent'], font=(self.ui_font_family, self.ui_small_font_size, 'bold')).grid(row=0, column=1, sticky='e')
        scan_path_label = ttk.Label(scan_box, text='Path: start→end→start; both KEPCOs to 0 A at every end (done, stop, error).', foreground='#9a4d00', wraplength=420)
        scan_path_label.grid(row=3, column=0, sticky="ew", pady=(2, 0))
        scan_folder_label = ttk.Label(scan_box, textvariable=self.magnet_image_directory_var, foreground='#555555', wraplength=350)
        scan_folder_label.grid(row=4, column=0, sticky="w", pady=(2, 0))
        scan_wrap = {"width": None}
        def wrap_scan_notes(event) -> None:
            width = max(200, int(event.width) - 20)
            if scan_wrap["width"] == width:
                return
            scan_wrap["width"] = width
            scan_path_label.configure(wraplength=width)
            scan_folder_label.configure(wraplength=width)
        scan_box.bind("<Configure>", wrap_scan_notes, add="+")
        roi_edit = self._build_moke_roi_edit_box(outer, "MOKE")
        roi_edit.grid(row=3, column=0, sticky="ew", pady=(0, 3))
        data_frame = ttk.Frame(outer)
        data_frame.grid(row=4, column=0, sticky="nsew")
        data_frame.rowconfigure(1, weight=1)
        plot_title = "Magnet current vs ROI mean intensity (top axis: Magnetic field (Gs))"
        plot_title_width = tkfont.Font(root=self.root, family=self.ui_font_family, size=self.ui_font_size, weight='bold').measure(plot_title) + self._ui_px(24)
        data_frame.columnconfigure(0, weight=2, uniform="moke_bottom_plots")
        data_frame.columnconfigure(1, weight=1, uniform='moke_bottom_plots', minsize=plot_title_width)
        display_controls = self._build_moke_display_controls(data_frame)
        display_controls.grid(row=0, column=0, columnspan=2, sticky='ew', pady=(0, 4))
        self.difference_clim_low_var.trace_add('write', self._schedule_difference_clim_live_update)
        self.difference_clim_high_var.trace_add('write', self._schedule_difference_clim_live_update)
        intensity_box = ttk.LabelFrame(data_frame, text='ROI mean intensity vs time (live)', padding=6)
        intensity_box.grid(row=1, column=0, sticky="nsew", padx=(0, 5))
        intensity_box.rowconfigure(0, weight=1)
        intensity_box.columnconfigure(0, weight=1)
        self.moke_intensity_canvas = tk.Canvas(
            intensity_box,
            bg=THEME_COLORS["plot_background"],
            highlightthickness=1,
            highlightbackground=THEME_COLORS["plot_border"],
            height=self._ui_px(200, 125, canvas=True),
        )
        self.moke_intensity_canvas.grid(row=0, column=0, sticky="nsew")
        self.moke_intensity_canvas.bind('<Configure>', lambda _event: self._redraw_live_intensity_plots())
        plot_box = ttk.LabelFrame(data_frame, text=plot_title, padding=6)
        plot_box.grid(row=1, column=1, sticky="nsew")
        plot_box.rowconfigure(0, weight=1)
        plot_box.columnconfigure(0, weight=1)
        self.moke_plot_canvas = tk.Canvas(
            plot_box,
            bg=THEME_COLORS["plot_background"],
            highlightthickness=1,
            highlightbackground=THEME_COLORS["plot_border"],
            height=self._ui_px(200, 125, canvas=True),
        )
        self.moke_plot_canvas.grid(row=0, column=0, sticky="nsew")
        self.moke_plot_canvas.bind('<Configure>', lambda _event: self._redraw_moke_plot())
        self.moke_field_source_var.trace_add('write', lambda *_args: self._redraw_moke_plot())
        ttk.Label(outer, textvariable=self.magnet_status_var, style='Status.TLabel', anchor='w').grid(row=5, column=0, sticky='ew', pady=(4, 0))
        self._update_magnet_scan_controls()
    def _build_magnet_channel_ui(self, parent, key: str, row: int) -> None:
        label = MAGNET_CHANNEL_LABELS[key]
        bop_port = "COM14" if key == "OUT" else "COM12"
        gauss_port = "COM13" if key == "OUT" else "COM15"
        panel = ttk.LabelFrame(parent, text=f'{label} path (BOP {bop_port}; Gauss {gauss_port})', padding=4)
        panel.grid(row=row, column=0, sticky='ew', pady=(0, 2) if row == 0 else 0)
        ttk.Label(panel, text="Target A:").grid(row=0, column=0, sticky="e")
        target_entry = ttk.Entry(panel, textvariable=self.magnet_target_vars[key], width=7)
        target_entry.grid(row=0, column=1, sticky="ew", padx=(1, 3))
        write_button = ttk.Button(panel, text='Write', command=lambda selected=key: self.set_magnet_current(selected), width=5)
        write_button.grid(row=0, column=2, sticky="ew", padx=1)
        flip_button = ttk.Button(panel, text='Flip', command=lambda selected=key: self.flip_magnet_current(selected), width=5)
        flip_button.grid(row=0, column=3, sticky="ew", padx=1)
        zero_button = ttk.Button(panel, text='Zero current', command=lambda selected=key: self.zero_magnet(selected))
        zero_button.grid(row=0, column=4, sticky="ew", padx=(1, 0))
        self.magnet_channel_control_widgets[key] = {'target': target_entry, 'write': write_button, 'flip': flip_button, 'zero': zero_button}
        ttk.Label(panel, text="I:").grid(row=1, column=0, sticky="e", pady=(2, 0))
        ttk.Label(panel, textvariable=self.magnet_current_vars[key], style='Metric.TLabel').grid(row=1, column=1, sticky='w', pady=(2, 0))
        ttk.Label(panel, text='Field:').grid(row=1, column=2, sticky='e', pady=(2, 0))
        ttk.Label(panel, textvariable=self.magnet_field_vars[key], style='Metric.TLabel').grid(row=1, column=3, columnspan=2, sticky='w', pady=(2, 0))
        ttk.Label(panel, text='Step A:').grid(row=2, column=0, sticky='e', pady=(3, 0))
        step_entry = ttk.Entry(panel, textvariable=self.magnet_manual_step_vars[key], width=7)
        step_entry.grid(row=2, column=1, sticky="ew", padx=(1, 3), pady=(3, 0))
        down_button = ttk.Button(panel, text='↓ Down', command=lambda selected=key: self.step_magnet_current(selected, -1), width=7)
        down_button.grid(row=2, column=2, sticky="ew", padx=1, pady=(3, 0))
        up_button = ttk.Button(panel, text='↑ Up', command=lambda selected=key: self.step_magnet_current(selected, 1), width=5)
        up_button.grid(row=2, column=3, sticky="ew", padx=1, pady=(3, 0))
        field_zero_button = ttk.Button(panel, text='Zero field', command=lambda selected=key: self.zero_magnet_field(selected), width=8)
        field_zero_button.grid(row=2, column=4, sticky='ew', padx=(1, 0), pady=(3, 0))
        self.magnet_channel_control_widgets[key].update({'field_zero': field_zero_button, 'step': step_entry, 'down': down_button, 'up': up_button})
        panel.columnconfigure(1, weight=1)
        panel.columnconfigure(5, weight=1000)
    def build_keithley_ui(self) -> None:
        outer = ttk.Frame(self.keithley_tab, padding=7)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        outer.rowconfigure(4, weight=1)
        top = ttk.Frame(outer)
        top.grid(row=0, column=0, sticky="ew", pady=(0, 5))
        top.columnconfigure(1, weight=1)
        instruments = ttk.LabelFrame(top, text='MOKE-24 instrument connection', padding=self._ui_px(6, 4))
        instruments.grid(row=0, column=0, sticky="nsew", padx=(0, 4))
        device = ttk.Frame(instruments)
        device.grid(row=0, column=0, sticky="ew", pady=1)
        device.columnconfigure(1, weight=1)
        device.columnconfigure(6, weight=1000)
        ttk.Label(device, text='Keithley:', width=11, anchor='e').grid(row=0, column=0, sticky='e')
        ttk.Entry(device, textvariable=self.keithley_resource_var, width=18).grid(row=0, column=1, sticky='w', padx=(0, 4))
        self.keithley_connect_button = ttk.Button(device, text='Connect', width=8, command=self.connect_keithley)
        self.keithley_connect_button.grid(row=0, column=2, padx=1)
        self.keithley_disconnect_button = ttk.Button(device, text='Disconnect', width=10, command=self.disconnect_keithley)
        self.keithley_disconnect_button.grid(row=0, column=3, padx=1)
        self._create_connection_indicator(device, 'keithley2410').grid(row=0, column=4, padx=(5, 1))
        ttk.Label(device, textvariable=self.keithley_connection_var, width=13, anchor='w').grid(row=0, column=5, sticky='w', padx=(1, 0))
        settings = ttk.Frame(device)
        settings.grid(row=1, column=1, columnspan=5, sticky="w", pady=(4, 0))
        ttk.Label(settings, text="Model:").pack(side="left", padx=(0, 3))
        self.keithley_model_combo = ttk.Combobox(settings, textvariable=self.keithley_model_var, values=tuple(KEITHLEY_MODELS), state='readonly', width=6)
        self.keithley_model_combo.pack(side="left", padx=(0, 10))
        self.keithley_model_combo.bind("<<ComboboxSelected>>", lambda event: self._update_keithley_controls())
        ttk.Label(settings, text="Current limit (A):").pack(side="left", padx=(0, 3))
        self.keithley_compliance_entry = ttk.Entry(settings, textvariable=self.keithley_compliance_var, width=9)
        self.keithley_compliance_entry.pack(side="left")
        output = ttk.LabelFrame(top, text="Keithley output", padding=8)
        output.grid(row=0, column=1, sticky="nsew")
        output.columnconfigure(10, weight=1)
        for panel_row in range(3):
            output.rowconfigure(panel_row, weight=1)
        ttk.Checkbutton(
            output,
            text="Wiring, current limit and manual/scan voltage range confirmed safe",
            variable=self.keithley_safety_var,
            command=self._update_keithley_controls,
        ).grid(row=0, column=0, columnspan=11, sticky="w", pady=(0, 6))
        ttk.Label(output, text="Manual V:").grid(row=1, column=0, sticky="e")
        ttk.Entry(output, textvariable=self.keithley_manual_voltage_var, width=9).grid(row=1, column=1, padx=(0, 4))
        manual_write = ttk.Button(output, text='Write', command=self.write_keithley_manual_voltage, width=7)
        manual_write.grid(row=1, column=2, padx=(0, 3))
        manual_flip = ttk.Button(output, text='Flip', command=self.flip_keithley_manual_voltage, width=7)
        manual_flip.grid(row=1, column=3, padx=(0, 3))
        self.keithley_manual_zero_button = ttk.Button(output, text='Zero', command=lambda: self._submit_keithley_manual_voltage(0.0, 'zero', require_safety=False), width=7)
        self.keithley_manual_zero_button.grid(row=1, column=4, padx=(0, 10))
        ttk.Label(output, text="Step V:").grid(row=1, column=5, sticky="e")
        ttk.Entry(output, textvariable=self.keithley_manual_step_var, width=8).grid(row=1, column=6, padx=(0, 4))
        manual_down = ttk.Button(output, text='↓ Down', command=lambda: self.step_keithley_manual_voltage(-1), width=8)
        manual_down.grid(row=1, column=7, padx=(0, 3))
        manual_up = ttk.Button(output, text='↑ Up', command=lambda: self.step_keithley_manual_voltage(1), width=8)
        manual_up.grid(row=1, column=8)
        self.keithley_manual_buttons.extend((manual_write, manual_flip, manual_down, manual_up))
        self.keithley_off_button = tk.Button(
            output,
            text=f"{self.keithley_model_var.get()} zero / output off",
            command=lambda: self.stop_keithley_scan("zero / output off"),
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=12,
            pady=2,
        )
        self.keithley_off_button.grid(row=1, column=9, padx=(10, 2), sticky="w")
        ttk.Label(output, textvariable=self.keithley_voltage_var, anchor='w').grid(row=2, column=0, columnspan=9, sticky='ew', pady=(7, 0))
        self._arrange_pair_by_width(top, instruments, output)
        hazard = ttk.Label(outer, textvariable=self.keithley_hazard_var, foreground='#a34b00')
        hazard.grid(row=1, column=0, sticky="ew", pady=(0, 5))
        hazard.bind('<Configure>', lambda event: event.widget.configure(wraplength=max(200, event.width - 4)))
        acquisition = ttk.Frame(outer)
        acquisition.grid(row=2, column=0, sticky="ew", pady=(0, 7))
        acquisition.columnconfigure(1, weight=1)
        scan = ttk.LabelFrame(acquisition, text='Voltage scan and ROI acquisition', padding=8)
        scan.grid(row=0, column=0, sticky="nsew")
        ttk.Label(scan, text="Start V:").grid(row=0, column=0)
        ttk.Entry(scan, textvariable=self.keithley_start_var, width=8).grid(row=0, column=1, padx=(0, 8))
        ttk.Label(scan, text="End V:").grid(row=0, column=2)
        ttk.Entry(scan, textvariable=self.keithley_end_var, width=8).grid(row=0, column=3, padx=(0, 8))
        ttk.Label(scan, text="Step V:").grid(row=0, column=4)
        ttk.Entry(scan, textvariable=self.keithley_step_var, width=8).grid(row=0, column=5, padx=(0, 12))
        ttk.Label(scan, text="Settle s:").grid(row=0, column=6)
        ttk.Entry(scan, textvariable=self.keithley_settle_var, width=7).grid(row=0, column=7, padx=(0, 8))
        ttk.Label(scan, text="Acquire s:").grid(row=0, column=8)
        ttk.Entry(scan, textvariable=self.keithley_collect_var, width=7).grid(row=0, column=9)
        ttk.Label(scan, textvariable=self.keithley_roi_var).grid(row=1, column=0, columnspan=6, sticky='w', pady=(8, 0))
        self.keithley_save_images_check = ttk.Checkbutton(scan, text='Save processed images too', variable=self.keithley_save_images_var, command=self.configure_keithley_image_saving)
        self.keithley_save_images_check.grid(row=1, column=6, columnspan=4, sticky='e', pady=(8, 0))
        scan_actions = ttk.Frame(scan)
        scan_actions.grid(row=2, column=0, columnspan=10, sticky="w", pady=(8, 0))
        self.keithley_start_button = ttk.Button(scan_actions, text='Start round-trip scan', command=self.start_keithley_scan)
        self.keithley_start_button.pack(side="left", padx=(0, 4))
        self.keithley_stop_button = ttk.Button(scan_actions, text='Stop scan', command=self.stop_keithley_scan)
        self.keithley_stop_button.pack(side="left", padx=(0, 4))
        self.keithley_save_button = ttk.Button(scan_actions, text='Save CSV + PNG', command=self.save_keithley_csv)
        self.keithley_save_button.pack(side="left")
        progress_row = ttk.Frame(scan)
        progress_row.grid(row=3, column=0, columnspan=10, sticky="ew", pady=(6, 0))
        progress_row.columnconfigure(0, weight=1)
        self.keithley_scan_progress = ttk.Progressbar(progress_row, mode='determinate', maximum=1, value=0, length=180)
        self.keithley_scan_progress.grid(row=0, column=0, sticky="ew", padx=(0, 8))
        ttk.Label(progress_row, textvariable=self.keithley_scan_eta_var, style='Success.TLabel').grid(row=0, column=1, sticky='e')
        ttk.Label(scan, textvariable=self.keithley_image_directory_var, foreground='#555555').grid(row=4, column=0, columnspan=10, sticky='w', pady=(4, 0))
        roi_edit = ttk.LabelFrame(acquisition, text="ROI editing", padding=7)
        roi_edit.grid(row=0, column=1, sticky="nsew")
        roi_edit.columnconfigure(9, weight=1)
        actions = ttk.Frame(roi_edit)
        actions.grid(row=0, column=0, columnspan=10, sticky="ew")
        toolbar = ttk.Frame(actions)
        toolbar.pack(side="left")
        self._populate_roi_nudge_toolbar(toolbar, self.edit_2410_roi, self.keithley_roi_edit_buttons)
        ttk.Label(actions, textvariable=self.keithley_roi_mean_var, style='Metric.TLabel', width=-30, wraplength=self._ui_px(240)).pack(side='right', padx=(8, 2))
        roi_steps = ttk.Frame(roi_edit)
        roi_steps.grid(row=1, column=0, columnspan=10, sticky="w", pady=(6, 0))
        ttk.Label(roi_steps, text="Step:", style="Muted.TLabel").pack(side="left")
        for key, unit in (("A", "°"), ("W", "px"), ("H", "px"), ("X", "px"), ("Y", "px")):
            ttk.Label(roi_steps, text=f"{key}=").pack(side="left", padx=(5, 1))
            ttk.Entry(roi_steps, textvariable=self.roi_edit_step_vars[key], width=5).pack(side='left')
            ttk.Label(roi_steps, text=unit).pack(side="left", padx=(1, 0))
        live_row = ttk.Frame(roi_edit)
        live_row.grid(row=2, column=0, columnspan=10, sticky="w", pady=(6, 0))
        ttk.Label(live_row, text="Live refresh (s/point):").pack(side="left")
        ttk.Spinbox(live_row, from_=0.05, to=3600.0, increment=0.1, textvariable=self.roi_live_interval_var, width=8).pack(side='left', padx=(3, 12))
        ttk.Label(live_row, text="Max points:").pack(side="left")
        ttk.Spinbox(live_row, from_=10, to=10000, increment=10, textvariable=self.roi_live_max_points_var, width=8).pack(side='left', padx=(3, 0))
        image_buttons = ttk.Frame(roi_edit)
        image_buttons.grid(row=3, column=0, columnspan=10, pady=(6, 0), sticky="w")
        ttk.Button(image_buttons, text='Apply live settings', command=self.apply_roi_live_settings).pack(side='left', padx=(0, 6))
        ttk.Button(image_buttons, text='Save processed image', command=lambda: self.save_current_processed_image(self._keithley_page_model())).pack(side='left', padx=(0, 3))
        ttk.Button(image_buttons, text='Save raw 16-bit image', command=lambda: self.save_current_raw_image(self._keithley_page_model())).pack(side='left')
        video_bar = ttk.Frame(roi_edit)
        video_bar.grid(row=4, column=0, columnspan=10, sticky='ew', pady=(6, 0))
        ttk.Label(video_bar, text="Camera Live 8-bit recording: FPS").pack(side="left")
        ttk.Entry(video_bar, textvariable=self.camera_video_fps_var, width=5).pack(side='left', padx=(3, 4))
        keithley_video_button = ttk.Button(video_bar, text='Start recording', command=self.toggle_camera_video_recording, state='disabled', width=-16)
        keithley_video_button.pack(side="left")
        self.camera_video_buttons.append(keithley_video_button)
        ttk.Label(video_bar, textvariable=self.camera_video_status_var, style='Muted.TLabel', width=-36, wraplength=self._ui_px(290)).pack(side='left', padx=(7, 0))
        self._arrange_pair_by_width(acquisition, scan, roi_edit, gap=7)
        ttk.Label(outer, text='Hold Shift and left-drag in the camera window to select an ROI; scans require difference mode.', foreground='#9a4d00').grid(row=3, column=0, sticky='w', pady=(0, 7))
        data_frame = ttk.Frame(outer)
        data_frame.grid(row=4, column=0, sticky="nsew")
        data_frame.rowconfigure(0, weight=1)
        for column in range(2):
            data_frame.columnconfigure(column, weight=1, uniform="moke24_plots")
        def plot_box(column: int, title: str, redraw) -> tk.Canvas:
            frame = ttk.LabelFrame(data_frame, text=title, padding=6)
            frame.grid(row=0, column=column, sticky='nsew', padx=(0 if column == 0 else 3, 0 if column == 1 else 3))
            frame.rowconfigure(0, weight=1)
            frame.columnconfigure(0, weight=1)
            canvas = tk.Canvas(
                frame,
                bg=THEME_COLORS["plot_background"],
                highlightthickness=1,
                highlightbackground=THEME_COLORS["plot_border"],
                width=self._ui_px(160, 100, canvas=True),
                height=self._ui_px(200, 120, canvas=True),
            )
            canvas.grid(row=0, column=0, sticky="nsew")
            for sequence in ("<Configure>", "<Map>"):
                canvas.bind(sequence, lambda _event: redraw(), add="+")
            return canvas
        self.keithley_intensity_canvas = plot_box(0, 'ROI mean intensity vs time (live)', self._redraw_live_intensity_plots)
        self.keithley_plot_canvas = plot_box(1, 'Voltage vs ROI mean (voltage scan)', self._redraw_keithley_plot)
        ttk.Label(outer, textvariable=self.keithley_status_var, style='Status.TLabel', anchor='w').grid(row=5, column=0, sticky='ew', pady=(8, 0))
        self._update_keithley_controls()
    def build_k6221_ui(self) -> None:
        outer = ttk.Frame(self.k6221_tab, padding=7)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        connection = ttk.LabelFrame(outer, text="Instruments", padding=7)
        connection.grid(row=0, column=0, sticky="ew")
        connection.columnconfigure(6, weight=1)
        for row, (name, key, resource, connect, disconnect, state) in enumerate((
            ("6221", "keithley6221", self.k6221_resource_var,
             self.connect_k6221, self.disconnect_k6221, self.k6221_connection_var),
            ("Avtech AVR-E3-B (50 Ω load required)", "avtech", self.avtech_resource_var,
             self.connect_avtech, self.disconnect_avtech, self.avtech_connection_var),
        )):
            pady = (0 if row == 0 else 3, 0)
            ttk.Label(connection, text=name).grid(row=row, column=0, sticky="w", padx=(0, 6), pady=pady)
            ttk.Entry(connection, textvariable=resource, width=18).grid(row=row, column=1, pady=pady)
            connect_button = ttk.Button(connection, text="Connect", width=8, command=connect)
            connect_button.grid(row=row, column=2, padx=(6, 0), pady=pady)
            disconnect_button = ttk.Button(connection, text="Disconnect", width=10, command=disconnect)
            disconnect_button.grid(row=row, column=3, pady=pady)
            self._create_connection_indicator(connection, key).grid(row=row, column=4, padx=3, pady=pady)
            ttk.Label(connection, textvariable=state, width=13).grid(row=row, column=5, sticky="w", pady=pady)
            if key == "avtech":
                self.avtech_connect_button = connect_button
                self.avtech_disconnect_button = disconnect_button
            else:
                self.k6221_connect_button = connect_button
                self.k6221_disconnect_button = disconnect_button
        ttk.Checkbutton(
            connection,
            text="6221 wiring, sample current/compliance and output parameters confirmed safe",
            variable=self.k6221_safety_var,
            command=self._update_k6221_controls,
        ).grid(
            row=2,
            column=0,
            columnspan=7,
            sticky="w",
            pady=(8, 0),
        )
        output = ttk.LabelFrame(outer, text="Pulse settings", padding=7)
        output.grid(row=1, column=0, sticky="ew", pady=(7, 0))
        output.columnconfigure(12, weight=1)
        def source_fields(line: int, name: str, fields) -> None:
            pady = (0 if line == 0 else 6, 0)
            ttk.Label(output, text=name).grid(row=line, column=0, sticky="w", padx=(0, 6), pady=pady)
            for column, (label, variable) in enumerate(fields):
                ttk.Label(output, text=label).grid(row=line, column=1 + 2 * column, sticky='e', padx=(0 if column == 0 else 10, 3), pady=pady)
                ttk.Entry(output, textvariable=variable, width=7).grid(row=line, column=2 + 2 * column, sticky='w', pady=pady)
        source_fields(0, '6221', (('|I| mA:', self.k6221_current_var), ('Width µs:', self.k6221_width_var), ('Pulse count:', self.k6221_count_var), ('Compliance V:', self.k6221_compliance_var)))
        self.k6221_apply_button = ttk.Button(output, text='Apply +I pulse', command=lambda: self.apply_k6221_output(1))
        self.k6221_apply_button.grid(row=0, column=9, sticky="ew", padx=(10, 3))
        self.k6221_apply_negative_button = ttk.Button(output, text='Apply −I pulse', command=lambda: self.apply_k6221_output(-1))
        self.k6221_apply_negative_button.grid(row=0, column=10, sticky="ew", padx=(3, 0))
        readback = ttk.Frame(output)
        readback.grid(row=1, column=1, columnspan=8, sticky="w", pady=(4, 0))
        ttk.Label(readback, textvariable=self.k6221_readback_output_var, style='Metric.TLabel').grid(row=0, column=0, sticky='w', padx=(0, 12))
        self.k6221_compliance_state_label = ttk.Label(readback, textvariable=self.k6221_compliance_state_var, foreground='#666666', font=(self.ui_font_family, self.ui_font_size, 'bold'))
        self.k6221_compliance_state_label.grid(row=0, column=1, sticky="w", padx=(0, 12))
        ttk.Label(readback, textvariable=self.k6221_output_var, style='Metric.TLabel').grid(row=0, column=2, sticky='w')
        self.k6221_off_button = tk.Button(
            output,
            text="6221 stop now / zero",
            command=self.stop_k6221,
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=10,
            pady=3,
        )
        self.k6221_off_button.grid(row=1, column=9, columnspan=2, sticky="w", padx=(10, 0), pady=(4, 0))
        source_fields(2, 'Avtech', (('|V| V:', self.avtech_amplitude_var), ('Width ns:', self.avtech_width_var), ('Pulse count:', self.avtech_count_var)))
        self.avtech_apply_button = ttk.Button(output, text='Apply +V pulse', command=lambda: self.apply_avtech_pulse(1))
        self.avtech_apply_button.grid(row=2, column=9, sticky="ew", padx=(10, 3), pady=(6, 0))
        self.avtech_apply_negative_button = ttk.Button(output, text='Apply −V pulse', command=lambda: self.apply_avtech_pulse(-1))
        self.avtech_apply_negative_button.grid(row=2, column=10, sticky="ew", padx=(3, 0), pady=(6, 0))
        ttk.Label(output, textvariable=self.avtech_output_var, style='Metric.TLabel').grid(row=3, column=1, columnspan=8, sticky='w', pady=(4, 0))
        self.avtech_off_button = tk.Button(
            output,
            text="Avtech output off",
            command=self.avtech_output_off,
            bg=THEME_COLORS["danger"],
            fg="white",
            activebackground=THEME_COLORS["danger_pressed"],
            activeforeground="white",
            padx=10,
            pady=3,
        )
        self.avtech_off_button.grid(row=3, column=9, columnspan=2, sticky="w", padx=(10, 0), pady=(4, 0))
        ttk.Label(output, text='6221: DC unipolar pulse output (0 A ↔ ±I, 50% duty)', style='Muted.TLabel').grid(row=4, column=0, columnspan=11, sticky='w', pady=(6, 0))
        scan_pair = ttk.Frame(outer)
        scan_pair.grid(row=2, column=0, sticky="ew", pady=(7, 0))
        scan_pair.columnconfigure(1, weight=1)
        scan = ttk.LabelFrame(scan_pair, text='Pulse sign scan (display, raw + processed TIFF after each pulse)', padding=7)
        scan.grid(row=0, column=0, sticky="nsew")
        scan.columnconfigure(11, weight=1)
        self.cidwm_scan_source_entries = {"6221": [], "avtech": []}
        for row, (source, name, fields) in enumerate((
            ("6221", "6221:", (("|I| mA:", self.cidwm_scan_current_var, 7),
                               ("Width µs:", self.k6221_width_var, 7))),
            ("avtech", "Avtech:", (("|V| V:", self.cidwm_scan_amplitude_var, 7),
                                   ("Width ns:", self.avtech_width_var, 7))),
        )):
            ttk.Label(scan, text=name).grid(row=row, column=0, sticky="w", padx=(0, 6))
            for column, (label, variable, width) in enumerate(fields):
                ttk.Label(scan, text=label).grid(row=row, column=1 + 2 * column, sticky='e', padx=(0 if column == 0 else 10, 3))
                entry = ttk.Entry(scan, textvariable=variable, width=width)
                entry.grid(row=row, column=2 + 2 * column, sticky="w", pady=(0, 2))
                self.cidwm_scan_source_entries[source].append(entry)
        common = ttk.Frame(scan)
        common.grid(row=2, column=0, columnspan=12, sticky="w", pady=(2, 0))
        for column, (label, variable, width) in enumerate((
            ("Pulses:", self.cidwm_scan_pulses_var, 7),
            ("Signs:", self.cidwm_scan_signs_var, 14),
            ("Wait after pulse s:", self.cidwm_scan_wait_var, 6),
        )):
            ttk.Label(common, text=label).grid(row=0, column=2 * column, sticky='e', padx=(0 if column == 0 else 10, 3))
            ttk.Entry(common, textvariable=variable, width=width).grid(row=0, column=2 * column + 1, sticky='w')
        buttons = ttk.Frame(scan)
        buttons.grid(row=3, column=0, columnspan=12, sticky="w", pady=(4, 0))
        ttk.Label(buttons, text="Pulse source:").grid(row=0, column=0, padx=(0, 3))
        self.cidwm_scan_source_buttons = []
        for column, (value, text) in enumerate((("6221", "6221"), ("avtech", "Avtech")), 1):
            button = ttk.Radiobutton(buttons, text=text, value=value, variable=self.cidwm_scan_source_var, command=self._update_k6221_controls)
            button.grid(row=0, column=column, padx=(0, 6))
            self.cidwm_scan_source_buttons.append(button)
        self.cidwm_scan_start_button = ttk.Button(buttons, text='Choose folder and start scan', command=self.start_cidwm_pulse_scan)
        self.cidwm_scan_start_button.grid(row=0, column=3, padx=(10, 3))
        self.cidwm_scan_stop_button = ttk.Button(buttons, text='Stop', command=self.stop_cidwm_pulse_scan, state='disabled')
        self.cidwm_scan_stop_button.grid(row=0, column=4, padx=(3, 0))
        ttk.Label(
            scan,
            text="Signs: + and - per pulse, repeated to fill Pulses (+- alternates, ++-- goes in pairs)",
            style="Muted.TLabel",
        ).grid(row=4, column=0, columnspan=12, sticky="w", pady=(4, 0))
        ttk.Label(scan, text="6221: compliance from its pulse output; the width boxes are the pulse outputs' own", style='Muted.TLabel').grid(row=5, column=0, columnspan=12, sticky='w')
        scan_status = ttk.Label(scan, width=1)
        scan_status.grid(row=6, column=0, columnspan=12, sticky="ew", pady=(2, 0))
        show_trimmed(scan_status, self.cidwm_scan_status_var)
        difference_box = self._build_moke_difference_box(scan_pair)
        difference_box.grid(row=0, column=1, sticky="nsew", padx=(7, 0))
        self._arrange_pair_by_width(scan_pair, scan, difference_box, gap=7)
        moke = ttk.Frame(outer)
        moke.grid(row=3, column=0, sticky="ew", pady=(7, 3))
        moke.columnconfigure(0, weight=1)
        images = ttk.LabelFrame(moke, text="Images", padding=7)
        images.grid(row=0, column=0, sticky="nsew")
        self.cidwm_save_images_button = ttk.Button(images, text='Save images', command=self.save_cidwm_images)
        self.cidwm_save_images_button.grid(row=0, column=0, sticky="w")
        ttk.Label(
            images,
            text="The current display (8-bit PNG), the raw 16-bit TIFF and the "
                 "difference raw image (float32 TIFF), into the folder you choose",
            style="Muted.TLabel",
        ).grid(row=1, column=0, sticky="w", pady=(4, 0))
        camera_settings = ttk.LabelFrame(outer, text="Camera settings", padding=4)
        camera_settings.grid(row=4, column=0, sticky="ew", pady=(0, 4))
        camera_settings.columnconfigure(0, weight=1)
        self._build_moke_display_controls(camera_settings).grid(row=0, column=0, sticky="ew")
        outer.rowconfigure(5, weight=1)
        ttk.Label(outer, textvariable=self.k6221_status_var, style='Status.TLabel', anchor='w').grid(row=6, column=0, sticky='ew', pady=(7, 0))
        self._update_k6221_controls()
    def _populate_roi_nudge_toolbar(self, parent: ttk.Frame, command: Callable[[str], None], button_store: list[tk.Widget], *, initial_state: str='normal') -> None:
        groups = (('A', 'rotate_left', 'rotate_right'), ('W', 'width_minus', 'width_plus'), ('H', 'height_minus', 'height_plus'), ('X', 'move_left', 'move_right'), ('Y', 'move_up', 'move_down'))
        for index, (axis, minus_action, plus_action) in enumerate(groups):
            group = ttk.Frame(parent)
            group.pack(side="left", padx=(0 if index == 0 else 5, 0))
            ttk.Label(group, text=axis, style="Muted.TLabel").pack(side="left")
            for symbol, action in (("−", minus_action), ("+", plus_action)):
                button = ttk.Button(group, text=symbol, width=2, style='Compact.TButton', state=initial_state, command=lambda selected=action: command(selected))
                button.pack(side="left", padx=(2, 0))
                button_store.append(button)
    def build_channel(self, parent, channel: int, row: int, column: int) -> None:
        panel = ttk.LabelFrame(parent, text=f"LED channel {channel}", padding=7)
        panel.grid(row=row, column=column, sticky="nsew", padx=0, pady=3)
        panel.columnconfigure(0, weight=1)
        variables: dict[str, tk.Variable] = {
            "i": tk.IntVar(value=0),
            "m": tk.StringVar(value="Off"),
            "p": tk.IntVar(value=5),
            "g": tk.IntVar(value=0),
            "d": tk.IntVar(value=5),
            "f": tk.IntVar(value=0),
        }
        self.channel_vars[channel] = variables
        primary = ttk.Frame(panel)
        primary.grid(row=0, column=0, sticky="ew")
        primary.columnconfigure(5, weight=1)
        ttk.Label(primary, text="Current:").grid(row=0, column=0)
        ttk.Spinbox(primary, from_=0, to=CURRENT_LIMIT, textvariable=variables['i'], width=9).grid(row=0, column=1, padx=(0, 10))
        ttk.Label(primary, text="Mode:").grid(row=0, column=2)
        ttk.Combobox(primary, textvariable=variables['m'], values=tuple(MODE_LABEL_TO_VALUE), state='readonly', width=7).grid(row=0, column=3, padx=(0, 10))
        actions = ttk.Frame(primary)
        actions.grid(row=0, column=5, sticky="e")
        apply_button = ttk.Button(actions, text='Apply', style='Strong.TButton', width=8, command=lambda selected=channel: self.apply_channel(selected))
        apply_button.pack(side="left", padx=(0, 3))
        self.action_widgets.append(apply_button)
        query_button = ttk.Button(actions, text='Query', width=8, command=lambda selected=channel: self.query_channel(selected))
        query_button.pack(side="left")
        self.action_widgets.append(query_button)
        advanced = ttk.Frame(panel)
        advanced.grid(row=1, column=0, sticky="w", pady=(7, 0))
        self.raw_parameter_frames.append(advanced)
        ttk.Label(advanced, text='Advanced:', style='Muted.TLabel').grid(row=0, column=0, padx=(0, 2))
        for index, parameter in enumerate(("p", "g", "d", "f")):
            ttk.Label(advanced, text=f'{parameter}=').grid(row=0, column=1 + index * 2)
            entry = ttk.Entry(advanced, textvariable=variables[parameter], width=6)
            entry.grid(row=0, column=2 + index * 2, padx=(0, 7))
            self.raw_entries.append(entry)
        advanced.grid_remove()
    def toggle_led_log(self) -> None:
        visible = not bool(self.led_log_visible_var.get())
        self.led_log_visible_var.set(visible)
        if visible:
            self.led_log_frame.grid()
            self.led_outer.rowconfigure(6, weight=1)
            self.led_outer.rowconfigure(7, weight=0)
            self.led_log_toggle_button.configure(text="Hide log")
        else:
            self.led_log_frame.grid_remove()
            self.led_outer.rowconfigure(6, weight=0)
            self.led_outer.rowconfigure(7, weight=1)
            self.led_log_toggle_button.configure(text="Show log")
    def attach_motor(self, motor_app_class) -> None:
        self.motor_app_class = motor_app_class
        self.motor_app = motor_app_class(self.motor_tab, embedded=True)
        focus = self.__dict__.get("auto_focus")
        if focus is not None:
            self.motor_app.motion_stop_listeners.append(focus.motor_stopping)
        self._apply_commercial_look(self.motor_tab)
    def _apply_commercial_look(self, widget=None) -> None:
        if not isinstance(self.root, tk.Misc):
            return
        style = ttk.Style(self.root)
        apply_look_to_tree(widget or self.root, style)
        if widget is None and self.__dict__.get("connection_overview") is None:
            try:
                self.connection_overview = ConnectionOverview(self.root, self.notebook, pad=self._ui_px(6, 4))
            except Exception as error:
                self.connection_overview = None
                print(f"Connection overview not shown: {error}", file=sys.stderr)
            self.notebook.bind("<<NotebookTabChanged>>", self._apply_look_to_shown_page, add="+")
    def _apply_look_to_shown_page(self, _event=None) -> None:
        try:
            shown = self.notebook.nametowidget(self.notebook.select())
        except (tk.TclError, KeyError):
            return
        apply_look_to_tree(shown, ttk.Style(self.root))
    def _set_camera_dependent_controls(self, enabled: bool) -> None:
        state = "normal" if enabled else "disabled"
        for button in self.difference_mode_buttons:
            button.configure(state=state)
        for button in self.difference_clim_buttons:
            button.configure(state=state)
        for button in (*self.difference_capture_buttons, *self.objective_100x_marker_buttons):
            button.configure(state=state)
        for button in self.camera_video_buttons:
            button.configure(state=state)
        focus = self.__dict__.get("auto_focus")
        if focus is not None:
            focus.set_camera_ready(enabled)
    def _update_camera_launcher_controls(self) -> None:
        has_window = self.camera_window is not None
        if self.camera_connect_button is not None:
            self.camera_connect_button.configure(state='disabled' if has_window else 'normal')
        if self.camera_disconnect_button is not None:
            self.camera_disconnect_button.configure(state='normal' if has_window else 'disabled')
        if self.camera_show_button is not None:
            self.camera_show_button.configure(state='normal' if self.camera_connected and (not self.camera_window_visible) else 'disabled')
        if self.camera_hide_button is not None:
            self.camera_hide_button.configure(state='normal' if self.camera_connected and self.camera_window_visible else 'disabled')
    def connect_camera(self) -> None:
        if self.camera_window is not None:
            return
        if self._camera_still_releasing():
            messagebox.showwarning(
                "Camera connection",
                "The camera is still being released: its last acquisition thread waits for the frame it is "
                "exposing (up to 10 s). Connect again once the Camera status says \"Camera not connected\".",
                parent=self.root,
            )
            return
        self.camera_connected = False
        self.camera_window_visible = False
        self.camera_window_status_var.set("Connecting to the PCO camera and waiting for the first frame…")
        if self.camera_connect_button is not None:
            self.camera_connect_button.configure(state="disabled")
        try:
            camera = TkCameraWindow(self.root, self)
        except BaseException as error:
            self.camera_start_failed(error)
            messagebox.showerror("Camera connection failed", str(error), parent=self.root)
            return
        self.attach_camera(camera)
    def attach_camera(self, camera_window) -> None:
        self.camera_window = camera_window
        try:
            camera_window.worker.set_difference_display_average(
                int(self.difference_temporal_average_var.get()),
                int(self.difference_spatial_binning_var.get()),
                int(self.difference_mean_filter_var.get()),
            )
        except (TypeError, ValueError, OverflowError, tk.TclError):
            self._restore_difference_display_average_vars()
        try:
            exposure_ms = float(self.camera_exposure_ms_var.get().strip())
            if not math.isclose(exposure_ms, camera_window.worker.active_exposure_ms(), rel_tol=1e-09):
                camera_window.worker.request_exposure_ms(exposure_ms)
        except (TypeError, ValueError, AttributeError, tk.TclError):
            self.camera_exposure_ms_var.set(f'{camera_window.worker.active_exposure_ms():g}')
        camera_window.set_100x_marker_visible(self.objective_100x_marker_visible)
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        self.camera_window_status_var.set("Connecting to the PCO camera and waiting for the first frame…")
        self._set_camera_dependent_controls(False)
        self._update_camera_launcher_controls()
        self._update_moke_roi_controls()
    def camera_connection_ready(self) -> None:
        if self.camera_window is None:
            return
        self.camera_connected = True
        self._set_connection_indicator("camera", True)
        self._set_camera_dependent_controls(True)
        self.difference_status_var.set("Difference mode: off")
        self.camera_window_visibility_changed(self.camera_window_visible)
    def camera_start_failed(self, error: BaseException) -> None:
        for running, event, page in (
            (self.magnet_scan_running, self.magnet_scan_stop_event, "magnet"),
            (self.keithley_scan_running, self.keithley_stop_event, "keithley"),
            (self.k6221_scan_running, self.k6221_stop_event, "cidwm"),
        ):
            if running:
                event.set()
                if not self.__dict__.get(f"{page}_scan_stop_reason"):
                    setattr(self, f"{page}_scan_stop_reason", "the camera failing")
                self._scan_log(f"{page}_scan_recorder", "stop_requested", button="the camera failing")
        failed_camera = self.camera_window
        self.camera_window = None
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        if failed_camera is not None:
            try:
                failed_camera.close()
            except BaseException:
                pass
            self._watch_camera_release(failed_camera, announce=False)
        self.camera_window_status_var.set(f'Camera start failed: {short_status_error(error, 100)}')
        self._set_camera_dependent_controls(False)
        self._update_camera_launcher_controls()
    def camera_window_visibility_changed(self, visible: bool) -> None:
        if self.camera_window is None:
            self.camera_window_visible = False
            self.camera_window_status_var.set("Camera not connected")
            self._update_camera_launcher_controls()
            return
        self.camera_window_visible = bool(visible)
        self.camera_window_status_var.set(
            "Camera acquiring · Camera Live window shown"
            if self.camera_connected and visible
            else "Camera acquiring · Camera Live window hidden"
            if self.camera_connected
            else "Connecting to the PCO camera and waiting for the first frame…"
        )
        self._update_camera_launcher_controls()
    def show_camera_live_window(self) -> None:
        camera = self.camera_window
        if camera is None or not self.camera_connected:
            messagebox.showwarning('Camera Live', 'Connect the camera and wait for the first frame first.', parent=self.root)
            return
        try:
            camera.show()
        except BaseException as error:
            self.camera_start_failed(error)
            messagebox.showerror("Camera Live", str(error), parent=self.root)
    def hide_camera_live_window(self) -> None:
        camera = self.camera_window
        if camera is not None:
            camera.hide()
    def disconnect_camera(self) -> None:
        camera = self.camera_window
        if camera is None:
            return
        if self.magnet_scan_running or self.keithley_scan_running or self.k6221_scan_running:
            messagebox.showwarning('Disconnect camera', 'A field, voltage or pulse scan is running; the camera cannot be disconnected.', parent=self.root)
            return
        if camera.video_recorder is not None or self.camera_video_stopping:
            messagebox.showwarning('Disconnect camera', 'Stop and save the Camera Live recording first.', parent=self.root)
            return
        self.camera_window_status_var.set("Stopping acquisition and disconnecting the camera…")
        self.camera_window = None
        try:
            camera.close()
        except BaseException as error:
            self.append_log(f"Camera disconnect warning: {error}")
            messagebox.showerror("Disconnect camera", str(error), parent=self.root)
        self.camera_connected = False
        self.camera_window_visible = False
        self._set_connection_indicator("camera", False)
        self._set_camera_dependent_controls(False)
        self.clear_camera_roi()
        self.difference_status_var.set("Camera not connected")
        self.camera_window_status_var.set('Camera still releasing (waiting for its last frame)…' if self._watch_camera_release(camera) else 'Camera not connected')
        self._update_camera_launcher_controls()
    def _camera_still_releasing(self) -> bool:
        worker = self.__dict__.get("camera_releasing_worker")
        return worker is not None and worker.releasing
    def _watch_camera_release(self, camera, announce: bool = True) -> bool:
        worker = getattr(camera, "worker", None)
        if worker is None or not getattr(worker, "releasing", False):
            return False
        self.camera_releasing_worker = worker
        self.append_log('Camera: its acquisition thread still holds the camera (a frame is being exposed); Connect waits until it has let go')
        def check() -> None:
            if self.closing or self.__dict__.get("camera_releasing_worker") is not worker:
                return
            if worker.releasing:
                try:
                    self.root.after(CAMERA_RELEASE_POLL_MS, check)
                except tk.TclError:
                    pass
                return
            self.camera_releasing_worker = None
            self.append_log("Camera released by its acquisition thread")
            if announce and self.camera_window is None:
                self.camera_window_status_var.set("Camera not connected")
            self._update_camera_launcher_controls()
        try:
            self.root.after(CAMERA_RELEASE_POLL_MS, check)
        except tk.TclError:
            pass
        return True
    def _on_notebook_tab_changed(self, _event=None) -> None:
        if self.closing:
            return
        try:
            self.root.after_idle(self._redraw_active_tab)
        except tk.TclError:
            pass
    def _redraw_active_tab(self) -> None:
        if self.closing or self.notebook is None:
            return
        try:
            selected = self.notebook.nametowidget(self.notebook.select())
        except (KeyError, tk.TclError):
            return
        self._redraw_live_intensity_plots()
        if selected is self.difference_tab:
            self._redraw_moke_plot()
        elif selected is self.keithley_tab:
            self._redraw_keithley_plot()
    @contextmanager
    def camera_render_paused(self, reason: str):
        camera = self.pause_camera_rendering(reason)
        try:
            yield
        finally:
            self.resume_camera_rendering(camera)
    def pause_camera_rendering(self, reason: str):
        camera = self.camera_window
        if camera is not None:
            camera.pause_rendering(reason)
        return camera
    @staticmethod
    def resume_camera_rendering(camera) -> None:
        if camera is not None:
            camera.resume_rendering()
    @staticmethod
    def write_csv_exports(exports) -> None:
        for path, header, rows in exports:
            destination = Path(path)
            destination.parent.mkdir(parents=True, exist_ok=True)
            with destination.open("x", newline="", encoding="utf-8-sig") as file:
                writer = csv.writer(file)
                writer.writerow(header)
                writer.writerows(rows)
    @staticmethod
    def write_parameter_log(path: Path, text: str) -> None:
        destination = Path(path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        with destination.open("x", encoding="utf-8", newline="\n") as file:
            file.write(text)
    @staticmethod
    def format_parameter_log(title: str, parameters: dict[str, object]) -> str:
        lines = [title, f"log_saved_local={datetime_module.datetime.now().isoformat(timespec='seconds')}"]
        for key, value in parameters.items():
            if isinstance(value, bool):
                rendered = "true" if value else "false"
            elif value is None:
                rendered = "none"
            elif isinstance(value, float):
                rendered = f"{value:.12g}"
            else:
                rendered = str(value)
            lines.append(f"{key}={rendered}")
        return "\n".join(lines) + "\n"
    def camera_scan_parameter_snapshot(self, roi) -> dict[str, object]:
        camera = self.camera_window
        frame = None if camera is None else camera.latest_frame
        parameters: dict[str, object] = {}
        if roi is not None:
            for key in ("cx", "cy", "w", "h", "angle"):
                parameters[f"roi.{key}"] = float(roi[key])
        if frame is None:
            parameters["camera.frame_available"] = False
            return parameters
        raw = np.asarray(frame.raw)
        parameters.update(
            {
                "camera.frame_available": True,
                "camera.raw_dtype": str(raw.dtype),
                "camera.raw_width_px": int(raw.shape[1]) if raw.ndim == 2 else -1,
                "camera.raw_height_px": int(raw.shape[0]) if raw.ndim == 2 else -1,
                "camera.exposure_ms": float(frame.exposure_ms),
                "camera.background_enabled": bool(frame.background_enabled),
                "camera.background_mode": str(frame.background_mode),
                "camera.temporal_average_frames": int(
                    frame.temporal_average_count
                ),
                "camera.spatial_binning": int(frame.spatial_binning),
                "camera.mean_filter_size": int(frame.mean_filter_size),
                "camera.display_contrast_auto": bool(frame.contrast_auto),
            }
        )
        try:
            contrast_mode, active_clim = camera.worker.difference_contrast_state()
        except BaseException:
            contrast_mode, active_clim = "unknown", None
        parameters["camera.difference_clim_mode"] = contrast_mode
        parameters['camera.difference_clim'] = 'none' if active_clim is None else f'{float(active_clim[0]):.12g},{float(active_clim[1]):.12g}'
        return parameters
    @staticmethod
    def _snapshot_variable(variable, fallback: object = "unavailable") -> object:
        try:
            return variable.get()
        except (AttributeError, RuntimeError, tk.TclError):
            return fallback
    def moke_hardware_parameter_snapshot(self, phase: str) -> dict[str, object]:
        phase = str(phase).strip().lower().replace(" ", "_") or "snapshot"
        root = f"hardware.{phase}"
        parameters: dict[str, object] = {
            f"{root}.captured_local": datetime_module.datetime.now().isoformat(
                timespec="seconds"
            ),
            f"{root}.illumination.connection_summary": self._snapshot_variable(
                self.connection_var
            ),
            f"{root}.illumination.operation_status": self._snapshot_variable(
                self.operation_var
            ),
            f"{root}.illumination.connected": bool(self.controller.is_connected),
            f"{root}.illumination.configured_port": self._snapshot_variable(
                self.port_var
            ),
            f"{root}.illumination.connected_port": self.controller.port,
            f"{root}.illumination.protocol_baud": int(BAUD_RATE),
            f"{root}.illumination.protocol_format": "8-N-1",
            f"{root}.illumination.read_timeout_s": float(READ_TIMEOUT_S),
            f"{root}.illumination.write_timeout_s": float(WRITE_TIMEOUT_S),
            f"{root}.illumination.command_delay_s": float(COMMAND_DELAY_S),
            f"{root}.illumination.current_limit": int(CURRENT_LIMIT),
            f"{root}.illumination.global_continuous_current": self._snapshot_variable(
                self.global_current_var
            ),
            f"{root}.illumination.auto_readback": bool(
                self._snapshot_variable(self.auto_readback_var, False)
            ),
            f"{root}.illumination.advanced_parameter_edit_visible": bool(
                self._snapshot_variable(self.raw_edit_var, False)
            ),
            f"{root}.magnet.connection_summary": self._snapshot_variable(
                self.magnet_connection_var
            ),
            f"{root}.magnet.operation_status": self._snapshot_variable(
                self.magnet_status_var
            ),
            f"{root}.magnet.all_devices_connected": bool(
                self._magnet_devices_ready()
            ),
            f"{root}.magnet.physical_selector_gui": self._snapshot_variable(
                self.magnet_switch_var
            ),
            f"{root}.magnet.physical_selector_confirmed": str(
                self.magnet_switch_confirmed_label
            ),
            f"{root}.magnet.selected_channel_key": (
                self._selected_magnet_switch_key() or "none"
            ),
            f"{root}.magnet.safety_confirmed": bool(
                self._snapshot_variable(self.magnet_safety_var, False)
            ),
            f"{root}.magnet.auto_poll_enabled": bool(
                self._snapshot_variable(self.magnet_auto_poll_var, False)
            ),
            f"{root}.magnet.poll_interval_s": self._snapshot_variable(
                self.magnet_poll_interval_var
            ),
            f"{root}.magnet.poll_inflight": bool(self.magnet_poll_inflight),
            f"{root}.magnet.poll_consecutive_failures": int(
                self.magnet_poll_failures
            ),
            f"{root}.magnet.command_busy": bool(self.magnet_busy),
            f"{root}.magnet.scan_running": bool(self.magnet_scan_running),
            f"{root}.magnet.scan_active_channel_key": (
                self.magnet_scan_active_key or "none"
            ),
            f"{root}.magnet.current_limit_A": float(MAGNET_CURRENT_LIMIT_A),
            f"{root}.magnet.current_readback_abs_tolerance_A": float(
                MAGNET_CURRENT_READBACK_TOLERANCE_A
            ),
            f"{root}.magnet.current_readback_relative_tolerance": float(
                MAGNET_CURRENT_READBACK_REL_TOLERANCE
            ),
            f"{root}.magnet.protocol_baud": int(MAGNET_BAUD_RATE),
            f"{root}.magnet.protocol_format": "8-N-1",
            f"{root}.magnet.reply_deadline_s": float(MAGNET_REPLY_DEADLINE_S),
            f"{root}.magnet.query_attempts": int(MAGNET_QUERY_ATTEMPTS),
        }
        for channel in CHANNELS:
            variables = self.channel_vars.get(channel, {})
            channel_root = f"{root}.illumination.channel_{channel}"
            mode_label = self._snapshot_variable(variables.get('m'), 'unavailable')
            parameters.update(
                {
                    f"{channel_root}.gui_current": self._snapshot_variable(
                        variables.get("i")
                    ),
                    f"{channel_root}.gui_mode_label": mode_label,
                    f"{channel_root}.gui_mode_code": MODE_LABEL_TO_VALUE.get(
                        str(mode_label), "unavailable"
                    ),
                    f"{channel_root}.gui_p": self._snapshot_variable(
                        variables.get("p")
                    ),
                    f"{channel_root}.gui_g": self._snapshot_variable(
                        variables.get("g")
                    ),
                    f"{channel_root}.gui_d": self._snapshot_variable(
                        variables.get("d")
                    ),
                    f"{channel_root}.gui_f": self._snapshot_variable(
                        variables.get("f")
                    ),
                }
            )
        for key in ("OUT", "IN"):
            label = MAGNET_CHANNEL_LABELS[key]
            channel = self.magnet_channels[key]
            bop = channel.bop
            gauss = channel.gauss
            channel_root = f"{root}.magnet.{key}"
            parameters.update(
                {
                    f"{channel_root}.label": label,
                    f"{channel_root}.configured_BOP_port": self._snapshot_variable(
                        self.magnet_port_vars[f"{key}_BOP"]
                    ),
                    f"{channel_root}.configured_Gauss_port": self._snapshot_variable(
                        self.magnet_port_vars[f"{key}_GAUSS"]
                    ),
                    f"{channel_root}.BOP_connected": bool(
                        bop is not None and bop.connected
                    ),
                    f"{channel_root}.Gauss_connected": bool(
                        gauss is not None and gauss.connected
                    ),
                    f"{channel_root}.BOP_connected_port": (
                        None if bop is None else bop.port
                    ),
                    f"{channel_root}.Gauss_connected_port": (
                        None if gauss is None else gauss.port
                    ),
                    f"{channel_root}.BOP_output_armed": bool(
                        bop is not None and bop.output_armed
                    ),
                    f"{channel_root}.gui_target_current_A": self._snapshot_variable(
                        self.magnet_target_vars[key]
                    ),
                    f"{channel_root}.manual_step_A": self._snapshot_variable(
                        self.magnet_manual_step_vars[key]
                    ),
                    f"{channel_root}.cached_verified_current_A": self.magnet_last_currents[
                        key
                    ],
                    f"{channel_root}.gui_current_readback": self._snapshot_variable(
                        self.magnet_current_vars[key]
                    ),
                    f"{channel_root}.gui_field_readback": self._snapshot_variable(
                        self.magnet_field_vars[key]
                    ),
                    f"{channel_root}.is_selected_physical_path": bool(
                        self._selected_magnet_switch_key() == key
                    ),
                }
            )
        return parameters
    def _refresh_file_export_controls(self) -> None:
        for method_name in ('_update_magnet_scan_controls', '_update_keithley_controls', '_update_k6221_controls', '_update_nonlocal_keithley_controls'):
            method = getattr(self, method_name, None)
            if method is not None:
                method()
    def submit_file_export(self, key: str, camera, work: Callable[[], object], on_success: Callable[[object], None], on_error: Callable[[BaseException], None]) -> None:
        self.active_file_exports.add(key)
        self._refresh_file_export_controls()
        try:
            future = self.file_executor.submit(work)
        except BaseException as error:
            self.active_file_exports.discard(key)
            self._refresh_file_export_controls()
            self.resume_camera_rendering(camera)
            on_error(error)
            return
        def completed() -> None:
            try:
                if self.closing:
                    return
                try:
                    result = future.result()
                except BaseException as error:
                    on_error(error)
                else:
                    on_success(result)
            finally:
                self.active_file_exports.discard(key)
                if not self.closing:
                    self._refresh_file_export_controls()
                self.resume_camera_rendering(camera)
        future.add_done_callback(lambda _future: self.post_ui(completed))
    def latest_raw_image_snapshot(self, frame=None):
        if frame is None:
            camera = self.camera_window
            frame = None if camera is None else camera.latest_frame
        if frame is None or frame.raw is None:
            raise RuntimeError("The camera has not produced a raw frame to save yet")
        array = np.asarray(frame.raw)
        if array.dtype != np.uint16 or array.ndim != 2:
            raise RuntimeError(f'Unexpected camera raw frame format: dtype={array.dtype}, shape={array.shape}')
        return array.copy()
    def latest_display_image_snapshot(self, frame=None):
        camera = self.camera_window
        if camera is None:
            raise RuntimeError("The camera is not connected")
        if frame is None:
            frame = camera.latest_frame
        displayed = getattr(camera, "latest_display", None)
        if displayed is None:
            raise RuntimeError('Camera Live has not drawn a frame yet; show Camera Live first')
        if frame is None or displayed[2] is not frame:
            raise RuntimeError('Camera Live has not drawn the newest frame (it is hidden, or paused while a file is saved); show Camera Live first')
        return self._compose_display_snapshot(displayed[0], displayed[1])
    @staticmethod
    def _compose_display_snapshot(array, geometry):
        if array is None or geometry is None:
            raise RuntimeError("Camera Live has not produced a display image to save yet")
        array = np.asarray(array)
        if array.dtype != np.uint8 or array.ndim != 2:
            raise RuntimeError(f'Unexpected display image format: dtype={array.dtype}, shape={array.shape}')
        offset_x, offset_y, canvas_width, canvas_height = geometry
        snapshot = np.zeros((canvas_height, canvas_width), dtype=np.uint8)
        paste_height = min(array.shape[0], canvas_height - offset_y)
        paste_width = min(array.shape[1], canvas_width - offset_x)
        if paste_height <= 0 or paste_width <= 0:
            raise RuntimeError("The display image canvas size is invalid")
        snapshot[offset_y:offset_y + paste_height, offset_x:offset_x + paste_width] = array[:paste_height, :paste_width]
        return snapshot
    def latest_processed_image_snapshot(self, frame=None):
        if frame is None:
            camera = self.camera_window
            frame = None if camera is None else camera.latest_frame
        if frame is None or frame.display_difference is None:
            raise RuntimeError("Enable plain or drift-tracking difference first and wait for one processed frame")
        array = np.asarray(frame.display_difference, dtype=np.float32)
        if array.ndim != 2 or not np.all(np.isfinite(array)):
            raise RuntimeError(f'Unexpected processed image format: dtype={array.dtype}, shape={array.shape}')
        settings = {'mode': frame.background_mode, 'temporal_count': frame.temporal_average_count, 'spatial_binning': frame.spatial_binning, 'mean_filter_size': frame.mean_filter_size}
        return array.copy(), settings
    @staticmethod
    def processed_image_settings_suffix(settings) -> str:
        mode = "TrackingDiff" if settings["mode"] == "tracking" else "PlainDiff"
        return (
            f"{mode}_Avg{int(settings['temporal_count'])}_"
            f"Bin{int(settings['spatial_binning'])}x"
            f"{int(settings['spatial_binning'])}_"
            f"Mean{int(settings['mean_filter_size'])}x"
            f"{int(settings['mean_filter_size'])}"
        )
    def save_current_display_image(self, source: str) -> None:
        export_key = f"display-image:{source}"
        if export_key in self.active_file_exports:
            self.operation_var.set(f"{source} display image is still being saved; please wait")
            return
        camera = self.pause_camera_rendering(f"Saving {source} display image")
        try:
            snapshot = self.latest_display_image_snapshot()
        except BaseException as error:
            self.resume_camera_rendering(camera)
            messagebox.showwarning("Save display image", str(error), parent=self.root)
            return
        timestamp = datetime_module.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        selected = filedialog.asksaveasfilename(
            parent=self.root,
            title=f"Save {source} current Camera Live display image (no overlays)",
            defaultextension=".png",
            initialfile=f"{source}_CameraLive_display8_{timestamp}.png",
            filetypes=(("PNG image", "*.png"), ("All files", "*.*")),
        )
        if not selected:
            self.resume_camera_rendering(camera)
            return
        destination = Path(selected)
        self.operation_var.set(f"Saving {source} display image in the background…")
        def work():
            save_display_u8_png(snapshot, destination)
            return destination
        def failed(error: BaseException) -> None:
            self.operation_var.set(f"{source} display image save failed")
            self._dialog_after_drain("showerror", "Save display image failed", str(error))
        def saved(path: Path) -> None:
            self.operation_var.set(f"{source} display image saved")
            self._dialog_after_drain('showinfo', 'Save display image', f'Saved the current Camera Live 8-bit display image (no overlays):\n{path}')
        self.submit_file_export(export_key, camera, work, saved, failed)
